-- 202609280001_import_woody_reports_2021_2022.sql
--
-- 把 2021-09-12 ~ 2022-12-25 的 Woody 週報（62 篇）補進 woody_reports。
-- 來源：woody.comart@gmail.com，主旨 `Woody 週報` 的寄件備份。平台原本最早只到 2023-01-01。
--
-- 🔴 日期用「信件內文標示的報告日」而非寄出日 —— 有 11 篇是前一天晚上寄的
--    （例：2021-11-19 21:05 寄出、內文寫 2021.11.20），用寄出日會錯開一天。
-- 🔴 每封信在信箱裡都有兩份（同一時間戳、兩個 thread id，因為這個 Gmail 同時收
--    woody@comart.com.tw 與 woody@peripower.com 兩條路徑），已去重。
-- 🔴 信末的「願景／使命／價值觀」與「知識學習平台」清單**沒有**匯入：那是 board/index.html
--    的 WR_OKR／WR_LEARN 常數，由樣板自己渲染，存進資料庫會變成重複顯示。
-- 🔴 id 由報告日期雜湊產生（非隨機），配合下方的 NOT EXISTS，這支 migration 重跑不會重複新增。
--
-- 對應：work=本週工作 plan=下週計畫 reflections=心得思考 intel=視野情報
--       feedback=團隊回饋 other=其他資訊（開場白、交代事項、週報分享辦法）

