軍徽 視野情報：限电的背后其实是大宗商品价格的疯涨，随之而来的是各个行业原材料成本的上涨，运费成本的大涨。大宗商品好涨价，但加工成的商品却很难涨价。这就导致很多企业虽然看起来很忙很赶货，其实利润却微乎其微。这就使得企业要想生存，必须得进行产业升级，降低能耗。

陶莎 心得思考：近期各材料暴涨，国家着手调控，有一部份原因是产能过剩，让我不禁想到「内卷」一词。学生争相课外辅导，就会增加压力失去内驱力和创造力，职场打工人为了博好感，低效率工作而去加班，势必影响管理考核机制；疫情复工复产，国内各生产商拼命扩产、抢市场，恶性竞争、原材料价格上涨，产能上升，但出口价没升，在既没有材料定价权也没有国外终端市场定价权的情况下，生产越多，能耗和资源浪费也就越多，现在无论国家怎么调控，都是一场博弈，每个人、每个企业都将被裹挟到这场经济战斗中。

→ 這已到不可迴避的程度了，確實需要檢討，下週四會議討論

李立 心得思考：在OKR 中有：目标是自下而上的由量化指标形式呈现的）在执行中不断的收集实际值，将实际值同计划值进行比较，如果发生偏差分析偏差产生的原因，制定纠偏措施，执行纠偏措施。

豔梅 心得思考：刘先生上周提及的OKR，完成目标的四个策略中的「连结部门协作」，对实际工作非常重要！这与我们的企业价值观中的「团队」同理，如果大家都能切实执行，互相配合，相信大家的工作效率都会有所提升，验厂也会变成大家 OKR考核中「我要做的事」，而不仅仅是DCC的事。

→ 是的，完成大家共同的目標，隨時檢討，有效控管達成目標的進度，肯定是一個原因，另外，也是要聚焦「做最重要的事」。

李美玲、林森 視野情報：9月24 日有消息称欧盟立法强制推行通用充电器，所有智能手机、平板电脑、相机、耳机、便携式扬声器以及手持电子游戏机都将采用统一标准接口以支持通用充电器。$wr$, $wr$$wr$,
