・新產品佈局，分工 and 年度 roadmap 檢討$wr$, $wr$商周文章啟發。60年前，如果你告訴一個農夫，以後的人只要坐在桌上敲敲鍵盤就可以生活，他一定會認為你瘋了，30 年前，你也不會相信每個人手上拿一塊玻璃，就可以掌控全世界的資訊，那 30 年後的人看待今天的我們，會不會是另外一種「農夫」或「無知之徒」？現在的我們，要如何改變？！走老路，必然無法到達願景之地。$wr$,
       $wr$文千分享：社交媒体购物进步发展、内容营销成为一大趋势、AR和VR体验将更受到欢迎，都帶出一個新的命題：metaverse，元宇宙。

元宇宙一詞由前綴「meta」和詞幹「verse」組成；這個詞通常用來描述未來網際網路迭代的概念，由連接到一個可感知的虛擬宇宙的持久、共享的3D 虛擬空間組成。廣義上的元宇宙不僅指虛擬世界，還指整個網際網路，包括增強現實的整個範圍。

未來的世界將是現實與虛擬世界的融合，顛覆現有的認知，將會存在平行世界。我們會在哪裡？$wr$, $wr$Kimi & Vivi：中國大陸今年為了遏制碳排放，加強落實「能耗雙控」，意即同時控制能源消耗的「總量」與「強度」，對諸多產業造成衝擊。能量消耗總量，是指在一定時間內消耗的能源總量；能源消耗強度，則是指單位 GDP的能源消耗量。這項政策並非近期才推出，早在2006 年提出的《中國國民經濟和社會發展第十一個五年規劃綱要》中，中國當局就將能耗強度作為指標，並納入「十三五規劃」（第十三個五年，即2016年至2020 年）政策中。由於中國每年都會設定全國能耗總量目標，再分拆給各省、各地區執行，因此各地能耗標準皆不同。

→ 也是 OKR

Esther 品牌分享：其實很感概我們從引導市場走到像競爭者學習, 感覺我們的核心能力消失了, 而變成也只是在鑽研為何我們比人家報價貴, 客人不接受, 但要是我們若能核心能力可以加深, 推出市場WANT的產品, 就算貴也是有客人買單的, 而不是現在一毛一毛的斤斤計較被客人殺價

→ Never too late..

李立：在日常的工作中我们经常提到创新。创新我们可以理解为横向和纵向，横向就是与同行业和社会上其他行业比较属于创新--这个是大范围的，纵向就是在公司内部进行比较，以前没有出现过现在有了新的，这个就是小范围的。

→ 謝謝。多看看外部環境，只要是對我們好的，而我們現在沒有的，採納使用，就是創新

Amy：国有国法，家有家规，生而为人，不可漠视规矩。也许你会认为守规矩可能会很吃亏，但是实际上，这个世界其实还是公平的，守规矩才是最稳妥的一条出路。不守规矩的人确实会在短期内获得利益，但是从他不守规矩的那一刻开始会为此付出一定的代价，甚至可能会发展为惨痛的。

→ 天理昭彰，報應不爽$wr$, $wr$下週起，本週報格式開放給本文所有收件者，「建議」可改用此格式，不限主管。謝謝。

ps.「團隊反饋」該欄為我專屬，不需要寫。$wr$,
