insert into public.woody_reports
  (id, report_date, work, plan, reflections, intel, feedback, other, author_id, author_name, created_at, updated_at)
select $wr$b0000000cae6tij$wr$, $wr$2021-10-10$wr$, $wr$・磁鐵廠商與運用探討
・PM 系統檢討
・新創總會課程$wr$, $wr$・年度 roadmap 檢討
・PM 分工確認
・OKR 專案顧問討論$wr$, $wr$事情有四種：緊急又重要、緊急但不重要、不緊急但重要、不緊急又不重要。

我們通常優先處理哪一種？

我的觀察是以上皆非，工作者通常會優先處理的是，簡單容易不用思考的事情，但這些事情很可能是第四種，且耗費時間，因此，很容易淪為看起來忙碌，但成就甚微。

近日在導 OKR 更能體會這個系統的精義，日後如我問大家，OKR 是什麼？請大家回答我：「做最重要的事」$wr$,
       $wr$借用趙燦分享：在下一个10年或20年，气候变化对经济造成的破坏，不亚于每隔10 年爆发一次的流行病。能源创新是一个巨大结构性变化，会重塑整个制造业，同时改变我们的经济基础及生活方式。未来的产品一定会将环保列为一项重要的指标。

近來的限電、原物料成本飆升、通膨，都與此議題相關，不得不慎。$wr$, $wr$艷梅：

所有的企业都在转型，无论是从过去的生产制造向品牌转型，还是从单一的产品向解决方案转型，亦或是从独立经营向平台型组织转型，但是所有的企业都殊途同归，面临着数字化转型。

在整个数字化转型的过程中最关键的是数据积累，数据和数字化就像太极阴阳一样相辅相成。

在最近的 COSTCO QMS+ GMP 验厂中，审核员提出「工厂没有保留培训需求调查的记录」，要求详细到对每一个一线员工进行书面调查及保留记录，调查后制定培训计划才更有实操性。现在基本上，人人有手机，个个有网络，行政课可以考虑设置一份简单的网上电子调查问卷，员工可以直接网上提交，后台保留数据，方便快捷，这也是数字化转型的一种方式。

→ 請各單位文管、行政、HR、MIS 討論一下，OA 應有機會達成。

可欣：

「接班人計劃」開始執行
這次的經驗，提醒我開始啟動「接班人」計畫。在關鍵的職務上，必須要有備案，我們無法確保每一個員工會如自己預期的在該職務上效命效忠，為了不讓身為主管的我們陷入找無人交接的窘境，有規劃性的接班人計劃，對整個團隊來說是非常重要的。

→ 每個職務都要有接班人，從代理人開始設計。這不是心得，這是必要的政策。

雲丞：

網紅的生態，累積一定的知名度後，就會想要去將粉絲變現，那變現的方法有很多，可以接業配廣告等等，但跟我們銷售比較有相關的，大概可以分為幾類：

1. 團購/團媽：主要透過文字與粉絲溝通，常出現於FB社團或是Line。
2. 網紅/部落客：透過文字與圖片與粉絲溝通，銷售大多為導購/折扣碼的方式來作分潤。
3. 帶貨直播主：「直播帶貨」類似於「電視購物」商業模式，透過及時影像和觀眾互動來推銷商品，隨著科技發展，進而促成直播帶貨的風潮，近期因為疫情的緣故，大家更常使用網購平台購物，使得中國和台灣的的直播帶貨變得更加火熱。

→ 新通路年代，所有商務都要數位化，我們自己的思維也不應被限制，做就對了。加油。

振慈：

這周參加了與品牌顧問的餐敘交流，針對之前所提出的問題，顧問提出了解答，問：促銷活動的頻率和策略該如何制訂，才不會損害品牌價值以及影響消費者對品牌的定價認知。答：促銷活動和折扣若是限時、限量、限地、限款，若有這四個條件，那基本上是不會因為有折扣而影響品牌形象的，Jennifer 補充，網路上的折扣活動通常會跟著平台做大型活動的促銷，Jamie 也補充通路上的折扣會依照款式而有所不同，一般的基本款項通常不會有折扣，有折扣的都是一些庫存品。每次跟不同的品牌顧問接觸，都會有不一樣的收穫，品牌說起來簡單，就是把產品印上 logo 賣出就好，但真正的品牌所內涵的精神和意義，以及所面臨到的環境和問題，才是我們必須思考和面對的。

→ 振慈自己提了答案：購物不再分線上線下，只剩品牌！

趙燦：

品质的稳定性是基于标准化作业的执行力的落实程度，完美的产品是设计及制造出来，并不是靠管控出来的，在执行生产制造过程中，品质的作用是监察是否按照预定的程序进行，以及偏离程序后的督导及通知执行单位进行调整。$wr$, $wr$$wr$,
