select $wr$b0000007blpqnqz$wr$, $wr$2021-10-17$wr$, $wr$・年度 roadmap 檢討
・PM 分工確認
・OKR 專案顧問討論$wr$, $wr$・新開案產品分析
・外購專案分工確認$wr$, $wr$Kai 提到：「近看開發中的產品會有許多疑點，但這疑點放至使用情境時，並不足以成為『缺點』。未來在判斷疑點是否為影響產品的缺點，會是個至關重要的學習，這將影響到產品的開發速度與產出。」

確實，產品總有適應的對象與族群，如要考慮「所有人的需求」與考量，終將會原地踏步走不出去。近日在使用 magsafe 卡片夾為例，其實極其不穩，容易掉落，昨天在外突然發現不知掉落何處（後來在背包內找到），就有同樣反思，如果是我們開發的產品，可能過程就會被不斷質疑，商品化之後也將面對客訴。

另外一個點是，品牌力也足以引領規格，（磁性卡套）這個產品是蘋果主推的規格，大家就會買單，客訴一定難免，但也有許多消費者可能不會責怪蘋果。$wr$,
       $wr$陶莎：近五年，国内医疗器械市场快速扩容，全球占比也逐步提升至2020年的22%，将近全球市场的1/4。新冠疫情全球蔓延期间，大多数产品出口额实现翻倍以上增长，为国产器械国际化奠定基础，其中「一带一路」国家在内的新兴市场是国产器械出口的重要区域。随着全国卫生投入增长、老龄化加剧、分级诊疗推进，消费升级和国产替代加速，从中长期看，中国医疗器械的发展空间巨大。华为腕部单导心电采集器获准生产，此外还有三款医疗器械进入优先审批程序，这意味着，华为正式进入医疗器械市场。

→ 以此思考，很有可能是我們下一波的機會，也是我們恒群廠的就地升級的契機，我們已有一些相關佈局，大家也可以思考一下相關領域發展的可能性。$wr$, $wr$湘平、軍徽：

节约成本和减少浪费，产线员工是我们最直接的人选，我们怎么给我们这些工人一个值得在乎和珍惜的理由呢？参考当责书本分享，了解员工的心和头脑，我们创造需求，让他们觉得他们是被需要的，不满足于机械式的工作方式，听命行事，遇到问题的时候，不是习惯性的找上层解决，而是进入解决问题的工作模式，自动负担起解决问题和节省成本的工作；在上次 110 球窝冷气出风口四爪插拔检验时，一直苦扰工程，PE 和品管的问题，产线为优化自己的生产和人力损失，已经找出最简单，最快速的办法。给他们有被需要的重视。

