商佑維：

為自動駕駛把關駕駛人監測系統（DMS）將大放異彩：

車輛安全科技的演進從車外走向車內，感測技術朝向整合車內駕駛人狀況與車外環境的方向發展，AI 的應用也不僅止於娛樂與便利，安全成為新的應用重點。受到各項 ADAS 系統搭載率快速攀升，導致不斷發生駕駛人依賴系統而忽視前方路況的事故，對駕駛人進行監測的功能再次受到重視。然而未來將往更加主動、可靠和精準的攝影機方案發展，進行瞳孔追蹤及特徵萃取來監測駕駛人疲勞、分心和不當駕駛行為。

明隆：

高階主管應為公司貢獻, 而不是來學習 -Morris Chang said... 解決問題而不是製造問題, 去開創而不是抱怨感嘆.... in my opinion.（Woody: 不限高階，各主管與資深同事亦然）

新鮮人不只要習得學校教育最好還要能（有系統 有計畫 有紀律）的終生學習. -Morris Chang said. 對事物培養獨立洞察分析能力

可欣、振慈：

人在一個環境久了，思考事情的方式都會被固定，甚至是不用思考，一些平常例行的小事，可以機械化的反應，不用思考其中該如何處理，怎麼處理會是最好、最有效率的，因為我們習慣了一種固定的模式。好的是我們可以很順暢地把事情完成，但我們就會忽略了每一次可能可以變得更好的機會。（振慈）

本週週會因為 Ashley 對於公司飲水機設備提出了新的想法所以給予鼓勵及表揚；的確在工作中因為做某些事情時間久了，思想就容易固化，有時覺得自己的「意見會被否決」，或是「這個行不通」、「規則就是如此」、「沒用的」等等，其實當別人提出的意見就算不夠專業也不要急著否絕，因為每個人出發的角度不一樣，看待問題也會不一樣，觀點也就不一樣，相對的自己也就會有不一樣的看見及找到可學習的地方，千萬別讓思想固化變成一種習慣。（可欣）

