・業務策略制定與團隊溝通$wr$, $wr$本週在企業經營班的上課，嚴格地說，新的資訊不多，但是看到成功的企業是如何用簡單的概念，制定目標、形成策略、凝聚團隊、共同成功，仍是深有所獲。

其中一個重要的概念在於，在團隊成員當中，到底是能力重要？還是意願重要？兩者搭配可以畫成一個二元四象限的座標圖，試問，哪一種人最有價值？最佳答案當然是有能力也有意願的人。於是，要如何調度有能力的人提升意願？以及有意願的人提升能力？自然是組織的挑戰。

ps. 老師的簡報中有這句話：「熱情是原動力，願景是熱情的源頭」。當以此為範，調整績效評核與激勵相關政策。$wr$,
       $wr$$wr$, $wr$涵暭：

Morris Chang 在玉山科技協會晚宴上的演講，分享了自己從年輕開始的工作經驗、學習及應用。TI 的工作經驗方面，他分享了在一家公司裡面各個功能部門的關鍵學習（從我的角度來解讀，是分屬不同部門的功能，但是他每一個功能都有涉獵），每一點都是重點帶過段段幾句，但是都讓人印象深刻而且值得深思，包括技術、產品、行銷、訂價、領導、策略、有說服力的簡報…等等。只取其其中幾點分享：

(1) 商品與客製品：搞清楚自己在生產的是商品還是客製品。商品的話，就是只要有兩家公司以上生產相似的產品，這就是商品，commodity，you don't need more than one competitor，一個就夠讓人應付了。客製品則是你要搞清楚你要做什麼，如果要多一點客製品，那就是策略問題。

(2) 行銷：非常重要，做為技術的 business unit head，他把行銷當作第一要務，如果只是 commodity，去看客人是沒有用的，是客製品才去看客人，而且要常常去看。

(3) 訂價：如果你賣的是 commodity，價錢不用說，it's not up to you，it's up to the competitors! 如果是客製品，那還有一點點空間。

→ 按照定義，我們做的就是 commodity, 我們的客製品，是毫無非我們不可的理由，按照 Morris 的說法，就是要採取「絕對的價格競爭策略」。

→ Now is our turning point, 是該改變的時刻了。

福威：

在工作中，培養自己的規範性。對於需要確認的事情，多發一遍郵件確認，不要口頭承諾。很多專案最後發現需求偏離，都是在口頭溝通結果，沒有任何檔確認。工作過程中，需要及時溝通，工作進度要進行階段回饋。若在執行過程中，沒有任何進度資訊，到最後發現問題，但為時已晚，讓自己也陷入被動。執行事情一定要有始有終，有的事情已經看到失敗了，也不要放棄不管，注意收尾，做最終的總結，吸取教訓。

文千：

因为外购品的关系，最近接触供应商比较多，我感觉供应商跟客户的角色都是互通的，其实流程面也都是一样的，只是角色的互换，但其实沟通方式都是一样的，而且对接供应商，现在也更能换位思考客户端的需求跟想法，感觉挺奇妙的。

我觉得供应商、客户、消费者这种上下游关系本身就是环环相扣，相辅相成缺一不可的，而且是共存亡的，消费者有需求才有市场，要在市场生存就必须要有好的产品，要好的产品就需要好的设计以及资源面的整体配合，所以平等的看待消费者、供应商跟客户，大家双赢才能共同生存。

→ 很好，多功能工作者，能夠體悟得更深更徹底，更多的同理跟認知。

→ 是的，我們必須充分考慮上下游的生存利基，多為廠商與客戶著想。

振慈：

這周看到公司要處理一些廢棄、無法再利用的主機和螢幕，請了回收公司的人員來收走，幾台的主機和螢幕，最後只剩台幣幾百元，這也讓我聯想到之前所分享過的《外商 CEO 內傷的每一天》這本書，其中內容提及有感的30%，書中舉例「假如你今天花了2萬元買了一隻手機，過了1-2 年後你會願意花多少錢買？」到目前聽說沒人願意花超過5千元，因為大家都會追求更新、更好、更美的手機，有感的「30%」是指，我們每年的改變必須要達30%，因為如果只是5-10%，那麼自己和周圍的人一定都無感，如果可以使自己達到30%的改變，那麼我們的思維、生活圈、習慣一定都會比那原來0% 的自己更好！最後作者也用一段話勉勵大家「別說自己不行。我們的皮膚每20-28 天就全部換新，全身的紅血球每四個月也會全部換新一次。每個人都有自我更新的能力，不是你能不能，重點是你要不要!」今年也即將快到尾聲，此刻的我們來到了幾%呢?

家瑩：

世界上的企業分兩種：擁有「Day 1」創業心態的和擁有「Day 2」停滯心態的公司。Day 1 是保有創業「第一天心態」，包含堅持以客戶為中心、不被工作流程綁架、盡早跟上新趨勢，提升決策速度且保有高品質；Day 2 則是企業隨著成長而不自覺走向停滯，一間成熟的公司可能停滯幾十年而不自知。

「每個工作者都是自己『人生有限公司』的 CEO」。在職場上，每個人都在想辦法優化自己的投入與產出，打造更好的產品與服務。而經營人生其實可以借鏡企業營運的管理哲學，目標與心態決定了一個人能走多遠，幫助自己提升個人思維、塑造良好的職涯道路。

→ 個人也是。我們是否能夠每天都是用「Day 1」心態做事？否則就是選擇了停滯。

雲丞：

棚割或棚割圖，是我最近認識的詞彙，來自日本的用詞，由於早年台灣零售業相關 Know How 來自日本老師或業界合作，因此一直沿用至今。棚-指貨架，割-則是在貨架上做適當的分割及配置，簡單地說，是將商品在貨架做適當配置的意思。因此如將商品配置表定義為『如何將不同品類，做一個最有效的分配，並用圖形或表格規劃繪製』，讓現場理貨員或店員輕易瞭解商品配置表的陳列及意義，叫棚割圖。

先前我們在陳列或是整理專櫃與貨架，大部分是依照業務的經驗與對產品的了解，來決定商品擺放的位置，但隨著新品推出或是門市人員的替不同，都有可能把我們的陳列重新組合，導致我們的品牌形象或是業績受到影響，為了日後能夠有專櫃的一致性，棚割圖非常適合讓我們運用，規劃成標準 SOP，讓業務和門市人員都能依照的標準來作業。

可欣：

因為工作性質的關係，常會接觸到不同領域的工作需要解決，當遇到不熟悉的業務內容，心中難免會有些恐懼與抗拒，擔心沒有資源沒有管道可以如期完成，但事情通常『看起來』都很困難，但實際執行後，會發現原來沒有想像中的困難；重點在於要先『開始行動』，因為不做就不知道困難在哪裡，不要著眼在困難的大小而裹足不前，只要開始行動，就會發現問題，有問題就去解決，自然而然就會有『進度』，不要怕錯不要怕做，做中學錯中學，問題自然就會被解決。$wr$, $wr$$wr$,
