select $wr$b0000002yekvt4z$wr$, $wr$2021-11-07$wr$, $wr$・立錡 Qi 電子廠商合作洽談
・台灣電子製造外包廠商拜訪
・業務策略制定與團隊溝通$wr$, $wr$・拜訪林口台灣電子代工廠
・拜訪高雄酒精淨手液代工廠
・拜訪三創$wr$, $wr$最近我看到了德鲁克的一句话，刚开始觉得有点奇谈怪论：「成果的取得靠挖掘机会，而不是靠解决问题。」

挖掘机会，没有人反对，但是不解决问题怎么行呢？尤其是我们这些做事的人，天天不都在解决问题吗？好像说来说去，德鲁克不过是在「抬头看路」和「低头拉车」之间，更加强调抬头看路而已。这个观点也没有什么稀奇。

但是，紧接着我又看到了德鲁克的一句话：「创造未来的行为就发生在今天。没有明天的目标，那今天的行动多半是重复昨天的事。」

我突然明白了：一个有创造力的人的本质是：活在自己构想的未来里。

为什么德鲁克让我们不要去解决问题？因为问题是过去留下的。你要去解决问题，你就是活在过去，就是看不到未来，因此就不再创造。

这个道理听起来古怪，其实，举几个例子就不难懂了。

我们先拿一家公司来说，一家好公司，是因为你把看见的问题都解决了，所以变好的吗？不是吧？问题是解决不完的。所有的程序员都懂这个道理，BUG 是补不完的，细节是完善不尽的。

有一句话说得好：好管理是一家坏公司的结果。

当然，这不是说这家公司真的管理得好。而是说，看起来井井有条的公司，是因为把老问题解决得太多了，以至于它没有精力和意愿去为自己定义新问题。这样的公司当然就是活在过去的。

比如我们公司是互联网公司，想学互联网运营，我有一阵到处翻各种各样互联网运营的书，到处听各种各样互联网运营的课，花了好多钱，好多时间。问题是它能解决我问题吗？如果我带着一个心思说，这个老师水平高，这个公司是一个大厂，所以它的互联网运营一定能解决我问题，那是我自己糊涂。

「得到 App 的线上运营该怎么干？」这个问题不是用来被解决的，这个问题搁在我心里，它是一个永远解决不了的问题。但是我在解决的过程中，听到了各种各样的意见，看到了各种各样的干法，我自己获得了各种各样的知识资源，我在这个过程中滚动，让这个问题本身往前演化，这才是我听课、去看书的原因。你怎么可能指望我在底下坐两个小时，让老师给我讲得明明白白？从此我就知道什么叫互联网运营了——老师自己也不行。

说到这儿各位是不是更能深刻理解德鲁克那句话，你不要去解决问题，而是要推动眼前的难题往机会发掘，就是未来目标那个方向去演化。$wr$,
       $wr$$wr$, $wr$佑維：

「好的服務建立好的關係。」

最近與一個客戶 A 接觸後印象深刻，店面不大，離峰時間生意卻還是非常好，觀察之後發現了幾個重點：

1. 親切問候。
2. 真誠與熱情。
3. 隨時保持笑容。
4. 耐心、專注聆聽。
5. 把客戶當自己家人且精準給予建議。

後續也無私介紹了上游廠商 B 讓我們去互動，A B 兩者都是在產業深耕至少三十年以上的廠商，口碑好且特色都是笑聲很爽朗，對我們的品牌也都高度肯定。

體悟到培養一段長久且良好的合作關係實屬不易，抓住服務的本質，堅持做對的事，自然會有好事發生。

→ 做業務是如此，做人、做朋友、成為一個專業的工作者，不也應該是如此？謝謝小商的分享。

怡萱：

很多人會以加班來當成「我對工作很投入」的一種表態，並期待能因此獲得老闆的肯定。不否認，加班這種作法在某些組織與環境中，確實是有些「必要」。因為在那環境中，大家都這麼做，所以你若不做，就顯得好像低人一等。但這是其實就是一個很多上班族始終沒搞懂的秘密，就是到底老闆是用甚麼角度在評判「功勞」這件事情。加班通常不算甚麼了不起的技能，因為要加班的話人人都會。大部分老闆看重的，往往僅是「結果」兩個字。「在對的時間點，很輕易做到的功勞；比累得要死，但卻看不出成果的苦勞更有用。」若是一昧地照指令辦事，沒有去想指令的目的，指令沒講的就沒做，明明不合常理，也悶著頭做出來，往往就會造成作白工的結果。

所以若是既有基礎不足，強迫自己學習新技能，改變自己看事情的高度與角度，在既有的知識基礎上逐步架構新的概念，期許自己每次付出的苦勞都能獲得等比的功勞。

湄涵：

戰略思維（Strategic Thinking）是我最近新知的名詞，我的理解是，用有戰略思維的工作者，能發掘對之後有益的事並訂定明確的工作目標，將工作累計的經驗與技能投入下一個戰略目標並產生累積性的價值。大環境的變動，我認為不只是公司決策方針可能會變動，而是每一個工作者都要保持危機意識，培養戰略思維思考目前的工作是否能帶給自己未來的價值並與最終目標連接。

→ 這個反饋跟最近非常熱門的一個討論有關，

「損益表」是最簡單就能看自己到底有沒有賺錢的報表。以它的主要結構來看：收入 – 成本 = 淨利，只要收進來的錢大於花出去的錢，就是有獲利；反之就是虧損。

成本減少有其極限，還要開源才行

管理成本可以從了解不同成本的特性開始。一是「銷貨成本」，只有交易發生時它才會產生。假設你賣的是甜點，跟甜點相關的所有原物料、包材等，都是銷貨成本。

第二個是「管理費用」，這是就算沒有發生交易，也會產生的花費或支出，如水電、租金、人事成本等。

簡單來說，如果要增加淨利，就是要讓收入愈多愈好、成本費用愈低愈好。在企業內部，可能會常聽到要 cost down（降低成本），尤其是很多人都把成本效率當成是競爭力的展現。

如果一味地降低成本，進而損害品質、間接影響到客戶滿意度的話，對企業來說也不是件好事。在成本管理上，要記得兩個重要原則：

1. 該少的成本不能要（cost down）
2. 該要的成本不能少（value up）

閒置、浪費與損壞，是絕對要減的無效成本

所謂的無效成本，就是對企業沒有效益的成本，最常見的 3 種無效成本是：

1. 閒置成本
顧名思義，是錢花下去，但沒產生任何好處。閒置空間還是會有成本發生，包括水電、清潔、人事、租金等，這些成本沒辦法為公司帶來任何效益，就是浪費。

2. 浪費成本
製造過程中浪費的原物料，會壓縮掉原本該有的利潤。在無效成本裡，浪費成本最可怕，所以許多製造業導入精實管理，就是希望消除生產製造過程中的所有浪費。

3. 損壞成本
想要消除損壞成本，就必須關注「良率」。如果良率是 98%，代表你生產 100 個產品裡，有 98 個是好的，只有 2 個是壞的。然而，良率時好時壞，一旦良率降到 80%，等於你一天的產量，就硬生生少了 2 成。

砍掉「延後發酵」的成本，反而會喪失競爭力

除了削減成本外，也要關注如何增加成本，提升附加價值。換句話說，有些成本絕對不能砍。這些絕不能刪的成本，通常都有「時間延遲」效果，一旦把它砍掉，短時間的確能替公司降低支出，但長期來看，反而會影響公司的競爭力。

1. 品牌建立
建立品牌不一定馬上會顯現價值，所以關於品牌的支出要謹慎，不能隨意減少，否則很容易造成用戶的對品牌的認知不清。

2. 技術研發
目前財務會計規則裡，認為研發的效益不一定會實現，規定組織必須當期認列，這有時會降低企業投入研發的意願。然而，美國研究報告顯示，每 1 美元的研發費用，未來可能會帶來 2 美元的利潤，甚至對公司估值有 3～5 美元的增幅。打個比方，研發就像是企業的肌肉，如果為了瘦身而減掉能保護內臟的肌肉，反而得不償失。

3. 人力資源
裁員最怕會有連鎖反應，當既有工作量要分攤給留下的員工，對那些能力較好的員工反而是種懲罰，因為公司無法提高他們的薪酬，最終產生另外一波出走潮。

再加上建立團隊需要時間，無論新增或裁減成員，都需要磨合期。換句話說，從帳面上來看，裁員或許能降低成本，但在績效上反而會產生負面影響。

文千：

1. 厂商专注于做灌胶工艺，目前都有做蓝禾、倍思、创龙、帕拓逊等的灌胶吸盘，蓝禾是目前对灌胶吸盘吸附力要求最严格的，有自己非常大的实验室来测试吸附力。

2. 跟蓝禾配合的初期，因为蓝禾实验室有很多不同纹路的仪表台，而且要求仪表台基本各个面都能适用，所以一直达不到要求，后面讨论了相互的折中点后，蓝禾可接受灌胶工艺。但友颉自己还是不断测试尝试，目前有做一种新给软胶工艺，胶的薄款更薄，吸附力会更强，现在很多客户接受了这种新工艺。

3. 听友颉说，创龙目前有 60 多台注塑机，新扩展了一个工厂，他们的产品开发速度很快，自主开发产品后会投入市场测品，一旦浏览量大的就会马上开模，所以跟电商客户配合的时效性会很迅速。

我在想，灌胶厂商提到他们已经满足了蓝禾的要求，但是他们也自省如何提升工艺达到原本的需求，测试半年后目前吸盘工艺有提升，可以做的更薄吸附力更好，说明他们对自己也是在不断的创新跟尝试。时代就是如此，无论是个人或者公司，只有不断的自我完善，进步，才能有一席之位。

家瑩：

客戶知名但可賺到的毛利低於平均，該接嗎？

如果客戶出的價碼，在評估成本後，毛利明顯低於平均，業務仍承接，就要交代原因。「這時的考驗，就變成異常成本的專案如何評估？」若客戶是國際知名品牌，業務認為接這單，後面會有 3、5 個客戶慕名前來，那不只毛利低，也許賠錢都值得做。

第一線的決策者要有成本概念，就能降低虧損機率，若此時財會人員應主動告知風險，讓業務知道這單做下去，效益沒出來，就有洞要補，儘管最後決定權在業務手上，但專案人員要有成本概念與風險意識，「他就會去挑戰自己，想著頭洗下去，有多少把握能賺回來。」多一層這種思考，也能相對降低做到賠錢單的可能。

接案後的折讓、退貨，也可能讓毛利沒達標。有時業務只看到案子談好，業績拿到，卻沒管錢還沒入袋。只要還沒收款，都可能遇到客戶因對成品不滿意，產生折讓或退貨。這些影響實際收入的損失，都得從別單補。

