・新創平台 survey$wr$, $wr$延續之前分享張忠謀先生的演講，有一個重要觀念在於 learning curve（學習曲線），亦即透過接單生產後的學習，可以有效地提升效率與提升研發以達到效能的提升，進而降低成本，並形成價格競爭力，用低於競爭者的報價來建構競爭優勢。

這是我們有條件發揮的戰場，本週也應用了這個題目讓團隊做了一個探討，相信能夠形塑出我們在成本與效能意識，重建我們在目標客戶群中的定位。

========= 下文摘自張忠謀的演講內容：

策略，我特別用紅字，因為我覺得，別的都是基本的，策略是比較高一層。

這是我在 TI 時用的策略，這個幾乎是 50 年以前，TI to Continue Cutting Prices on TTL:Chang，這個是我的策略，凶哈哈的樣子，這個策略事實上非常成功，

我是用 learning curve（學習曲線），我出任 GE 的 CEO 時，就是 learning curve 的 believer，GE 有很多 BU，他們對手下說，一定要在五年當中變成你這個行業的第一或第二，假如你不變成你這個行業的第一或第二，we stop your business，那個是 learning curve 的一個結論。

我是用 learning curve 來 cut prices，為什麼？因為在毛利率已經不高了，你要知道，不高，那時候在 TI，毛利率是 40%，不高，在半導體要的是 50% 以上，那就是基本，沒有 50%，因為要很多錢來做研發。

那個時候已經不高了，40%，還要 cut prices 幹嘛? 我要我的策略就是，我要你們絕望，因為 TI 已經是最低成本（cost），我們只賺 40%，你賺 20%，我們現在又繼續 cut，我們有 learning curve 的 advantage，沒有希望的（其他對手），還是停止好，當然那個時候我這個策略很成功。

現在英特爾新的 CEO 說，台積電因為有 learning curve advantage，所以做的比我們好，所以我們也要做晶圓代工。$wr$,
       $wr$$wr$, $wr$艷梅：

抱怨的人其实心中早已有了对某些事情的看法或解决方法，可能是不被重视或自身不够主动，所以只能抱怨。如果把自己的想法从公司的角度及员工的角度中采取一个平衡点加以考虑，把抱怨化作建设性的意见，并且以领导能够接受的方式主动提出，或者积极实施，我想公司应该是非常欢迎的。

→ 是的，歡迎有建設性的意見，請與主管聯繫，也可以副本給我：woody@comart.com.tw

芳杏：

同樣產品為什麼我們比較貴?

HM3 定價討論反映為什麼工廠成本這麼高，為什麼我們做不到低成本，這議題其實很大，從物料成本到進貨組裝生產到出貨海運報關息息相關，這星期連續 3 天熱烈，並且也提出很多改善及改善的方向，現在就自我動起來，相信我們還是有很大空間及競爭力。

于嵐：

因為客服，我們很常會第一線直接接觸客戶，服務客戶，解決客戶使用上的問題，

很多時候在服務客戶的時候，我們可以從中發現我們一些不足的地方，例如:

1. 圖文資訊不夠明確，導致客人對於產品仍存有疑慮，這時我們就會加強圖文的表示方式，或者拍攝產品影片。

2. 產品品質問題，可能對於代理品牌更換配件，我們並不一定會知情，當客戶反應時，我們當下會補足客戶缺失的配件，為防止同樣的狀況發生，之後只要每一批進貨都會拿一款產品出來驗貨，確認裡面的配件內容物。

客戶的每次反映其實都是讓我們從中學習並且變的更好，其實很多時候客戶感謝我們的服務，我們也是覺得很窩心，客服是最能感受到溫度的溝通方式。

淑倩：

這次分組作業，能在短暫的時間內順利完成並提早繳交，要感謝小老師 Vivi，

好的小老師會懂得協助團隊先去建立共同的目標和方法，有了共同的目標,

就能去設定個人目標，建議方法可從身邊的問題去思考。

經由團隊相互支援，從不同角度觀察問題，然後交換資訊，在大家熱烈討論下，

把解決方案及執行部門，即時歸納整理完成了作業的內容。

所以作業目標的完成，須由個人目標先服從團隊目標，同時團隊成員也需勇於兌現承諾，

不僅是團隊對公司的承諾，個人對團隊的承諾，也是個人對自己的承諾。

雲丞：

賣貨是徒弟，收款才是師父

「賣貨是徒弟；收錢才是師父」這是著名的台語生意俗諺，是在提醒做生意的人或負責業務推廣的人員，把產品銷售出去，只是第一步，把貨款回收才是完成任務。以西方的管理學來理解，就是開發新客戶或與既有客戶往來時，要作好信用調查、應收帳款的管理以及財務風險的控管，確保最低或零的被倒賬率。事前預防，重於事後治療，呆帳隨時可能侵蝕老本。

1. 事前的徵信調查
2. 建立客戶資料
3. 落實收款工作

佳鈴（瑩如、淑婷分享內容接近）：

這週與兩組伙伴們溝通 Xmind 的應用，與不同的伙伴群組合配合，發現各組都有著不同的思維開展，這倒是蠻有趣的學習經歷。業務伙伴對於這題目特別有感，會從自己面對的「被客戶嫌價」狀況去陳述問題及往下去思考問題背後的問題及解決方案；設計伙伴則會抒發與廠端溝通設計時發現的問題經歷並提出解決方案；財務伙伴則從成本面、費用面提供發現的問題及改善建議；有採購經驗的伙伴則提出曾遇到的採購問題及改進方案，每組的成員來自不同的工作領域，難得有這樣的題目發想，增加了跨部溝通問題的機會，讓彼此更了解問題的所在及共思解決之道。同時，也發現了一個問題的發生，可能因此產生連鎖的擴大效應，如來料不良問題，可能是採購購料時未與供應商溝通好品質要求，品保進料檢驗時檢驗標準過低沒有發現不良問題，不良料投產卻造成生產端須撿料再投產或投產產品不良率過高，得再重工補貨，甚或出貨後再被客訴品質不良退貨補貨……，問題的中心根源若能於早期發現時解除，也就不會再延伸後面更多的問題。透過這次的活動，讓我體認到團隊有著共同目標、建立共識、共同集思問題解決之道的那股自然而然凝聚力的強大，團隊若能有共同的目標策略，更有利於行動方案的落實執行，共同努力的結果表現也會更佳。

家瑩：

好的產品，要給到對的客戶，業績才能有長期正向循環。

錯的用戶，不但會讓產品開發時走錯路；最慘的狀況是，一旦好產品給了錯的用戶，這群人反而成了壞口碑的傳播者，加速產品的失敗。

台積電創辦人張忠謀日前提到，台積電的商業模式是以「客戶是誰」而定，不是以「產品是什麼」決定。他更舉星巴克為例，因為經營者很清楚，它的客戶不是隨意喝杯咖啡就走的人，而是懂得享受生活的人，因此能把一杯咖啡從 3、4 毛錢，賣到 2.5 美元。

看到上面的文章就聯想到我們這週分組討論「一樣的產品，為什麼我們的比較貴」的問題，我認為客戶的採購工作職責就是要找到便宜的報價，但一昧尋求便宜卻忘記了價格高的背後代表品質高。如果客戶在意的是品質我想只要能說服客人，讓客人了解我們的服務與產品品質絕對有這樣的價值，那願意跟我們往來的客人一定也都會是對的客戶。

湘芸：

「跳出框框」是我近來的業務心得。過往我們推廣產品給客戶，常常都會去看客戶的網站以了解客戶的產業別和產品線，然後再推廣客戶可能會感興趣的產品給他。但這次推「旅行支架」給 Wicked Chili 是一個另外一個跳出框框的嘗試。

Wicked Chili 一直以來是做機車架/車架類的產品，旅行支架跟他的產品線完全不同，但因為我從目前銷售的經驗了解到旅行支架這個產品適合在線上銷售，因為搭配產品影片、圖片能快速讓消費者知道如何操作及多元的使用情境，所以我看中 Wicked Chili 的銷售通路主要也是在 Amazon，就抱著試試看的心態推廣這個產品給他，同時提供產品影片、圖片說明、其他 Amazon 銷售旅行支架的賣家的連結等資訊給他，我跟客人說這個品項在 Amazon 上銷售成果很好，他也可以看其他賣家的 review 得到應證確實銷量很好。接著又跟他說，如果他願意試試看的話，我很願意接少量訂單支持他。於是得到客人很正面的肯定，訂單也下來了，第一張訂單 800 pcs 比我說服他時的 200-300pcs 多了很多，對我來說是一個蠻好的經驗，希望複製這經驗去做其他銷售。$wr$, $wr$$wr$,
       'C00001', '劉恕偉', timestamptz $wr$2021-11-14 09:00:00+08$wr$, now()
