select $wr$b000000bfidl9rv$wr$, $wr$2021-11-20$wr$, $wr$・OKR 輔導
・新創平台 survey$wr$, $wr$・拜訪經建會
・MISA 課程
・SS 年度 Review 會議$wr$, $wr$詐騙集團、銀行搶匪團是不是團隊？

第一時間，我也無法定論，答案揭曉後，卻是極易理解，人生道理似乎都是如此。

我自己思考，老師提醒的能否「共同承擔責任」，有以下思考：

a. 烏合之眾，起心動念就無正義。兵者五事：道天地將法，邪魔歪道，天地自然不容。

b. 信任，是團隊之基石。如果沒有信任基礎，就算是正義之師，也是一團散沙。

c. 「共同目標」到底是什麼？是各自能夠分到多少錢？還是大家能夠共患難共享福？在這樣的組織內通常說不清楚，如只是看錢，也會成為黑吃黑，搶到什麼，也只是一時的。

d. 組織成員因圖謀自己私利為多？還是為了造福共同利益？如以私利出發，自然不是共同目標，也就不會成為團隊。

上述原因才是「能否承擔共同責任」的原因。$wr$,
       $wr$$wr$, $wr$湘芸：

「給別人留後路，給自已留後路」

Perilogics 的貨終於在第三次檢驗後，順利地通過本廠的 QC 檢測並順利地如期出貨…。

揚均的貨依照交期送貨並預先提供自檢報告給我們，一切都很正常，但恒群品管同仁們依照要求進行來料檢驗，才抽驗第一箱，就發現不良數量超過比例，所以要求退會請揚均返工，但，重送第二次的貨物還是被本廠驗退。這期間千千、品管們協助驗貨、溝通，甚至最後派品管同仁直接到揚均的工廠去隨線驗貨，溝通我們要的品質，最後，終於在第三次驗貨時過關。

跟揚均合作這款旅行支架已經好幾張訂單了，一直以來每次給客戶的交期我都多預估至少一週的時間，這時間是預留給本廠做來料驗貨及做臨時狀況緩衝的。曾經，在客人催貨的壓力中想過取消這預留的一週驗貨時間，但，隨著單量成長，又加上旺季，很擔心揚均在趕貨的狀態下沒把產品做好。又想到我們曾自許要做客戶 ODM reliable partner，想到這產品我就只是做轉手貿易，連品質把關這基本服務都沒做好的話，我就失去價值了，多方考量下還是留下了這一週的驗貨時間，意外地也為這次的不良訂單爭取到了可以返工的時間，沒有延誤客戶的交期，也沒因此產生延遲交貨的賠償。給別人預留的後路，最後也為自己留了後路。

這次的客訴很感謝千千、品管們的協助，即使我們廠的產品也很多的狀況，曾經我也是對我們的品質管理很有疑慮，但當有狀況發生時，廠裡有同伴可以一起討論、一起處理事情，有伴可以依靠感受面還是很好的。就這次的事件，我是真心很感謝品管和千千幫忙分擔，套句 Albert 跟我說過的話，「有團隊合作真的很幸福」！

→ 團隊的三要素：互相信任、有共同目標、承擔共同成果

淑倩：

與跨部門會議溝通問題時，會陳述問題的關鍵點，將內心對問題的感受、想法與期望說出來，是希望問題能獲得改善解決，避免此問題重覆發生，不會針對問題故作曲解、批評、責備與抱怨等。

對於客訴問題，無非是說明內部作業流程確實有疏漏的地方，是不是作業上的 SOP 出現破口？

我們是否應盡速安排跨部門協調會議？來徹底 check 一下 sop 的細節與流程，是哪一個環節出現問題，還需要在加強，不會再發生相同的客訴問題。

因為客訴會影響公司的品牌價值，會削落對公司品牌的好感度和信任感，而且品牌的維繫是需要靠長時間的悉心呵護，有時可能因一個失誤就讓品牌毀於一旦，無法挽回。所以我們每一天面對客戶需求要做的每一件事，都是要除去品牌的風險，都是要為品牌加值加分。

→ 漢隆剃刀

怡萱：

OKR 是幫助所有人了解最新目標是什麼，由團隊討論出一個周期內定向的大目標，告訴大家「我們現在要做什麼？」這周上了 OKR 的課程後，才了解到自己之前所認知的 OKR 的定義還是有些許的不同。藉由這次的課程和分組討論，才發現看似簡單的定義，深深地剖析後，是多麼的複雜，不論是企業的 OKR 還是部門的 OKR，最後都會和自己的 OKR 息息相關，是牽一髮動全身的生命共同體。有一個共同努力的目標後，大家可以一起前進，一起奮戰，一起成長。

紹軍（家瑩分享類同）：

「對方很忙，不要常打擾」接到大客戶訂單⋯為何不能這樣想？

很多人都以為不要常打擾客戶，事情告一段落再跟客戶報告比較好，卻不知客戶已經開始焦慮，可能覺得你不在意、不關心，慢慢流失對你的信任，實在得不償失。

專業是建立信任的過程，需要很多溝通的細節與流程慢慢堆砌，這需要的不只是把事做好，而是在做事的過程中，讓客戶全然放心。這份放心，就包括主動報告進度。「讓客戶知道」這件事看似枝微末節，卻是影響客戶觀感的重要因素。這就是為什麼有些公司可以收比較貴的費用，而有些公司不行。

很多人接了專案之後，就埋首在工作中，忽略了要和客戶保持聯繫、定期更新進度，以為只要提出好的方案，客戶就會滿意，但往往客戶心意的變化比你想企劃案的速度還快。所以，最好的方式是密切與客戶連絡，報告進度、客戶也會告訴你他的想法，也許能幫助你企劃案寫得更精準。

→ 凡事有交代，件件有著落，事事有回音

于嵐：

近期在討論 XMind 以及 OKR 的時候發現到，因為不同的部門在意的事情都不太一樣，但透過幾次跟不同部門交流想法與意見後，我的想法都會因此而改變，都會看著討論出來的結果有所反思，思考自己可以再幫忙做到什麼，可以怎麼做到更好，小組的討論都是讓我們對於跨部門的合作想法更多元。

可欣：

這週 OKR 課程對焦過程中有很多收穫，其中印象較深的是顧問在解說 KPI 與 OKR 差異時舉例搶銀行與搶匪讓我們思考『團隊、團體』的差別，團隊是有確定的方向並且有共同的目標而且要能『共同承擔結果』，就跟會議室裡的看板提醒【所有對話請用『我』或『我們』來敍述】的意義是相同的，我們是一個團隊、我們是一個生命共同體、我們在同一條船上，我們要做的是發揮自己的長才並幫助彌補別人不足的地方，要把抱怨化成『正向』的行動力；『關鍵指標』的意義也不是用來檢討或成為指責的工具，而是為了『登頂』給的方向，要讓『我們』一起去完成『共同的目標』才是訂定目標的意義。

振慈：

「創業力」是未來時代的一個必要能力，我們是否能像創業者一樣去深度思考公司的問題、像創業者那樣去和同伴合作、像創業者那樣去探索和解決問題，這將會是一個必備能力也是一個好員工的標準，我們不見得需要自己創業，可是我們需要具備著這樣的能力和觀念。很多人上班只是打工心態，即使這對我們來說只是一個學習過程、一個跳板、隨時準備要走、不準備長待，也並不等於我們一定要用打工心態來對待手上的工作，這樣的心態並不會使我們在往後獲得更好的工作機會或是技能，甚至是多元型態的工作模式，我們為自己的工作負責，是為自己的人生負責，不是為老闆更不單只是為那個我們認為根本不屬於自己的公司或企業。交出成果、達成目標，當責不只應用在工作上，更應該是人生實踐的方向。$wr$, $wr$$wr$,
