省思問題點：

Q1. 東方人不善於表達情緒，或許。
Q2. 別人的再怎麼的好都是應該的，活該他的好。
Q3. 覺得別人表達讚美是有目的性的。

其實都有解法，

A1: 刻意練習
A2: 時時提醒自己要有謙卑的心、感恩的心
A3: 實事求是，如果真的好就是好，也應該同時給予各方讚美。

讚美是需要練習的，各位主管，各位同仁，我們用行動來落實，讚美同事、讚美伴侶、讚美家人、讚美公司、讚美客戶、讚美供應商、讚美自己。

也請大家一起想想，如何設計一些機制落實於組織內。$wr$,
       $wr$大陸電商平台不停的長江後浪推前浪，抖音、快手等直播平台後來居上，在網站成交金額（GMV）已與淘寶形成三足鼎立。

直播電商簡單來說，就是把電視購物搬到網路上，近兩年因為疫情宅在家上網，更推動直播電商爆發式增長。

據統計，2020 年全年 GMV 規模已超過人民幣 1 兆元，其中，淘寶直播達人民幣 4,000 億元，抖音直播人民幣 5,000 億元，快手直播人民幣 3,812 億元，呈三足鼎立的競爭格局；從增速來看，抖音年增 392%，快手 100%，淘寶 55%。預計 2021 年直播電商 GMV 規模達人民幣 2 兆元（約新台幣 8.7 兆元）。

=>

1. 小時候胖不是胖，巨大如淘寶，只要沒跟好任何一個技術拐點，就很有可能被甩出賽道。

2. 品牌商與通路商，也要掌握每一個拐點，跟對夥伴，才能持續擁有舞台。

結論：不創新就等死，包含業務推廣也是如此，不只是產品創新。$wr$, $wr$艷梅：

杰克·韦尔奇（前通用电气集团 CEO）：我们必须在整个公司提倡和灌输一种观念，营造一种气氛，以鼓励公司的每一位成员都能够以面对现实的态度看待问题，并以面对现实的态度解决问题，坚决避免那种自以为是、主观专横的处理问题的态度和方式。

——

审时度势，根据现实迅速作出有利决策并积极付诸行动。同样的外部条件，同样的问题，采取积极的态度，就有机会在现实的夹缝中找出一条出路。

→ 認同。信任與溝通是成就團隊的主要道路，沒有任何其他路徑。

于嵐：

在部門業務會議的時候有討論一個議題，我們需要在雙 11 或者雙 12 這種大節日去做大促銷嗎？我的回答是，我們以往都有在這些節日做活動下殺，其實做了幾次後發現，雖然業績有增加但毛利是減少的，重點之後這款產品就會沉寂好幾個月才會開始有顧客購買，其實對商品銷售蠻傷害的，另外大家並不一定會在這些節日做消費，我認為我們的產品屬性不屬於衝動型消費，通常都是有需求剛好有折扣，就購買了，所以以長期來看，我覺得我們是可以搭節日做一些活動折扣，但不需要大促銷，平常月份就持續性做小折扣，養成客戶，平時就會購買的習慣，不需要等大促銷才會購買我們家的產品。

→ 很棒的分享

林森：

本周进行了教育培训，在培训完既定内容后，最后跟大家分享了一下最近学到的 xmind 的运用和 OKR 个人一些理解。没想到还是有部分人对这些分享很感兴趣，很认真的听完了。自己分享的东西，能得到别人的认同和喜欢，还是很开心的。最少让我知道，有人喜欢自己讲的东西。

不管是分享，还是其他，比如当一个人发出信息后，潜意识，其实都是希望得到别人回馈的，就算最简单的「收到」，一个表情，也是一种回馈。如果你发出一条消息，如石沉大海，发消息的人，内心其实有点如飘在云端，无处着落。

以前自己也不太习惯做回馈。也是在工作中，各主管多次教导，才开始有回馈的意识。尤其是当自己也经历过这种情形后，有更深的体会。

所以回馈真的是一件很重要的事，这方面我做得还不够好，还需要更加主动的去做回馈动作。以此提醒自己，自勉。

家瑩：

因為自身有兼總機的職務，故常常會接到消費者的客訴電話，偶而會遇到比較不理性的客人，時常要耐著性子跟客人溝通，看到一篇文章的分享，覺得用這樣的方式處理客訴問題，能夠使顧客較容易冷靜下來，處理事情也會比較順利。

1. 先表示歉意
當客戶提出抱怨時，「我很抱歉」是你應該說的第一句話，這是對於造成客戶的不方便表示遺憾。在一開始就立刻說出「我很抱歉」，可以讓客戶不會那麼生氣。

2. 不要自我防禦
如果你在客戶抱怨時就先忙著撇清，對客戶而言你看起來就像是在找藉口、質疑他們的認知，以及將過錯推到他人身上，這些都解決不了問題，而且會讓客戶覺得你根本不想為他們解決問題。

3. 不要和客戶爭論

=> Joy 太棒了

雲丞：

只要是有和客人接觸的工作，最難應對的就是處理客訴。大多數的工作者聽到客訴就害怕，因為顧客強勢的態度總是讓他們陷入恐慌。但其實，客人願意抱怨，表示他強烈的在乎、關心公司或產品，所以我們應該更加重視，幫助察覺公司服務的優缺點，只要拿出正確的態度處理，使客人滿意，就有機會能為自家品牌或產品增加忠誠者。

我們也是一樣，通路也會常常遇到客戶客訴，但客戶不在乎，怎麼會跟你反應呢？把客訴的機會轉換成服務的契機點，不就是一個累積品牌鐵粉的機會嗎？

人可以在與客戶的爭論中獲勝，即使你向客戶證明你對了，其實你還是輸了。對誰對誰錯這種事不用太在意，找出解決方案才是最重要的。

4. 展現樂於處理問題的態度
在面對客戶抱怨時，最好以一種適切的關懷語調提供你的協助。如果他們正在氣頭上，盡量讓他們發洩，不要生氣也不要走開，在那裡等他們發洩完再提供你的協助。

5. 快速解決問題
盡你最大的能力讓問題盡快被解決。解決問題的速度越快，所造成的損失就越低，繼續保有這位客戶的可能性就越高。

6. 感謝客戶讓你瞭解狀況
這樣做可以讓客戶知道你重視他們提出的抱怨，增加他們對你的信賴，進而樂於與你打交道。

7. 追蹤問題解決的過程
不論你是自己處理問題，或是得將問題轉交給公司其他人處理，都要追蹤後續的處理狀況，確認客戶收到可以接受的解決方案，最好還可以持續追蹤更久一點，讓客戶知道你還在關心他們的狀況，也可以確認所有狀況真的完全沒問題。$wr$, $wr$$wr$,
