       $wr$于嵐：行銷科技 Martech 是什麼？

Martech 是 Marketing 和 Technology 的組合字－行銷科技，泛指各種能協助達成行銷目標、執行行銷工作的科技方法。

在從過客到熟客的旅程上，行銷可以使用的解決方案可說是琳琅滿目，而前段所提到的 Martech Landscape（也常稱作 Martech 版圖、Martech 地圖、行銷科技地圖…等）便是將市面上的行銷解決方案彙整，依不同功能及作業類型分為六大類：

1. 廣告技術（Advertising and Promotion）
2. 內容與體驗（Content and Experience）
3. 社群與關係（Social and Relationships）
4. 商業與銷售（Commerce & Sales）
5. 數據（Data）
6. 流程管理（Management）$wr$, $wr$艷梅：

12 月 3 日的《中国青年报》其中一篇文章《被认同和尊重比薪水高更能留住职场新人》，文中提及，新近发布的一份员工激励机制调研报告显示：「被认同、被尊重、有归属感」位居职场人留任原因之首。面对这些期待，如果一些企业管理者仍然高高在上、颐指气使地「虐员工千百遍」，只会将员工越推越远。

正好想起，刘先生亦曾提及我们要用行动来落实赞美。多点赞美值得肯定的人和事，少点习惯性否定，相信大家心情都会愉悦很多，工作执情自然就会提升。

