管理自己的情绪

人活着难免会碰到不如意的事，不顺眼的人。但就像老话说的，你可以愤怒，但不能愤怒地表达。真正成熟的人，都懂得管理自己的情绪。他们从不发不该发的脾气，不急急不来的事。不会因为愤怒就乱了方寸，也绝不用坏情绪影响他人。但说起来很容易，看了都明白清楚，但管理好自己的情绪并非易事。答应的交期已迫在眉睫，别人不急，你急，难免影响自我情绪，从而做出不当言行。合理的人员安排，适时的进度反馈，在自己在掌控情况下，从容应对，更容易管理自己的情绪。

