讀商周：「本週最讚的一件事」有感$wr$,
       $wr$不單是信仰價 為何蘋果配件最愛賣 590 元？

蘋果官網多種產品大缺貨，現在下訂也無法趕在聖誕節拿到，熱門商品之一，竟是售價 19 美元（台灣售價 590 元）的擦拭布。有趣的是，這項商品上架以來常被搶購一空，明明功能跟其他價格不到一半的擦拭布一樣，為何這塊「信仰布」能賣到這價格，難道真的「信仰無價」？事實上，背後藏有蘋果的「定價哲學」。

從官網看，蘋果配件的定價策略很少低於 19 美元（台灣通常為 590 元）門檻，像 Apple Pencil 筆尖 4 件裝、Apple Remote、USB-C 對 Lightning 連接線、EarPods 等小配件都賣 19 美元，僅轉接器最便宜可到 9 美元（台灣通常為 290 元）。

這些 19 美元小配件與 Apple Watch、AirPods 等產品屬於「可穿戴設備、家用設備和配件」類別，2021 財年第四季財報表現亮眼，營收高達 87.9 億美元。

雖然蘋果拒絕對定價政策發表評論，但科技產業分析師認為，19 美元是蘋果精心設計的價格，「不會太高也不會太低」，不讓目標族群失望。當客戶購買 iPhone 13、MacBook Pro 這種大件商品時，雖然不會注意到 19 美元的價值，但實際上這價格高到足以證明「你買的是高級產品」（即使可能不是）。

目前蘋果產品售價幾乎清一色以數字 9 作結（台灣通常為 90 元），主要照心理學的定價技巧「尾數定價」（charm pricing），讓顧客有價格優待的感覺。

風險投資公司 Loup Ventures 管理合夥人 Gene Munster 指出，對願意為科技產品和服務付額外費用的消費者來說，19 美元也算甜蜜價格，「當價格低於 20 美元，消費者不會特別考慮是否要買，即使只差 1 美元。」

相反來說，充電線、轉接器和擦拭布如果低於 20 美元，一不小心就會給人廉價感，不過蘋果這方面拿捏得很好，將產品定位於好用的奢侈品，即使價格稍高，消費者仍願買單。

除此之外，這種定價方式還取決於消費者的購物地點，如果是在蘋果官網或門市，就不會出現為了想買特定商品而拚命在亞馬遜或沃爾瑪網站比價的狀況。

Munster 表示，很多人認為花 20 美元在亞馬遜買一塊擦拭布相當荒謬，但如果是蘋果推出，的確爭議會少一些。他認為以擦拭布訂價來說，售價 19 美元比 9 美元創造更多需求，這塊布也證明蘋果對市場的影響力，每個品牌都無法擺脫這種模式。

