→ 漢隆剃刀

芳杏：

經銷商管理，大部份的企業對於經銷商是沒有管理，正確來說，應該是不知道該怎麼管理、或是不清楚該管理什麼。

業務人員往往分不清楚或不知道經銷商跟直接客戶管理上之差異，直覺性認為經銷商也是客戶，差別在於賣給經銷商的產品，經銷商會再轉賣給其他公司。

事實上經銷商跟直接客戶有很大的差異點，經銷商對企業而言的確是客戶，經銷商還有另一個很重要的身份－「夥伴」，意旨願意跟著我們一起打拼的企業。

但並不是所有的經銷商與企業有共同打拼的經營理念，大部份的經銷商還是著眼於「利」與「益」，也就是短期利益，而不是長遠的經營策略。企業在進行經銷商管理前，應先決定企業對於銷售通路的策略方向，接著企業該辨識哪些經銷商可以當作「夥伴」來經營。

→ 對供應商也是一樣，積極培養好的供應商成為夥伴是重要前提，盡可能的協助廠商與客戶，才有我們存活的空間。

瑩如：

當大家聚在一起慶祝達標，凝聚團隊的向心力，分享勝利成果。就如同我們在做 OKR 時，目標數字都是一大挑戰，但當團隊充滿著正面能量時，就可以用不同的心情面對挑戰。

