怡萱：

正向的力量不只可以使他人心情變好，也可以成為努力的動力。就如同 Woody 今天分享的商周文章〈本周最讚的一件事〉裡提到的一段話:「良言如同蜂房，使心覺甘甜，使骨得醫治」一個正向的念頭或話語，可以引發下一個正向的力量，凝聚團隊的向心力。

