福威：

推卸责任是自我保护的条件反射，往往在出现问题上级责问的时候，很多人立刻就产生了推卸责任的意识，接下来往往是无力的辩解，以及一些很粗糙的借口。这样会让上司感到你这个人很怯懦，并且很不诚实。也许当时上司没有点破，但千万不要认为他看不出这点。不承担负责任的人在上司的心目中不仅忠诚度较低，而且因为魄力不够也会慢慢淡出上司的视线，与很多工作机会失之交臂。所以与其把心思放在如何跟上司辩解上，不如在上司责问前想出问题的补救或解决方案。

→ 成長，從承認自己的問題開始。

文千：

本周有拜访供应商安耐佳，跟我们是同行，其工厂规模、5S、现场作业面给我的印象都还蛮深刻。样品室有很完整的无线充系列、香氛系列、懒人支架系列、重力系列等支架，专利证书一眼望去也不计其数。秉持着学习同行的心态，有以下几点觉得做的还不错：

1. 市场清晰，核心客户为国内电商客户，所以他们很侧重产品开发，5 位 ID 设计师，每月都有 1-2 款开发的新品。也有海外业务团队，目前也有一些国外市场客户。

2. 产线作业效率高，可能因为计件模式，产线员工做事速度很快，25 天交期就可交货。

3. 每月有生产之星评比，选出产线优秀员工给与嘉奖，提升员工的积极性。

4. 每款产品出来都会有设计对应的黄盒尺寸，样品都用黄盒装来送样，这样客人收到产品后，有现有的刀模图可参考。说明书也会做一些中英文公版，方便客人直接套用。

→ 這些都是我們需要學習的

李立：

控制成本的途径有三种：一、砍掉一些不必要的执行步骤。二、在保障质量的前提下减少对每一项执行步骤的投入。三、改进生产工艺，提高效率，在保障质量的前提下缩短每一项执行过程的时间。

记得之前刘先生曾经分享过一篇文章「为客户持续创造价值的能力」。我个人觉的这里面包括两个方面的内容，「价值」、「能力」，「价值」是主观的，「能力」是客观的。「价值」广义的来讲包含的内容是非常广泛的，我们从狭义的角度来谈论：比如某个产品，V=F/C，在这个公式中 V 表示价值，F 表示该产品的功能、外观、结构、是否包含了流行元素等等，C 表示成本。价值 V 是一个相对的概念，它不是该产品的使用价值，也不是该产品的交换价值。它是该产品的比较价值，任何提高价值 V，我们有五种方法：

一切从 V=F/C

第一，在成本 C 不变的条件下，通过提高产品的功能，提高利用资源的成果或效用，使价值 V 增加。这我们称之为「改进型」

第二，在保持产品功能，资源利用的成果或效用 F 不变的条件下，减少成本 C，进而使价值 V 增加。这我们称之为「节约型」

第三，通过对产品的功能，利用资源的成果或效用 F 进行大幅提升，同时成本 C 略有提升，使价值 V 得以增加。这我们称之为「投资型」

第四，产品的功能，利用资源的成果或效用 F 略有减少，同时成本 C 大幅度减少，这样也可以使价值 V 增加。这我们称之为「牺牲型」

第五，提升产品的功能，提高产品利用资源的成果或效用 F，同时减少成本 C，将使价值 V 大幅提升。这是最完美的状态，我们称之为「双向型」

以上就是属于主观的价值，而将这些主观的价值实现就是能力客观的展现

我不觉的这个世界有太上老君的仙丹这种东西存在。也没有一层不变的东西存在。世界变换太快，我们首先要让自己的思想能跟上世界变化的节奏。没有正确的只有适合我们的。$wr$, $wr$$wr$,
