謝謝 Vivi，下週聊聊您被 KD 表揚的那份 PPT

慶鍾：曾經在 HM2 報價過程中，客戶也曾經問過這個問題，換個 PCB 或是換個噴頭組馬達之類的，為什麼這麼貴啊? 我們跟你買零件自己換可算便宜些嗎? 我的回答則是，如您堅持要自買零件自行更換站在服務客戶的立場當然不能拒絕，但如果您在更換過程中因不熟悉機器內部構造進而造成其他地方損壞。後續要更換更多零件豈不是划不來呢? 是否還是交給我們的維修人員來處理呢? 也請相信我們的專業一定可以讓您滿意。

→ 專業、服務 能轉化為信任，信任有價，專業與服務也有價

于嵐：溝通再棘手，應該避免使用的 6 類詞語

NG 說法 1〉假設觀點顯而易見

有時若覺得自己 100％ 正確，可能會使用「明顯」、「顯然」或「毫無疑問」之類的詞語。如果這麼做，就會受到「素樸實在論」的影響，也就是認為某個客觀事實，其他人也能清楚看到，而且同意這項事實。

NG 說法 2〉誇大其詞

誇大其詞會傷害整體可信度，導致彼此針對頻率，而非針對實質內容展開爭論。「才不是這樣！」對方可能會先反駁，接著說出跟聲稱內容完全相反的具體日期或場合。

NG 說法 3〉告訴別人應該做什麼

告訴某人應該做什麼，其中暗含某種價值判斷。「你應該如何如何」，就表示那個「如何如何」就是事情「應該有的」模樣。

NG 說法 4〉因為自己的感受而責怪他人

自己若是對某人的話語或行為感到不悅，自然會產生情緒反應。這是人的本性。不過，說出這些感受的「原因」其實於事無補，還會產生反效果。

NG 說法 5〉挑戰對方的人格或誠信

可能會覺得某人的行為「不專業」、「不對」或「不道德」。但如果使用這類詞彙，對方就很有可能產生防衛心態。人類強烈需要認為自己符合禮儀和道德的標準。如果描述他們問題行為的方式，威脅到他們的核心自我意識，對方就更有可能偏離當前的議題，轉而為自身的人格辯護。

NG 說法 6〉「這不是針對你個人」

根據經驗，當人們（下意識）知道，某件事其實就是針對某個人時，就會說「這不是針對你」或「不要認為這是針對你個人」。

當某人因你的言語或行為，受到傷害、生氣，或是明顯受到影響時，告訴對方這並非針對他個人，只會讓對方覺得受傷。

最後，在工作上需要經過不斷的溝通，從中發現溝通需要思考過再說出，不然就很容易會使用到導致問題的詞語，需要不斷改進並盡量減少使用這類詞語，從而改進自己溝通的態度。$wr$, $wr$祝福大家聖誕快樂！$wr$,
