・年度面談總結$wr$, $wr$忒修斯之船（英語：Ship of Theseus），亦稱忒修斯悖論，是形上學領域內關於同一性的一種悖論。1 世紀時的希臘作家普魯塔克提出了這個問題：如果忒修斯的船上的木頭逐漸被替換，直到所有的木頭都不是原來的木頭，那這艘船還是原來的那艘船嗎？

→ 是不是同一條船的認知並非重點，重要是我們要有意識地不斷提升自我，替換掉不合時宜的自我，包含知識，包含認知，也包含健康的身體。鼓勵大家多學習，多改變，多運動。$wr$,
       $wr$紅卿（Red）：2022 虎紋數字寓意「前進」，特殊型裁切呈現「虎紋披風」意象

虎年總統、副總統賀年卡亮相，期許在新的一年面對變化，國人能有著老虎般的自信！由大象設計操刀，總統、副總統賀年卡以虎皮上的黑色斑紋拼出 2022 四字；電子賀卡的視覺元素由老虎延伸至貓科動物，提醒眾人當我們擁有老虎的勇猛，也別忘了展現貓的柔軟身段。

2022 虎紋數字表「前進」之意

電子賀卡則以紙本賀年卡元素為基礎，從傳統年節「虎」年的慶典，到跳入家庭和樂的「貓」，再進入全世界，以多元的字體、語言、老虎、貓科類動物等許多風格呈現，視覺上也能跳脫大眾對於傳統生肖賀年的印象，如同臺灣的多元文化，帶出「虎虎生風格」的概念。期許能夠像老虎般的勇猛，又保有貓科動物的柔軟身段，面對瞬息萬變的環境，保持變化的彈性。$wr$, $wr$金明：不是所有的工厂和公司都能赚到钱，赚到钱最后拼的一定是人品，产品亦人品，系统和机制亦人品。同时这个世界上大多数人经营的一切，都是在解决信任及被信任的问题。一旦信任出现危机，那万事尽将休矣。

→ 非常的認同

雲丞：《破框能力》這一本書作者在談我們常常會陷入一種稱為「能力陷阱」的境地，也就是說：「當你越擅長自己做的事情，就會一直去做。做得越多、越擅長，就越願意去做。這樣的循環讓你獲得大量專業經驗，卻容易讓你受限於專業框架，落入能力陷阱。」

你如果想在職場往上爬，那這種能力陷阱會成為一種很大的障礙，作者認為克服這個陷阱最好的方式就是「先行動後思考」，由外部的行動，改變內在的想法。

我們常常都是這樣思考那就是想要「先想清楚再行動」。結果，往往實際的情形是，想了半天卻滯足不前，永遠覺得自己還沒準備好、還不夠格。但我們必須要加強「行動」的部分，更願意讓自己嘗試以往不熟悉、不習慣的互動方式。

→ 是的，不懂就去學，不會就去做，做了就會了。

淑倩：週會提到，做學問的五步驟，博學、審問、慎思、明辨、篤行。

如在工作上遇到困難的問題時，想把問題解決好，就要去學習相關知識，然後對不懂地方審慎地探問，周密地思索知識正碓性，對於問題明確地判別正確的使用方法，明辨之後，得到的知識就要轉化為行動。

所以針對明年，我們要做個怎樣獲取知識的人。獲取知識的唯一途徑就是廣泛的學習，知識和能力都是從學習和實踐中得來的，在工作中學習，在學習中更新自我的能力。

→ 謝謝

佳鈴：「分數」無法百分百去定義、去衡量一個人的價值，每個人的存在都一定有他的價值所在，「分數」並無法完全代表一個人的一切。但是，透過別人為我們打分數及講評，能夠更了解自己哪些方面還有成長的空間，以及哪些方面做得不錯可繼續保持，這也就是古人說的：「以人為鏡，可以明得失。」因每人評分的基準不同，千萬別被別人打的分數左右了對自我的肯定，重要的是，在這說明落分數的過程中，可以讓我們更清楚別人如何看待自己及對自己的期許，肯定自己存在的價值，讓我們成長變成更好的人。

→ 同意，因為：1. 每個人的評分標準不同，有人認為達標是 60 分，有人認為是 100 分，我認為是 76~85 分，取決於品質跟目表的挑戰行。2. 分數不是絕對，重點是評論與回饋內容，要謝謝給我們回饋的夥伴。

于嵐：我的工作性質需要常常寫 FB 但有時候還是會有詞窮的時候，但後來在嘖嘖上發現了一本特別的日曆本在募資，看了一下內容，是每一天，都是值得慶祝的好日子，真的不知道原來 365 天都有節日，真的很有趣，對於未來寫文案也會有幫助，其中我覺得有一個節日很特別，國際失敗日，每年 10 月 13 日，開放讓所有人在網上公開分享自己的失敗經驗。因為芬蘭認為，從小就樂意擁抱失敗的孩子，最終會更容易成功，其實在工作當中也是如此，做錯事就是要勇於承認錯誤並且修補結果，這才是最好的。

→ Interesting ..

可欣：今年因著 OKR 課程建立了更堅固的團隊氛圍，仔細回想這一整年，真的有好多好多的感謝，每當在工作有困難或緊急需要支援及協助時，夥伴們回覆…『沒問題交給我、沒問題我幫妳、別擔心妳先做我來想辧法、別擔心我挺妳…』這每一句話都讓我覺得好安心及暖心，讓我有更強大的力量去解決每件困難的任務；未來也期望自己有更多能力，能成為夥伴們的幫助及支持的力量。

→ 謝謝可欣，謝謝團隊！$wr$, $wr$$wr$,
