自利可以让企业在短期内获取一定的生存空间; 利他则久, 利他才能让企业真正实现基业长青。自利是本能，利他是智慧，一个真正利他的人，可以想出无数感动别人的方法。利他就是最高级的利己。

→ 亞馬遜 CEO 貝佐斯：「聰明是一種天賦，而善良是一種選擇。」，聰明通常是一種負面的形容詞，聰明可以讓人獲得短暫的利益，而智慧則是可以讓多數人受惠，幫助別人，最終是自己獲得更多。$wr$,
       $wr$德國公衛專家勞德巴赫（Karl Lauterbach）日前宣稱，新冠變異株 Omicron 是「聖誕禮物」，或許能加速終結新冠疫情，這番言論引發關注，部份澳洲學者也呼應他的說法，主要原理在於，Omicron 可能更具傳染力而成為主流病毒，但是更不具致命性，將讓人類更有機會和新冠病毒共存。$wr$, $wr$佳芸：能當著你指出問題所在的，都是貴人

1. 思考事情本質：這時候可以換個角度思考，問題被指出，真的是壞事情嗎？或許感覺自己做錯事很丟臉，但知道自己的狀況，其實本質上是好事情，這樣才知道調整的方向。

2. 敢說你問題的都是貴人：任何會直接當面指出我們不足跟問題的人，都是「貴人」。

3. 自信來自於知道自己的不足：我的自信在於「跟自己比較」，我相信每一天我都能比過去更好。而自傲則是誤以為自己比別人更強，對他人鄙視貶低。

4. 相信世界的好：如果換種思維，那問題就會反轉成為助益，也就是因為我知道有不足，所以我也知道有成長空間，我相信自己能不斷成長，邁向自己希望的模式。而指出現狀跟不足的人，正在幫助我在這塊道路更加茁壯。他們的批評指教，都是在幫助我。你先假設所有人都對你是善意出發，把所有人都先當貴人，那自然你的世界中，就沒有小人了。

湘芸：這週跟 Jack 顧問餐敘，感覺蠻好的也受益良多。歷來的品牌輔導中，Jack 算是我最喜歡的顧問，他對我們品牌的了解和給的建議都很中肯，可實行性很高，不會太浮誇的給一個遠大目標。餐敘過程中，Jack 提到過往我們品牌輔導時曾練習過「傾聽」，其實我忘得差不多了，但經他一提，自己又重新思考傾聽的重要。常常我們在溝通時，只顧著想「怎麼說服對方」，卻忘了好好的「傾聽對方的需求、立場、觀點、情緒、感受」，或者即使聽到了，但卻沒有去進一步思考「對方背後的訴求是什麼？」，所以溝通效果大打折扣。「傾聽」是有效溝通的一環，大家對業務的刻板印象是業務都能言善道，但如果只是能說，卻說不到對方心坎裡也是白搭，提醒自己練習「傾聽」的重要。

文千：….. 我们作为职场新人或老员工，经常都会遇到同样的处境。学习新知识或者接收新挑战任务，第一反应往往是我不会怎么办，为什么是我？人的成长就是爬坡的过程，攀爬的能量就是不断的学习，新知识新领域的学习扩充，都是为上坡给予更多的能量补充。爬坡过程荆棘重重，但沿途都会遇到友善之人给与帮助，也会遇到目标一致共同攀爬的队友，所以不用担心自己爬不到山顶，我们要做好的是随时保持愿意前进的心态，遇到困难坦然面对，共同解决，总结经验奋勇前进，过程是充满正能量的，那结果也不会太差。

佳鈴：讚美活動於尾牙時經由福委們的鼎力相助順利開展，真心期盼大家能夠多多發現伙伴們的優點給予讚美，持續推廣讚美文化，讚美多多，快樂多多，收穫多多! 讚美活動，衝衝衝!

→ 謝謝大家！我們要持續，發覺團隊的優點，給予讚美跟肯定！

艷梅：赞美可以让人身心愉悦，但在日常生活、工作中，难免会遇到需去批评指正的人和事。在批评心理学中，把批评的内容夹在两个表扬之中，在建议和批评的同时，不忘认同、赏识、肯定和关爱对方，可以使受批评者更易接受批评，并改正自己的不足方面。

美玲：在目標、工作方法做到快、狠、準，但在經營客戶關係上不能只想著成交，應該要讓對方喜歡妳、想認識妳。不要大小眼，和對方建立良好關係，不是只對大老闆噓寒問暖，只有重視每個人，才能帶進更多新客戶。

