・OKR 初步確認$wr$, $wr$・董事長會議$wr$, $wr$https://www.managertoday.com.tw/articles/view/58458

閱讀文章有感，張董反應兩極的兩句話，「我覺得到這間公司有很多學習的機會」跟「我認為在這間公司貢獻的機會非常多」，其實，這兩句話完全是一樣的意涵，工作是從做中學，主動爭取工作或是開拓新的領域就是最好的學習過程，透過公司的工作平台鍛鍊自己的能力。成敗僅在一念之間而已。$wr$,
       $wr$林森，軍徽：

相机市场急剧萎缩，32 年历史的佳能珠海停产；落户珠海 32 年后，佳能珠海有限公司（以下简称「佳能珠海」）宣布「终止公司生产」。一份盖有佳能珠海有限公司公章的公告显示，因近年来全球照相机市场急剧萎缩，及新冠肺炎病毒长期肆虐，公司面临空前困难。虽经公司及各位员工共同努力，依然未能扭转困局，总部经慎重研究，做出艰难决定，终止公司生产。

佳能珠海的工厂位于高新区金鼎工业区，项目总投资 15 亿元人民币，占地 20 万平方米，是佳能在中国大陆唯一一家数码相机、数码摄像机、影像传感器和镜头的生产基地。该厂的关闭就意味着佳能已经把相机生产移出了中国大陆。由于智能手机的崛起，数码相机市场被急速压缩。近 11 年来，数码相机出货量从 1.2 亿台下跌至不足 1 千万台，降幅达 93%。据 CIPA（日本相机映像机器工业会）统计，2020 年全球数码相机出货量仅为 888.6 万台，比 2000 年时 1034.2 万台的出货量还要低。从佳能珠海工厂的关闭不难看出：一个企业要想永续经营不光靠的是强大的研发能力, 还要具备对未来产品市场敏锐的洞察力及快速的反应能力。我们要时刻保持高度的危机感，因为这份危机不光来自同行业，更有可能来自跨界的某个领域。这是我们未来需要思考和持续努力的方向。$wr$, $wr$豔梅：2022 年 1 月 11 日，清华大学艺教中心新年联欢会上，一个「神秘」的节目，勾起了观众的好奇心。当穿着蓝色工作服的邢国芹坐在钢琴琴凳上的那一刻，灯光亮起，全场爆发掌声。于是，清华保洁阿姨弹钢琴冲上热搜！永远有人正年轻！

由于常年在艺教中心从事保洁工作，音乐每天都在耳边萦绕，邢国芹耳濡目染，心中也默默燃起了音乐的梦想。她靠着走廊角落里一架因长期未用的「走音」钢琴，凭着毅力和兴趣成就了对音乐的梦想。

邢国芹坦言，她最想对同龄的人说，自身爱好和年龄没什么关系，做喜欢的事，永远都不晚。而对于年轻人，邢国芹鼓励他们：「趁着年轻，想学什么就去学，一定不要留下遗憾。」

芳杏：當業務，第一步莫過於要先搞定陌生開發，養成隨處把陌生人變熟客的能力。

陌生開發，是每個新手業務必經之路，帶著期待又緊張的心情，踏上未知處，盡力挖掘出寶貴客戶。而擁有好的溝通技巧、時間管理、面對失敗及創意新招，就如同拿到指南針，讓你校準方向，成為熟練的業務！

培養超強陌生開發力：

時間管理：妥善安排自己的優先次序，是陌生開發的重點
溝通技巧：丟棄話術，要讓客戶覺得被「特別對待」
面對失敗：為「被拒絕」重新下定義，把失敗看成是意見的回饋
創意新招：多一點創意，畢冊也能成為資料庫

陌生開發是走向超級業務員的必經過程，各種針對新客的「攻心術」，從時間管理、說話技巧、人脈開發到勇於面對失敗，都需要熟能生巧。更重要的是，堅持到最後一分鐘，成功才能在手中。

雲丞：信任的建立是「永遠的進行式」

信任和愛不同，愛是全然，沒有條件的付出，單純就是愛，信任不同，是有條件，有層次的，信任的建立是「永遠的進行式」，既然是有條件，更要把人和事分清楚。是隨便做沒做好辜負了你的信任，還是已經努力做出他認為好的東西，但不符合你標準，這是兩個不同的情境。尤其是在還沒有建立彼此真正的了解前，主管肯定是要負責任的，因為同仁不會知道你的標準在哪裡，但卻清楚自己的努力與用心。當你覺得東西不好，更有責任讓他了解要修正的方向。

淑倩：工作本身最大的回饋是工作本身，所以在工作中，認真的做好自己的本份。處在 OKR 的目標模式，會努力去專研過程中，把自己該做的事認真做好，遇到任何的難題難關都能應付過關。讓團隊受益，要顧及團隊因為自己的努力而有更好的提升，用「心」去感受工作中帶來的最大價值。

文千：

客人华联有一张急单请我们帮忙提交期，原本 2/28 的交期，经过生管，注塑，采购等各部门多次协调，可帮忙赶 1/19 出货。按照实际生产状况，提前到年前有一定困难，但客人请求我们一定帮帮忙，表示可多付费用，请我们务必帮忙达成。我们的团队真的非常棒，经过大家内部沟通，一环扣一扣反应非常快速，协调到客人希望的出货时间，我们也并没有请客人多付工时，回应客人的是如果真的有紧急需求，有机会我们都会全力去支持。客人表示很感谢我们整个团队的帮忙，除了认可我们的产品 & 品质，也非常认可我们的服务。之后客人也下了一张比较大的订单，表示会全力支持我们的产品。

团队向心力非常重要，因为我们有共同的目标跟使命，所以遇到困难，大家心往一处想，劲往一处使，才有能力完成我们的共同目标。很感谢我们团队每个成员的帮忙，谢谢大家。

对于客户或供应商，随时保持同理心，成就客户 & 成就供应商的同时，也是在成就我们自己。

→ 謝謝團隊

淑婷：本周周會分享的軟技能

軟技能造就努力工作的人，重要技能可造就偉大的職涯成功，這些只佔其中的一部分。

在一項特定任務上的表現突出並不重要，如果不具備優秀的軟技能，就無法讓自己成為有價值的團隊成員。所以我們需要軟技能來理解公司的目標和願景、認可工作的目的、溝通和接受想法、打造舒適安全的工作環境，並讓自己能夠發揮最大潛能。

也就是說優秀的員工，是同時具備專業技能及正向心態、良善的態度、積極的行為；但如果要取決的話，軟技會能更勝於專業技能。$wr$, $wr$$wr$,
