・拜訪世紀風電、興采實業$wr$, $wr$・選品會議
・更新獎酬辦法，溯自 2021 起$wr$, $wr$曾經跟台北團隊分享的「忒修斯之船」理論，這是我對自己的期待，我也很真實的透過學習不斷提升自己。

過年了，本想整理一些學習資訊，希望在新的一年讓大家方便運用，也怕一次資訊太多，吸收不良，決定逐個介紹。

學習工具一：得到 App, 這是我每天必用的工具，利用十幾分鐘的碎片時間就可學習一個知識概念，非常好用。其中有一個欄目叫做「啟發俱樂部」，開場白如下：

「七天长吗？不长，一晃眼就过去了。无非就是七次睡过去，然后七次醒过来。

七天短吗？不短，七天一点儿也不短。足够产生很多新的想法。

比如说读了一本书，或者跟有趣的人聊了个天。七天足以让我们变成另外一个人。」

是的，只要承認自己的不足，用心思考，擁抱新知，七天足以让我们变成另外一个人。$wr$,
       $wr$還記得今年初最流行的 App 是什麼嗎？是 Clubhouse。根據 Sensor Tower 的數據，Clubhouse 今年 2 月下載量達 960 萬，這種新形態的語音社交模式，不只讓人一窺「聲音經濟」的魅力，也帶動國內外 Podcast 的滲透率與黏著度。

台灣本土最大 Podcast 託管服務平台 SoundOn 日前公布最新數據，目前集團全球用戶突破 1100 萬人，海外活躍用戶超過 5 成。這一年來，累積創作者達 2 萬人，產出超過 10 萬小時的聲音節目，用戶使用時間平均每天超過 42 分鐘，平台總聆聽量超過 14.8 億次。

不只創作者眾多、產出豐富，聽眾的黏著度也提高。KKBOX 公布旗下 Podcast 的收聽數據，用戶每天平均聆聽時間從 2020 年的 40 分鐘，攀升至 70 分鐘。2021 年新上架單集數達 62 萬，總播放次數超過 1100 萬。

