很多時候我們會被自己的遠大抱負或是周延的想法給困住自己，很多事情做了就知道，做了就會了，不需要很厲害才能開始，是開始之後才能變厲害。別在還沒開始之前，就被自己給打敗了！相信自己一定做得到，努力練習，持之以恆，可能不一定會得到 100 分，但練習一定會讓自己更好！「想，都是問題；做，才是答案!」

于嵐：

翻到日曆發現 01/24 周一是讚美日，剛好呼應到我們最近的讚美夥伴的活動，

言語的力量是很強大的，根據研究，如果父母能常常肯定孩子的優點，小孩也會因為時常受到讚美的澆灌而越發成長茁壯，成為一個更自動自發的好孩子。不過不只是小孩，大人也需要讚美喲，讚美不只能夠帶給對方快樂和滿足，更是讓對方感覺到被認同的象徵，不管是 01/24 還是平日都需要不吝讚美夥伴，更別忘了讚美自己。

明隆：大智若愚 審時度勢 中國的成語就這樣簡單闡釋了, 確也醞釀多方的思維, 團隊里多點作實事的人 勝過好施小慧的聰明人, 反之就會有排擠效應〈洛克菲勒写给孩子的 38 封信 第 14 封信 做傻的聪明人〉$wr$, $wr$$wr$,
