select $wr$b000000cbjefupu$wr$, $wr$2022-01-28$wr$, $wr$・制定新版獎酬制度，溯自 2021 起適用$wr$, $wr$・閱讀、思考、計畫$wr$, $wr$知識學習平台＃2：Podcast

Podcast（臺灣和香港直接稱為「Podcast」；中國大陸稱為「播客」）是一種數位媒體，指一系列的音訊、影片、線上電臺或文字以列表形式經網際網路發佈，聽眾可下載或串流當中的檔案以欣賞。

Podcast 是 iOS 原生的服務，Android 用戶也可以使用，請參考：
https://support.google.com/websearch/answer/9049144$wr$,
       $wr$佳芸：不只 Podcast！聲音經濟還隱藏超多商機，如何抓住聽眾閒暇時間？

ASMR 刺激聽覺，成為高共感的行銷攻心術

ASMR（Autonomous Sensory Meridian Response，自發性知覺神經反應）是指當人們聽見特定聲音、或者看到特定視覺效果時，會伴隨而來的愉快酥麻震顫（Tingling）感受，吸引了許多在緊張生活中尋求放鬆的人們。

而除了演唱會之外，也有許多零售大牌運用 ASMR 進行行銷，用細緻的聲音抓住消費者的「耳朵」，讓消費者高度共感，帶來的望梅止渴商業綜效。

聊天機器人哄睡、陪聊，安撫人們心情

事實上，聲音的療癒不只能幫助行銷，也能在心理方面撫慰人心，助長相關應用的開發。其中，美國心理療法新創公司推出的「聊天機器人 App」Woebot 便是運用自然語言處理來模仿對話，偵測病患的關鍵字給予適當的回覆。

除了心理諮商類的陪聊之外，也有新創公司開發「哄睡」功能的聲音服務。冥想軟體 Calm 創辦人 Michael Acton Smith 所作計畫「Mind Candy」衍生出來的 Moshi，就是一家想要協助哄睡小朋友的公司。$wr$, $wr$淑倩：學習的資訊越來越廣泛，讀書是其中的一種。讀書能增進人的思考能力，豐富想像力，並給予人進步的力量。

因讀書能潛移默化，當我們在閱讀中學習新知，大腦的狀態能和書中體驗的新知狀態很接近。體驗會對新知的形成有所影響，能懂得書中傳授，就可以得到知識並變得自信帶來改變。

所以個人的體驗有限，多讀書可以讓人獲得更多的體驗，能幫助我們持續地學習新知、累積知識，不知不覺受到潛移默化而增長知識、提高思考力與進步的力量。

振慈：在工作職場上遇到我們不會的、不熟悉的或是自己無法掌控的，往往會有焦慮的心態產生，很多時候我也會這樣，不知道自己做不做得到，看到一本書《來談談那些痛苦的事吧！：商務人士的父親為孩子所寫下的工作本質！》裡面寫到一些內容，覺得很有感觸，頓時也讓自己豁然開朗。你對工作感到「焦慮」嗎？只要你今後繼續成長，那樣的焦慮就永遠不會消失。但沒關係，因為你終究會習慣這樣的焦慮。然後與焦慮共存的你，必定能把焦慮當成燃料，越變越強，焦慮正是你仍在持續挑戰的證據。挑戰的「焦慮」是對你未來的一種投資。逃避該焦慮就等於不去承擔失敗的風險，亦即選擇了什麼都不挑戰。那麼之後，你必定會被吸進所謂「永遠消除不了的焦慮」的更惡質黑暗中。焦慮是正常的，焦慮也是勇氣的表現，勇於挑戰，比起「不挑戰所以不會失敗的自己」，「因為挑戰而失敗的自己」絕對會變得更強大。

麗嘉：最近在做一個代工客人的案子，這個客人跟以前我接過的貼牌客人有一點不太一樣，案子有比較複雜一點。

在與客戶討論的過程中，很常請教 Emily。她很樂意得教我代工的流程並分享她的經驗和知識。我覺得理解這個流程的順序很有幫助，在遇到問題的時候也比較能夠想出下一步要做什麽，要找誰。

因爲自己覺得需要留這份檔案當手冊，所以把流程記下來了。後來發現 COMART 的筆記本裏面就有一張非常清楚的圖，所以決定把這一張圖用 XMIND 做成電子圖檔，之後如果有新同仁也可以分享給他／她。之後可以再把每一層展開寫更多細節，覺得還不錯。$wr$, $wr$敬致 各位親愛的夥伴們，

虎年春節即將到來，值此喜迎團圓之際，謹向各位夥伴致上最真摯的祝福，祝願您在新的一年裡，闔家健康平安、生活事事如意、工作虎虎生風！

新年快樂，平安吉祥！$wr$,
