Google 數位學程：上百堂免費課程、6 大技能認證

對此，Google 宣布在台灣推出數位學程，由上百位貢獻者提供教學，免費提供數位相關課程，用戶只要登入 Google 帳號，即可觀看，並在網路上進行證照認證。

全球 60 國同步，Google 數位學程期望幫助中小企業培養數位思維。在 Google 數位學程當中，有超過 20 個主題課程，包含數位思維入門、網路門面、搜尋引擎、追蹤分析數據等，Google 台灣行銷副總經理利啟正指出，現在學程中包含上百堂課程，且仍在持續增加中，朝更完整的學習系統發展。

