       $wr$于嵐：Z 世代有感的網路服務設計建議

Z 世代（Generation Z、Gen Z）指的約是 1997 年（25 歲）至 2012 年（10 歲）間出生的小孩

1. 別一直打廣告

在網路服務設計上，採用簡潔有力的 UX Design，能直覺性的找到「需要的訊息」，琳瑯滿目的廣告闖關不但沒有增加好感度，還會加速離去。

註：UX（User Experience）使用者體驗

2. 吃誠實豆沙包（誠實很重要）

品牌在網路上必須盡量誠實以對，才是上上策

3. 回歸品牌初心

Z 世代們身長在世界巨變的環境、重視兩性平權、冰山融化議題、環保意識等等社會議題，這點也反應在選擇品牌上，比起盲目追隨，更看重品牌個性與價值觀

4. 快一點，快就對了

Z 世代已經很習慣在 3-5 個不同的數位載具（PC、Mobile、iPad、App、TV、Alexa 等）上切換自如，注意力持續時間較短

5. 資安，哪次不講資安

Z 世代希望品牌在服務上可以公開透明，但他們在展現自己的同時，又期盼這些開放性平台能夠保護個人隱私

面對 Z 世代，跟風不是好策略$wr$, $wr$振慈：最近看了前東京著衣創辦人周品均寫的一篇文章，內容提到關於高薪工作者的 5 種習慣，雖然好的工作態度有可能間接影響薪資的水平，但更重要的是好的習慣和態度，可以讓我們的產出品質穩定，並且在工作上獲得成就感。5 種習慣：1. 主動報告手上處理完的事（凡事有交代，件件有着落，事事有回音）2. 對事情的執行度要高 3. 如果被糾正或被要求改善 4. 經常展現配合度與積極度 5. 保持你的穩定度。我覺得其實平常我們經常宣導的企業文化以及在工作態度上的要求，幾乎完全符合以上五點，很多時候我們可能已經正在做了，但我們卻沒察覺，好的習慣要繼續保持，持續改善不足的地方才是最重要的。

艷梅：稻盛和夫将人分为三种：不燃型、可燃型、自燃型。稻盛和夫就是一个典型的「自燃型」人。

「不燃型」的人永远一副无精打采的模样，对什么都提不起兴趣。

「可燃型」的人容易受到周围事物的影响，总需要人指点帮助。

唯有「自燃型」的人，他们永远保持着积极乐观心态，热情洋溢地生活着。别人眼中的苦差事，对他们来说，却是乐在其中。

春节假期，亲朋好友相聚畅聊，发现大部分人对家庭婚姻、经济来源或工作事业，都有不同程度的焦虑和不安。虎年伊始，万象更新，愿大家都要都能成为「自燃型」的人，在日常的工作和生活中，感受喜悦和幸福。

芳杏：今天 OKR 的課程，老師舉例說明粉絲頁流量等，各種的做法都要有關聯性，讓我意識到「關聯性」不是單一行為，事情做完就好，在業務面我很清楚沒有開發客戶就不會有新客戶，沒有新客戶就沒有訂單，沒有訂單就不會有業績，很明確的關聯性，日後可以更多的思考連結，開發轉換多少新客戶，新客戶轉換多少成交數等，邊做邊改善目標，討論、分析、共同學習成長，達成 2022 年業績目標。

軍徽：利他之心在工作的感悟：人存在的意义在于对社会奉献自我价值，企业存在的意义同样在于为社会奉献价值提供服务，万事万物无不如此，一切的成功都归结于利他之心，这是日本被誉为经营之圣的稻盛和夫基于自己八十多年人生经历的思考和总结，他说，人生的一切都是内心的投射，都是自己的内心吸引而来的。并强调说，这是驱动这个世界的绝对法则，是推动一切事物运行的真理。为什么稻圣和夫一生能够创造出两个世界 500 强企业？就是因为他时时刻刻以利他之心经营企业，经营人际关系，经营自己的一颗利他之心。如果没有利他之心，也就是王阳明所说的人欲，私欲，说的再直白一点就是私心太重，天长日久，就会越来越功利，急近功贪近利，修身正心的目的就是把自私自利之心，修正为无我利他之心。我们在平时的工作中要多有利他的心态，换位思考，相互间多提醒对方避免出错的机率，少一些埋怨多一份努力。这样才能有更好的人生。$wr$, $wr$$wr$,
