・拜訪數位時代$wr$, $wr$$wr$, $wr$知識學習平台＃4：

最有趣多元的線上課程都在網大－隨時隨地 在家也能輕鬆學

中小企業網路大學校平台係提供線上學習資源、實體課程培訓、活動資訊等一站式企業學習服務，整合虛實學習資源，提供多元化的新學習模式，辦理主題班、研習講座、論壇等，提升創業者或有意創業者、高階領導人、傳承接班等所需知能與企業人力培育能量。多數是免費的。

