       $wr$昕緯：

德國政府 2021 推動「七年壽命週期」提案，要求手機廠商提供手機七年的安全更新和備件維護，降低更新換代的頻率，達到更加環保目的。

老舊手機出現故障，維修成本非常高，很多人會更加傾向於選擇買一部新手機來用。

關於「手機能用多久」這件事，實質上變成了「手機維修服務能維持多久」。

歐盟提出「七年壽命週期」，讓手機維修服務以合理的的價格存在下去，在軟體逐漸成為手機行業營收重點，不僅是來自用戶的現實需求，也會是智能手機設計的一個重要趨勢。

對於當今手機更換速度趨緩的使用變化，也許能考量當中所衍生的「舊手機的續航使用」、「讓手機看起來像新的」的配件需求。

芳杏：

挪威最「綠」挖礦場，連熱廢氣都有用！

比特幣之所以會對環境產生負擔，主要是受到用電量的影響。要開採一枚比特幣，主要靠電腦解決計算程式難題作為工作量證明（proof of work）。當「挖礦」的電腦增加，用電量也會隨之上升。而目前化石燃料仍是大部分國家主要發電的來源，於是用電量的增加就會造成環保問題。

挪威最大的比特幣礦場位於一個名叫 Hønefoss 的小鎮，在小鎮的郊區有一間 5,000 平方公尺的大倉庫，這是挪威公司 Kryptovault 擁有的兩個礦場之一。雖然 Kryptovault 佔全球比特幣網路中運算和處理能力只有不到 1%，但是這個礦場不僅完全使用綠色能源挖礦，業者還利用挖礦產生的熱廢氣來乾燥木材。

熱廢氣可以說是在挖礦過程中無可避免的產物之一，而 Kryptovault 利用這些廢氣烘乾潮濕的木頭。因為當地常常下雪，這些原木原本需要好幾天時間才能完全乾燥，但是利用礦場的高溫廢氣能夠快速烘乾這些木頭，並提供這項烘乾服務讓當地的伐木工出售。

Pettersen 表示，在未來某個時候，一個又一個國家將採用比特幣作為法定貨幣，到時加密貨幣將改變世界，就像現在社群網路的發展一樣。

→ 企業能獲利，又能用餘裕資源解決社會問題，也是一種社會企業。$wr$, $wr$林森：OKR 学习有一段时间了，本以为自己已经理解了其原理，但实行过程中发现自己了解得还远远不够。

它不是一个人自己简单的定一个目标，写几条执行事项，不是一个人的事情。

它是需要大家，不同部门，共同协调，为了同一个目标去努力，每一个人为了这个目标，或者协助别人的目标，而在此基础上去主动定制自己的目标，是需要所有人一起去努力，互助达成的。

可能我的理解还是过于片面，但相信后续继续学习和理解，将更清楚如何去做，如何去确立自己需要做的和协助别人要做的。

每个部门，每个人，不应该是一座孤岛。

→ 理解正確，各單位都不是獨立存在的，每個人或部門的努力都必須為企業最終績效、成效產生正面的影響，否則就是資源的損耗。

雲丞：「如果你有的只是一個錘子，那麼所有的東西看起來都像一個釘子。」人在面對問題時，常傾向用自己最擅長的方法解決，落入「專業陷阱」。

錘子法則提醒著我們，不要只會用一種工具，也不要只從一個角度看待事情。這也是為什麼，有很多公司願意高價聘請顧問，向其諮詢各種決策。這些諮詢顧問會從另外一個視角分析公司目前遇到的問題，由於思維模式不同，外行很容易看出問題。

因此，我們需要時時提醒自己：

1. 不要只用一個工具，更不要只有一個工具。
2. 每個工具都不是萬能的，要了解它的適用場景，用對了地方才能發揮最大作用。
3. 保持開放心態、多參考他人意見、並且時常留意其他新觀點，讓自己的工具箱更豐富。

于嵐：周二早上參與了寶可齡的會議，覺得很不像在介紹產品，感覺很像是講解知識，對於牙齒的清潔，原來牙線棒跟牙刷都無法將牙齒徹底的清潔乾淨，所以我們需要看牙醫讓牙醫幫我們洗牙，達到清潔的效果，但也不能總是靠牙醫，所以沖牙機就顯得很重要。另外設計的包裝也是很有趣，本來沒有特別意識到人類有幾顆牙齒，但聽寶可齡說設計包裝上有 32 個三角型就是代表人類有 32 顆牙齒，買產品還帶著其他樂趣，覺得很特別，我們的包裝也可以設計的比較有趣，也有助於行銷的操作。

祐維：接觸了很多現場購買客戶、與門市人員互動經驗，發現客戶常遇到不知道挑選哪個支架才適合汽車環境的狀況，變成購買過程花費的時間拉長，針對實體賣場或是線上挑選商品的客戶，假設能用一張圖能幫助客戶快速辨別，自己喜歡的手機支架放置的位置（前擋、儀錶板、冷氣出風口、CD 插槽、A 柱等），旁邊簡單備註消費者挑選比例或是優點，相信能大大提升購物體驗，更甚者眼鏡品牌 OWNDAYS，線上官網提供虛擬試戴功能（藉由智慧型手機鏡頭與 AR（擴增實境）功能結合），假設能有類似的功能可以讓客戶虛擬試裝，輕鬆找到適合的商品，一定很酷。

淑倩：讚美彼此，正是彼此互相欣賞、互相了解、實踐說好話的大好時機。

曾聽說：「嘴巴即是風水！」確實如此。讚美即可改運，命運的塑造不在於外面的硬體，而在於你我的口、意之間，將我們的想法藉著口訴或文字的傳達給對方。如果與人相處時，能常常找尋對方的亮點，學習表達具體的讚美，定會受歡迎，自信就會更加自然而然的被營造出來。

由此可見，讚美確實是最簡單的自信心靈之鑰。

文千：最近跟外购品厂商沟通很频繁，厂商的回应速度，专业度，服务态度等都有一定的差异性，这些对于供应商日后的评鉴都有一定的参考标准。反思我们业务作为对外沟通的第一窗口，客人对我们的评鉴指标主要是哪些呢？

1. 及时性：我觉得这是最最重要的一点，接收到客户的需求，无论是询价，样品需求，订单需求等，第一时间回复客人消息非常重要。让对方知道我们有接受到这个资讯，并知道我们可以提供需求的时间，做一个凡事有交代，件件有着落，事事有回音的业务。这是对客人最基本的尊重，无论大小客户，代表了重视客户的态度。

2. 配合度：配合度包含多方面，比如打样需求、交期需求，账期需求等，也是我们一直提倡的服务度，配合度高的供应商，合作起来会顺畅很多。

3. 专业度：产品的专业度，对市场的解析度会让供应商会帮客人思考的更多，推荐产品也比较有针对性。

4. 跟进度：报价或送样出去，及时询问跟进进度，会促进采购方也主动去了解并反馈进度。

→ 整理得很好，有架構，也很適合自我檢討。但我們如何得知我們客戶眼中的我們？我想，是需要主動去詢問的，我們（以及主管）有必要經常去問問我們客戶覺得我們的及時性是否滿足？配合度是否滿意、專業度是否足夠、跟進度是否適切？還需要改進哪些地方？作為持續改善的方向。

芳杏：吸引力法則：討厭和恐懼都是一種力量，當你想著什麼就會吸引什麼來到眼前。所謂道不同不相為謀，保持適當的距離，避免增加討厭或恐懼的能量。「討厭是種力量，恐懼也是種力量，當你一直想著這些，他們就會到你面前。」職場上，總會遇到討厭的人事物，甚至是討厭的客戶，發生問題，面對他，處理他，別讓討厭的情緒成為自己的工作負擔，討厭的人不會因為你的討厭或不悅而不存在，提醒自己，討厭也是一種力量，想什麼就吸引什麼，所以深呼吸一口然後把討厭大力吐出來。

軍徽：最近看完了一本书《责任胜于能力》，责任胜于能力，是一个浅显易懂的道理，大家都应该能理解并明白：再有能力的人如果没有责任心，那所有的行为结果都会打折甚至无法完成。对工作负责，就是对企业负责; 对集体负责，就是对自己负责。一个员工的能力再强，如果他不愿付出，就不能为企业创造价值，而一个愿意为企业全身心付出的员工，即使能力稍逊一筹，也能创造出最大价值。一个缺乏责任感的人，会失去自己的信誉和尊严，失去别人对自己的信任和尊重，失去社会对自己的认可。在现在的企业当中，没有做不好的工作，只在于你是否选择去做。我想如果每一个企业员工都对自己的岗位负责，那么无论你是职位高低，都会给别人信任感，会吸引更多的人与你合作。无论你所做的是什么样的工作，只要你认真地、勇敢地担负起责任，你所做的事情就是有价值的，你就会获得尊重。责任产生忠诚。而忠诚，会让你承担更大的责任。一个人，只有对他所从事的职业充满责任感，他才能对企业忠诚。对企业忠诚，才能赢得企业管理者对他的信任。我们要做一个有责任感，有情义，有担当的人，安心做好自己的工作，劳于先而后享乐，对自我负责，对他人负责，对社会负责，通过自己的努力，让大家都过的平安幸福。$wr$, $wr$$wr$,
