上週因舉辦活動需求兼程拜訪了經理人總部與經理人創辦人，入門接待處放了兩個大屏幕，分別是數位時代與經理人的在線流量與 GA 數字分析，表示他們極其注重數據分析與即時掌控，印象深刻！這是我們未來要補強的能力。

