       $wr$振慈：〈快行銷時代：運用技術、數據、顧客三大共好，擘劃美好行銷科技的進行式〉from 數位時代

隨著科技急遽發展、環境瞬息萬變、資訊過度超載，行銷人所必須面對的挑戰將更加複雜而艱難。在這樣的快行銷時代下，「去中心化的自助服務」、「創新產品與服務」、「資料預測與分析能力」、「極致個人化體驗」、「規模化流程」這五大關鍵字，是不可不知的關鍵能力與技術。

去中心化的自助服務：善用生態系戰略，建構消費場景，實現更敏捷、更快速且優於傳統開發的開發週期。

創新產品與服務：數位工具的普及，行銷人將以數據資料推測潛在商機、資料分析打造竄紅爆品，強化開發與分析能力。

資料預測與分析能力：快速落實與驗證商業決策與創意，找到產品與市場的完美契合。

極致個人化體驗：利用人工智慧、即時數據分析，提供貼心的個人化服務，增加顧客體驗。

規模化流程：熟悉 Low code/No code 工具平台，減少重工、自動化降低營運複雜性，降低營運成本。

全文：https://www.bnext.com.tw/article/67686/how-the-low-code-movement-helps-marketers$wr$, $wr$可欣：這週進修 TTQS 課程建立了個新觀念，讓我們了解教育訓練（學習）應該是『領先指標』而不是落後指標；舉例迪士尼樂園的員工服務精神幾乎已成了全球服務業的標竿，但其實迪士尼中有 90% 以上的員工都是工讀生，他們能脫穎而出的關鍵，是先花時間做好完整的『教育訓練』並且讓員工『了解自己的工作使命』；平均一位新進人員要花費一個月的時間做教育訓練，並讓他們知道工作「做完」和「做好」的不同，讓每個人都能了解自己的工作所賦予的使命。公司的每一位夥伴其實都代表著公司，不單單只是業務同仁，即便是代接一通電話，呈現出的也是代表公司的一部份。

佳鈴：若能夠以利他之心作為判斷事情的初衷，週遭的人會樂於提供協助，也讓視野更為遼闊，思考也更加全面，於是能夠做出正確的判斷。而利他的最高境界，是擁有高層次的判斷基準，即不被矇蔽的判斷能力，能夠清楚地看見所有的事情，並一眼洞悉做出什麼事情可能招致什麼樣的後果。將利他之心融入於日常之中，就能以利他的思想帶動自己，進而在生活中有具體的利他行為。久而久之，習慣如此的思考模式之後，便能培養出利他之心，也更接近更層次的判斷基準。

怡芳：客人不滿意，才會跟你反映，業務人員不應該急著跟對方「講道理」，或把客人定位為「奧客」，更遑論與對方爭執

「不要和笨蛋爭吵，否則就會多出一個笨蛋。」如果遇到無法控制情緒的狀況，那就離開事發現場，請你的上司立即出面處理吧。

對方不是針對你！盡快解決問題

扳倒顧客是雙輸，我的 6 點心法

以下幾點可以幫你在氣憤的顧客面前保持冷靜：

（1）讓顧客盡情抱怨。聽顧客把事情的來龍去脈講一遍。有時，顧客需要的只是有人傾聽。

（2）對問題承擔起責任。不要推卸責任，不要辯解，不要找藉口。

（3）盡量找出簡單快速的解決方法。如果實在沒辦法，那就問顧客能不能讓你在二十四小時或四十八小時後再聯繫他們。恭敬的態度能夠撫平絕大多數顧客的情緒。另外，顧客氣消之後，要比正在氣頭上時更容易接受你的解決方案。

（4）君子能忍則忍。有時，失誤的確歸於顧客，想要打贏舌戰確實易如反掌，但打仗的成本實在太昂貴了。有時，忍一忍才是更好的選擇。如果閉口不語能讓你留住顧客，又何樂而不為呢？

（5）為顧客投訴建立暢通的管道。

（6）莫忘最終的勝負。當你扳倒顧客時，實際上雙方都輸了。

怡萱：人在江湖不僅要懂說話藝術，說話的語氣和語調也極為重要。之前在一篇網路文章中看到一句話：「一個人說話的語氣比講話的內容更為重要」，每個人都有自己習慣的說話習慣、語氣，我們也可以從一個人說話的語氣中，感受到這個人對人、對事的態度。

我們的說話「語氣和語調」不僅能表達出情感和情緒、還能表達出我們對交談對象的態度與重視。與此同時，語氣也是反映了一個人教養的重要因素，好的說話語氣，更代表了一種禮貌和修養。語氣更是影響一個人專業形象的重要因素，對你的聲音好感度增加，也會對你的專業能力提升信任感，如果說話的語氣好，會讓對方想更認真聽，反之亦然，不僅會想讓對方趕快結束對話，對你的專業能力也會大大的扣分。

如何培養和加強自己專業的聲音，是在日常生活和職場中必學的必修課。$wr$, $wr$$wr$,
