       $wr$許多人總受失眠困擾，不過近日一項醫學研究顯示，若人在睡前玩手機 8 分鐘，恐興奮超過一小時，導致難以入睡！醫師提醒，現代人睡眠問題越發嚴重，其實就和睡前過度使用手機有關，這會使人入眠困難、延遲等，因此建議將使用時間控制在 20 分鐘內。

根據《CTWANT》報導，美國睡眠評估平台「Sleep Junkie」，日前針對 2012 人進行睡眠數據調查，結果竟高達 78％ 對象承認，自己睡前總習慣先玩手機一段時間，入睡平均恐需一小時，這也稱為「報復性睡眠拖延症」。

至於失眠原因，專家解釋為視網膜的內生感光視神經細胞，因受「藍光」刺激造成身體持續興奮，且睡前滑手機容易刺激腎上腺素及多巴胺釋放，給人快樂的感覺，才會導致睡眠不斷延後。

根據《央視頻》報導，醫師指出「睡前滑手機」確實會影響睡眠，除了恐出現入睡困難、睡眠時間延遲外，另一方面也可能造成睡眠品質下降。醫師進一步說明，睡眠環境需要黑暗來促進褪黑素釋放，若視網膜受到過多光線刺激，尤其是手機螢幕藍光，這將嚴重影響視網膜感光作用。

大家晚上使用手機時，務必特別留意環境光線，尤其在睡前關了燈後，整個臥室只剩手機明亮發光，這樣照射恐造成非常大的潛在影響，因此醫師建議可將手機亮度調低，亦或採用夜間模式來減少藍光對視網膜的刺激。$wr$, $wr$文千：摘录于《真北》

1. 真正的领导者往往是从自己独特的生活经历中发掘出领导热情，并以此培养员工的领导才能，激励他们走上领导岗位。在领导者的成长过程中，最关键的就是你的性格和价值观。

2. 用目标和激情去领导：作为一名领导者，你必须保持整个组织的使命清晰，同时不断传达一种持久的激情。只有当领导者能够激励员工为一个共同目标努力时，他们才能产生持久的作用。

3. 领导者的任务之一，就是为自己的团队成员提供服务，要学会激励身边的人、培养他们，并帮助他们学会改变自己。这是你必须面对的挑战。

4. 你必须意识到，在整个领导过程中，最重要的人并不是你。要想真正领导其他人实现一些更伟大的目标，就一定要放弃个人英雄主义的想法。

5. 对人心最大的考验就是弯下腰去，抬起别人。这就是生活的真正意义所在。

芳杏：最大的醫療用品通路杏一醫療，門市採用具有護士背景的銷售人員。然而，護理工作重視 SOP，無論感冒打針或重症急救，都必須按照既定步驟進行；門市銷售卻重視與顧客每次不同的互動，要傳遞感受。為了讓員工從醫療專業轉換成銷售文化，杏一醫療董事長陳麗如常對門市人員「說故事」。

護士出身的陳麗如本來也不善言詞，但為了打下服務的基礎，她開始蒐集在各家門市發生的真實故事，在巡店時說給同仁聽。曾有一位罹患咽喉癌的老榮民，進行切除手術後，必須借助發聲器才能說話，走進杏一門市詢問，才發現當時沒有進口這項產品。老伯失望之餘，店長卻主動詢問其他醫療用品店，花了一段時間找到發聲器，還為老伯申請「台灣無喉協會」的會員。收到發聲器當天，這位老伯又來到門市，原本店長以為是產品出問題，沒想到老伯卻對她說：「店長你好，我想把第一聲謝謝獻給你。」

陳麗如用這個故事，向員工傳遞「服務業永遠不嫌麻煩」的理念，「沒人愛聽老闆訓話，故事才能讓人融入情境。」

