傳統的 KPI，比較偏向本位主義，個人績效優先。但 OKR 強調透明運作的機制，從執行長到基層員工，所有人的目標公開共享，公司會先訂出一個企業發展的共同目標，接下來各部門都會有個別的目標，但最後都要集結在共同目標之下，這個價值主張是很多企業缺乏的，企業規模愈大，更難做到。

OKR 在制定目標時，非常強調由下而上的決策討論過程，所以很容易檢討出過去訂的 KPI 當中有什麼缺失？是不是之前對公司的整體目標不夠了解？或是目標不切實際，甚至無法達成？

當 OKR 推動成熟後，就會改正許多目前管理上的缺失，更容易達成施崇棠一直強調的「眾志」。因為 OKR 強調契合與連結，全體員工可以共同參與目標設定的過程，當大家都寫下自己的工作計畫時，很容易發現最好的點子。這樣的過程也能夠培育協作的精神，當某位同仁看起來難以達成某項季度目標時，大家都可以看到他需要幫忙，便會有人伸出援手、提出建議，共同改善落後的進度。

=> OKR, 每個部門都有主動的責任，應著重在團隊協同合作，與其他部門共同解決問題。在組織內，每個部門都要對總體目標負責。$wr$,
       $wr$雲丞：

SONY 牽手 HONDA，2025 推首款電動車！背後目的是？兩大車廠如何合作？

對抗特斯拉（Tesla），日本電子產品大廠 Sony 和日本汽車大廠本田汽車（Honda）宣布將合攻電動車（EV），雙方將設立合資公司、目標在 2025 年開賣首款電動車款，而首款電動車的製造將委由本田進行。

Sony、本田 4 日於日股盤後發布聯合新聞稿宣布，雙方已達成基本共識、將於電動車事業進行戰略性合作，藉由將本田長年培育出的研發能力、車輛製造技術、售後服務和 Sony 的感測器、通訊、網路、娛樂技術相結合，實現貼近用戶和環境、持續進化的新時代移動服務。具體來說，雙方目標在 2022 年內設立一家合資公司、共同研發、販售高附加價值電動車，且目標在 2025 年開賣首款電動車。該家新公司將負責電動車款的企劃、設計、研發、銷售等業務，但不會擁有自家生產設備，首款電動車的製造預估將委由本田的工廠進行，而 Sony 將研發移動用服務平台、並提供給新公司。

Sony 電動車事業考慮採取「訂閱型」商業模式

Sony 會長兼社長吉田憲一郎 1 月 5 日在 CES 會場接受媒體採訪時表示，Sony 開始就進軍電動車市場一事進行評估，而電動車事業考慮採取「循環型（Recurring，即持續性收費的訂閱制）」商業模式。據悉，Sony 考慮的方案為藉由「循環型」模式提供車輛，或是藉由「循環型」模式來進行軟體更新擴增內容、功能。

2022 年電動車銷量有望超越油電混合車

日本研調機構富士經濟（Fuji Keizai）2021 年 7 月 9 日公布調查報告指出，隨著車輛價格下滑、基礎設施整備完善，長期來看，電動車將成為電動化車款的主流，預估 2022 年電動車銷售量將超越油電混合車（HEV），2035 年全球電動車銷售量預估將大幅擴增至 2,418 萬台、將較 2020 年跳增 10 倍（暴增約 1,000%）。$wr$, $wr$佳芸：什麼是上游思維？如果今天你住在一條河川的中游位置，你每天生活所需的各種用水都要從河川取得。這條河川的水很乾淨、清甜。有一天，你發現河水有怪味道，然後伴隨著大量的垃圾從上游漂了下來，經了解之後發現原來是上游的居民將垃圾傾倒進河川裡所導致。請問：「此時的你會怎麼辦？」

幫助上游，就是幫助自己

協助對方解決問題通常是比較簡單的，很多時候上游可能因為能力不足、資源不足，所以給你帶來麻煩，你有所準備，甚至主動協助對方解決問題，一切就變得簡單了。別老想著別人刻意給你製造麻煩，先想想他是不是無能為力。別老想著那是對方的責任，先想想可以做些什麼來跳脫現況。其實組織內向上跟橫向溝通的訣竅並沒有那麼複雜，先從這個點切入思考，其他問題自然會比較容易解決一些

淑倩：分享本身是一件快樂的事情。為了分享知識，會更努力把不清楚的搞懂，把沒學好的學好，並且思考如何表達。不難理解「教學相長」這個道理，能夠達到教、會、學的境界，顯然自己也需要花費心思在上面。為了講得清楚，就會再去鑽研幫助自己學得更好。而且，每講一次就會更加深印象。所以最好的學習就是把自己學到的知識，講解一次給別人聽。當自己講過後，連帶著自己也複習了一次，印象就深刻了。因為用語言呈現腦袋裡的知識學問時，需要經過再次整理與轉化等認知歷程；而當自己能清楚且完整地講述，表示對欲傳達的概念有足夠掌握。因此，分享本身就有助於對知識理解得更清晰。並且藉由回饋，會知道自己還有哪些概念是模糊的，哪些地方仍存在著盲點；就有機會回頭去複習與探究，補強不足之處。

芳杏：我們的客戶巨輪興業，成立 1990 年，董事長陳正忠，主要產品各類專業車輛警示燈具、照明燈具及車用警報設備。多年來提供高品質的視覺及聽覺警示設備解決方案，巨輪興業累積警用、消防、緊急救護支援、和公共事業服務等領域豐富知識，立足台灣、行銷全球。不僅持專注本業、創新研發，更用心打造優質友善的職場環境，成為深具國際競爭力的小巨人。

董事長陳正忠看過 QBQC 後，自覺問題的本身是自己，發現問題並能解決，從負面心態調節到正向，同時跟員工建立互信，修改制度更加透明，推動品質優化、自主紀律、學習成長與團隊合作等透過有系統、有策略的改變，營收、分紅的制度透明，建立坦承的文化，長期在社會公益上投注資源以及鼓勵員工也一起加入公司行列參與公益活動共同為社會實現共好。

我們就是這樣的企業。

慶鐘：最近在閱讀一本書，書名是《傻瓜一直在路上，生命的練習曲》，作者曲全立，是位匯集數位科技、藝術人文、工藝文化於一身，以鏡頭閱讀台灣的微觀與宏觀，為土地作傳的紀錄片導演。獲獎無數的曲全立導演，在經歷生命的無常轉折後，放下獎盃，走入偏鄉。結合生命、美感、科技、自然環境的教育意涵，以感動觸動靈魂，用生命，延續下一代的笑容。在他下鄉的其間看見了許多為生命努力活出精采平凡卻也不平凡的台灣超人們，勇敢做夢，活在當下。人生並不會一直風平浪靜，而問題不能構成停止前進的藉口，我們總能找到辦法解決問題，想做，拚了老命都會想盡辦法達成。不想做，就會找任何理由不去做，無論是在生活工作家庭人際上遇到的問題。閱讀的意義是什麼? 除了了解作者本身想藉由文字表達自身的理念外，身為閱讀者的我們呢? 學生時代我們為了找答案除了問老師同儕外，最直接的就是在書本上找答案，同理可證，在職場多年後也許忘記了閱讀這件事，當我們困惑時除了良師益友外，我們還是可以藉由大量的閱讀來找到我們要的答案，古人有句話，三日不讀書面目可憎。就是告訴我們要養成閱讀的習慣，藉由閱讀可以內化我們的底蘊，與人對談時也不會言之無物。$wr$, $wr$$wr$,
