自从集团推行 OKR 后，我们恒群的公司目标在跟着培训后不断修正，最近这次，叶先生加进了人员更具竞争力这个目标，将教育培训列为其中一个 KR。我觉得这个的确需要加入，因为培训是企业管理中非常关键的一部分，但往往又是最容易被忽视的一环。

当代最杰出的新管理大师之一彼得·圣吉曾在《第五项修炼》中写道：「在 21 世纪，唯一持久的竞争力就是比竞争对手学得快的能力。」

通过培训不仅可以提高员工的工作技能，更能增强企业凝聚力、提升员工稳定性。

企业文化与价值观的输出，有助于增强团队的默契度和凝聚力，更能切实的减少内耗，提升工作效率。

可能有人会说，说起来简单，做起来很难啊，做一次培训耗费的精力太大了，又费财力，又费人力，得不偿失啊。

其实，我们可以尝试一下在线培训，目前很多企业使用在线学习这种模式进行员工培训。在线培训让企业可以轻松举行大规模培训、轻松解决异地培训等问题。

同时在线培训比起传统培训成本较低，也正是因为如此，越来越多企业开始使用员工培训系统进行在线培训。例如华为的 E-Learning、iLearningX 等。

