淑倩：正能量才能吸引正能量，能量也是同性相吸，異性相斥的。正能量的人喜歡跟正能量的人在一起，負能量的人亦是。若我們是負能量的人，卻希望一個正能量的人來改變自己的生活，就會不舒服。所以我們選擇跟什麼樣的人在一起，終究會成為什麼樣的人。

正能量的人，有樂觀、積極、向上的心態，他們充滿熱情、希望與信念。能驅散你的霧霾、趕走你的煩惱，和他們在一起，會感受到快樂和自信；負能量的人，情緒多變，容易悲觀、畏懼、抱怨，看什麼都不順眼，會批評、指責和攻擊，跟他們在一起，會感覺不安全、緊張，處於防衛狀態。

比如跟正能量的人說「願景」，會感到有自信，很有希望的感覺。但跟負能量的人說「願景」，會感到沮喪，別做夢了！所以才要遠離負能量的人，如果想變得優秀、收穫滿滿，就該去接近充滿正能量的人。

