04. 人这一生，一定要有别人拿不走的东西。你读过的书，就是其中之一。
05. 读书的根本目的是为了让自己明白世界、看清自己，让自己在无所事事的时候，有一种严肃力量推动你往前走。
06. 只要打开书，就随时打开了一个崭新的世界。
07. 腹有诗书气自华。当看到天边飞鸟，你会说：落霞与孤鹜齐飞，秋水共长天一色。而不是：啊，好多鸟。读书会让你成为一个有温度、有情趣、会思考的人。
08. 我们没有办法无限延续生命的长度，但却可以增加生命的宽度和厚度，读书便是最好的方法。
09. 爱书的人，可以拥有一个忠实的朋友、一个良好的老师、一个可爱的伴侣、一个优婉的安慰者。
10. 读书，能解决 80% 以上的迷茫。你的问题主要在于读书不多而想得太多。$wr$, $wr$$wr$,
