本週芳杏的分享：

我們在傳遞訊息的時候，常常都沒注意到言語表達帶著什麼樣的情緒，以為沒人在意我們用什麼聲音語調。但是語氣如果是生氣、嘲諷或擺出一副趾高氣昂的樣子，對方常常只注意到口氣很差，卻忽略剛剛到底說了些什麼，我們的溝通失敗、各說各話！有時不是你說的不清楚，而是忽略了聲音語調這件事，導致別人無法記得你的話。

有好聽的聲音表現，不僅能建立良好的自我形象，更能強化說服力、提升溝通效率。

說話聲音好聽的 4 大訓練關鍵

一、音色乾淨紮實

我們要從清晰明亮、乾淨紮實的音色著手，透過這樣的聲音，聽眾不僅能輕鬆舒服地聽清楚你所說的內容，也更容易進一步接收、思考當下正在談論的主題。

二、音高自然恰當

說話時建議維持在舒適的中音域，通常也就是一般人講話舒適的音高。為了傳情達意，適當的音高起伏自然是必要的，也就是所謂的「抑揚頓挫」。

三、咬字清晰乾淨

我們講話時理應要將嘴巴張開，至少要讓聽者可以聽得清楚你所說的每個字，清楚的咬字絕對有助於提升溝通效率

四、語速穩定和緩

如果語速過快，對方很有可能會聽不清楚你所說的內容，日常聊天的語速通常是比較合適。$wr$,
