Web3.0 是一個非常新的觀念

Web 3.0 結合區塊鏈技術之下，其最大特色是保護你的隱私，再也沒有一家公司擁有你的個人訊息。Web 3.0 的宗旨就是去中心化抗審查，不會有一個中心化的機構來控制你、審查你。用戶對於自己的數據隱私，有絕對的掌控權。

而區塊鏈技術又與 Web3.0 的願景尤為契合，這也是它被稱為有價值的互聯網原因。區塊鏈技術中的智能合約是 Web3.0 的一個基石代碼、法律代碼及規定，一切規則被寫進協議，一旦開啟便不可竄改。代碼開源公開透明，接受所有人的檢查，同時區塊鏈節點分佈式的協同共識，把信任的需求降到最低，這之間只需要代碼驗證。

…

Web3.0 的概念其實還很新，只是未來有非常高的機率會朝這個方向去前進，這之間還有許多的事情需要克服，像是假的網路訊息或者是版權問題等等這一系列的狀況需要解決，當然在這之前各位可以先去深度了解，在未來新科技成長的道路上從容佈局！$wr$, $wr$林森：

费曼学习法，用教学的方式进行学习。把自己的知识分享出去，其实也是一种自我学习。

一、选择目标领域，并完全了解这个概念

将需要学习的概念写在纸上，尽可能的去熟悉这个概念。

1、一定要将自己脑海的语言组织出来并反应在书面上
2、如果写不出来再回去看哪里不懂

二、向别人复述这个概念

向身边人复述一遍你所学习到的知识，如果没有，就只好假装自己是一个老师，向学生复述这个概念，记住，尽量使用简单的语言，这一步是为了让你更好的融入自己的理解。在复述时，一定会在所难免的会卡住，或者结巴，叙述不完整。这时候，恭喜你，喜提知识概念薄弱点。这时候，将这些薄弱点重新学习巩固一遍，直到真正理解。

三、纠错之后的再次学习

把刚才学习的不完善的地方再次学习，回归原材料或者书本本身，直到能够流畅地阐述学习的知识点。

四、回顾和精简

走完上述三个步骤之后，想必你们可以能够很流畅精准地将概念完整的阐述出来。而现在我们需要做的是用我们理解的语言去阐述知识概念。

→ 謝謝，這個概念很重要！

雲丞：在過去服務客戶的過程中，也常發現許多主事者，對於每件事都有很多想像的畫面，迫不及待地希望我們根據他們的想像，提出執行的方式。但當回過頭問起客戶：「你希望呈現出這些畫面，最終的目的是什麼？」起初你會非常訝異，之後就慢慢見怪不怪的看著他們認真思考，或者帶些疑惑迷茫的眼神，回過頭來評估這個最根本的問題。清楚定義「目的」，依據此目的思考合理的策略，再給出至少不會引起負面爭議的執行方式，才是解決所有問題的關鍵點。

