       $wr$振慈：【在 FB 和 Amazon 投廣告，成效實測背後：網路巨頭勢力大洗盤？】

蘋果（Apple）、Google 相繼推出隱私政策變動，前者要求 App 必須徵求用戶同意，方可追蹤在其他網站或 App 的動態，後者則宣布要在明年淘汰第三方 Cookie，不只大幅降低投放客製化廣告的精準度，也讓用戶行為更難追蹤，尤其臉書（Facebook）身為數位廣告領域的龍頭，廣告成效受到重傷。

這兩項變化的目的，都是為了強化用戶隱私保護，但蘋果新政策上線還不到一年，《紐約時報》卻揭露：「你我在網路上仍被追蹤，只是方式不同！」

原來，追蹤重點已從第三方數據轉移至第一方數據，這反而讓 TikTok、亞馬遜（Amazon）、Pinterest、Snap 和 Google 等握有眾多第一手用戶數據的大型數位平台更吃香。規模較小的企業如果想用廣告網羅新客戶，需要求助於這些科技巨頭。

