心理學有個「破窗理論」這麼說到：

「環境中的不良現象如果被放任存在，會誘使人們仿效，甚至變本加厲。」

當一個團體裡存在著一個不適任員工時，其實整個團隊都在看主管會如何處理，時日一久卻仍置之不理，大家對主管的信任程度也會降低。

→ 論語‧為政：舉直錯諸枉，則民服；舉枉錯諸直，則民不服。

趙燦：伦敦街头，一个推销员在推销气球。生意稍差时，他就会释放一个气球。当气球在空中漂浮时，就有一群新顾客聚拢过来，这时他的生意又会好一阵子。他每次放的气球都变换颜色，起初时白的，然后时红的，接着时黄的。

过了一会儿，一个黑人小男孩拉了一下他的衣袖，望着她，并问答一个有趣的问题：先生，如果你放的时黑色的气球，会不会上升？推销员看了一个这个男孩，就以一种同情，智慧和理解的口吻说：孩子，那是气球内部所装的东西使它上升的。

个人感悟：气球内所装的东西使它上升，同样，也是我们内在的东西使我们进步。

彥菩：如果你的職業是業務，只要每天比別人多一張訂單，兩個月下來就能比別人多幾十張訂單，如果你是工程師，只要每天晚上比別人多鑽研技術一個小時，一個月下來就比別人多了三十小時的專業知識。

每天都比別人多累積一點，這句話的重點不在於「累積」，而在於「每天」，這也是這件事最困難的地方，畢竟人有惰性，要每天都持續比別人進步一點是很難的一件事。

事實上，每個人的進步都是在每天逐漸累積的，即使你當下沒有發現，但人幾乎每天都在變化。

人生當中，無論你想做什麼事，無論你想改變什麼，你並不需要一口氣改變很多，你只需要每天都進步一點點、前進一點點，一年後的你就會變得很不一樣。只要每天都能進步一點點，日子一久就能產生巨大的差距。每天都確保讓自己進步一點，即使無法立刻到達也沒關係，只不過，不要忘了前進。

伯恩斯坦曾說：「想要成就偉大的目標，你需要的是計畫，以及不太夠的時間。」懂得平時不斷累積自己能力的人，才能開拓出自己的成功道路。

來造就未來的大改變，這也是改變這件事困難的地方，改變需要持續不斷的累積，只要確保每天都比昨天更好一點、多學一點，人生就能朝更好的方向前進。

振慈：《零規則》為 Netflix 創辦人所寫的書，主要公開 Netflix 的經營心法與企業文化，其中我覺得有一點與我們的企業文化很相似。那就是誠實透明的溝通與團隊的回饋與信任，要求每個人對彼此可以說出真話，給予真實且適當的回饋。因為真正的人才在意的是實質表現，而不是面子或表面上的尊嚴。提供回饋時，以協助為目的，而不是只是批評，意見要可以切實執行。收到回饋時，表達感謝（這樣別人才會繼續給真實回饋）、意見的採納或捨棄，最終還是取決於當事人自己決定要如何運用聽到的建議。

書裡提到，主管更要自己以身作則展現出鼓勵別人給他建議且認真改進的行為，當主管越常示範這樣的方法時，部屬也會更習慣去給別人回饋。讓一切變得公開透明，不管是重要的資訊，或者是犯下的錯誤。因為資訊充分，所有人才能做出對的判斷。甚至是經營數據，全員讀財報，大家都是共同承擔的一份子。不怕談論錯誤，才可以從錯誤裡學到教訓。所以在 Netflix 犯了錯並不會丟飯碗，但是嘗試隱瞞則可能真的會丟飯碗。誠信正直，坦承的面對錯誤，積極的糾正預防，勇敢的判斷分析和下決策，以公司和客戶最大利益為考量，培養創業家精神。$wr$, $wr$$wr$,
