・印刷廠 survey$wr$, $wr$策略分析工具：安索夫矩陣

不同產品在不同市場的發展策略

探討業務的開展策略，安索夫矩陣是非常能夠幫助思考的一種工具。此模型可以幫助我們解析企業過去的策略，也能反過來從現在的角度規劃未來經營策略。

安索夫矩陣（Ansoff Matrix）將「市場」和「產品」，分別切成「既有」和「新」兩部分，並組合成一個 2x2 矩陣：

1. 既有產品 x 既有市場：市場滲透（Market Penetration）

市場滲透，即思考既有產品如何提升在既有市場的市佔率。

Ex: 面向既有的客戶開發更多的訂單，介紹客戶還沒有購買的其他產品。

2. 新產品 x 既有市場：開發新產品（Product Development）

向既有客戶提供新產品。可以思考產品延伸的周圍產品、依據顧客反應改善升級後的產品。

Ex: 向車架客戶推薦香氛與醫護類產品；
Ex: 瞭解客戶的所有需求，找出我們可以但尚未開發的全新類型產品。

3. 既有產品 x 新市場：開發新市場（Market Development）

將公司現有產品，賣到尚未被開發市場，可以是不同地區的市場，也可以是不同客群的市場。可以：透過不同銷售管道賣給不同人（線下實體店面與線上購物）、思考同一產品如何賣給其他客群、拓展海外市場等等。這是業務的天職。

Ex: 將產品外銷到沒有銷售過的國家（如中東、印度。開發中國家也有中高端的需求）;
Ex: 將車架產品賣給租車公司（Herz, Dollars etc.）。

4. 新產品 x 新市場：多角化經營（Diversification）

讓企業踏出原本經營的圈子，發展全新的產品供應給全新的客戶。

Ex: 如引進我們的策略夥伴有沖牙機產品，開發海內外醫護通路。$wr$,
       $wr$振慈：臺大開放式課程

促進教學資源共享，落實建構終身學習環境理念，提供自學者更寬廣的學習內容，開放式課程（OCW）已蔚為世界風潮。其教材內容除提供社會人士免費上網自我學習外，並提供予國內外學生、教師及相關研究人員作為學習輔助、課程教學及研究題材之參考，以提昇學習效果及研究品質。

網站上有許多不同內容的課程可以學習，不僅有影片檔還有簡報檔，完全免費，目前聽了幾堂課程，覺得還不錯。

網址：http://ocw.aca.ntu.edu.tw/ntu-ocw/ocw/coupage/1$wr$, $wr$振慈：看了一篇經理人文章在介紹天才圍棋職業棋士黑嘉嘉，被譽為台灣圍棋段位最高女棋士，大家以為她一路很順遂，但實際上卻為了自己堅持熱愛的事情吃了不少苦，其中提到了他們全家搬遷到美國，當地完全沒有職業棋士、沒有人教課、沒有圍棋可下的環境，她每天放學後就上網對奕，周末早上 4、5 點，為了能和亞洲的好手連線，家人都還在睡，自己設鬧鐘起床，因為「太晚起，高手就下線了。」就這樣持續了一年半。「沒有環境的時候，你只能創造環境。」，很多時候我們抱怨大環境、抱怨客戶、抱怨各種因素，但卻沒有仔細想想我們還能做什麼，為了自己的目標和所熱愛的事物，我們是不是還能再努力一下，而不是一味的自怨自艾。「人生如棋，落子無悔。」棋子一下就再也不可以拿起來，人生也是一樣，有些事不可能再回頭，既然做了決定，就努力朝這個目標前進。

可欣：費曼學習法

「如果你不能向其他人簡單解釋一件事，你就是還沒有真正弄懂它」這是費曼學習法的核心信念。有時在學習新的領域知識時，無法清晰理出頭緒時就可以運用，試著整理出重點講給同事或家人聽，通常要讓不相干的人要聽得懂時，自己就會簡化內容，用最通俗淺顯易懂方式說明，本來鑽牛角尖的地方就會無師自通，而對方的反饋也常有自己絞盡腦汁也意想不到的問題癥結點；學習讓自己透過教學的方式進行學習，在不斷的分享過程中也可以鍛鍊精進自己的溝通能力及表達技巧。

淑倩：

快樂與不快樂往往只在一念之間。想著某個人如何得罪自己，往往怒火中燒，突然想起對方曾拉自己一把，頓時有如清泉灌頂，通體舒暢。

懂得用好的角度去看事情，真的很重要，那往往就會決定了一件事的好與壞，凡事換個角度來看，就能常常擁有好心情。站在別人的立場看一看，或在對方的角度想一想，很多事情就不一樣了。一個轉折，方位就不同，角度就不一樣。碰到一些懊惱的問題，當下覺得十分沮喪，往往一念間，一個小小轉折，立刻豁然開朗。原來，快樂與痛苦，其實只在一念之間而已。

老想負面的事情、思緒，精神狀態是痛苦的；盡量正面思考、樂觀祥和，心情是知足快樂的。這個一念之間決定在於人的「樂觀質量」。

雲丞：

本周的周會分享提到海底撈的多一小步服務，其實多想、多做一小步，就是創新，而且人人都可以做。

而創新通常都是從「不方便」「不滿意」「不舒服」中找到機會，站在顧客的立場，了解「痛點」在哪裡，進而找出解決之道。

最後將這些思維與步驟轉化為 SOP，再將 SOP 內化成為工作習慣的一部分，如果某些 SOP 已經內化在日常作業中，成為標準的優質服務時，這就是管理的最高境界。

彥菩：這禮拜與 Jamie 主任第一次演練業務簡報，第一次的表現自己覺得差強人意，因為在台上的感受跟在台下的感受是完全不一樣的，平時準備好的內容，上台會因為緊張或是突發狀況導致沒有辦法 100% 完全發揮，惟有在台下不斷的練習，準備超過 100 分的表現，在台上展現出來的才會有 100 分的演出。曾經看過一個建議如何克服上台緊張的方法，就是不斷的上台發表，透過挑戰自己害怕的事物，熟悉之後漸漸地就不會那麼害怕。

=> Woody: 我到現在也還是一樣，上台都會緊張，每次上台前也都是要不斷地重複練習，每個人都一樣。

慶鐘：

…

有句老話是對的：在通往頂峰的路上，我們最該擔心和規劃我們的未來，而不是等到為時已晚。

我們還能想到哪些其他著名的英雄產品公司？我們近期也在一家有類似情況的公司工作嗎？公司當前收入的 60% 至 70%，是否都被單一產品佔據？許多歷史悠久的家族小型企業，都可能會遭遇這類問題。他們通常是 30 年或 40 年前，由來自美國、日本或歐洲的一個 OEM 或 ODM 客戶發展了整個業務。他們的大部分收入，可能僅來自一兩個主要產品或一兩個主要製造客戶。

當整個行業突然發生變化時，當那個大客戶突然遭遇衰退，當客戶自己的產品不再有需求時，如果外部環境和消費者的需求發生巨大變化，以至於整個產品線或行業基本上消失了，會發生什麼事？

從歷史角度來看，旗艦產品當然能帶動公司成功，但在我們有時間時，必須盡快考慮如何自然有機地實現多元化，而不僅僅是依賴過去。

林森：成功者和失败者的思维方式是不同的。

比如一种人看到了一个问题会说「我不会拍摄，那么怎么做去做视频」。我没有工作经验，如何获得好的工作机会。甚至还有人抱怨，什么都需要有经验的，第一次怎么可能有经验呢，由此质疑别人不该要求那么多。

这就是一种思维方式的不同。我们不应该首先想的是，我有这些问题，那些问题，我没办法完成某某目标。

而是换一个思路：我该如何克服我的问题，从而达到目标。

如果没有经验，就想办法增加经验，如果不会什么达不到目标，就想办法学会什么以至于可以达到目标，这才是一个可以回答和可以解决的问题。你不会拍摄，可以简单拿手机，训练一下，学习一下，尝试一下，想办法增加自己的拍摄经验。

这些都是可以想解决的办法，如果我们陷入一个死循环，就是只会想我没有什么经验，什么东西不会，完成不了目标，那我们可就真的做不到了。

我们永远要记住，所有问题都是自己努力解决掉的，不是天生就跨过去的，没有捷径。$wr$, $wr$$wr$,
