       $wr$別讓手機變破口！病毒恐存活 3 天…蘋果、三星曝「正確消毒關鍵」：直接噴會陣亡

中央流行疫情指揮中心於昨（30）日公布，國內新增 15149 例新冠確定病例，其中 15033 例是本土個案，另確診個案中亦新增了 3 例死亡，指揮中心於近期開始實施的居隔「3＋4」新政策，不出所料的讓確診人數不斷攀升，進而掀起了快篩之亂。至於最容易讓病毒滋生的溫床，想必就是人手一支的手機了，由於觸碰的次數甚多，因此正確的進行消毒成為了最簡單的防疫方法，亦讓手機避免遭到損壞。

對於現代人來說，手機不離手早已成為了常態，無論是在哪個領域，手機都充分的扮演著重要的角色，完美的詮釋了什麼叫做「愛不釋手」；然而，觸碰手機的次數、隨手放置手機的習慣，恐怕會讓自己陷入染疫的風險，雖然手部有習慣性的進行消毒，但再次拿起手機的動作，也瞬間讓消毒的舉動無效了。根據相關的研究發現，肆虐全球的新冠病毒在物品上的存活天數，大概是 2 至 3 天，由此可見手機消毒是非常重要的，否則即進一步的提高染疫的可能性

至於手機的消毒方式，有醫師建議，只要準備一般 75% 的酒精做清潔即可，次數的話一天至少一次，必須多加留意的是，通話口、手機背部、手機殼縫隙是最容易暗藏病毒與細菌的地方，所以絕對不能忽略、隨意的擦拭了事。另外，亦有人會擔心若用酒精擦手機，是否會造成手機的損害，對此各大手機廠牌官方如蘋果、三星則建議，在消毒手機前有幾個步驟要先做，那就是關機、拔除電源、脫下手機殼。

接著，也就是 75% 酒精的部分，千萬不要直接的噴在手機上，最好的方式是利用軟布，輕輕的擦過表面、鏡頭等等，如果直接噴上去的話，液體會有流進任何開口得可能，進而影響了手機內部零件。此外，有人質疑，酒精是否會讓螢幕表面的鍍膜脫落，廠牌官方對此說明，事實上鍍膜的使用年限是最大的耗損原因，所以酒精並不會直接的釋出影響。

https://reurl.cc/6ZDAKV$wr$, $wr$振慈：現在的工作形態越來越多元，很多的自由工作者，或是公司裡制度等，讓員工相對可以有越多彈性的選擇，但當自由越來越多，相對的紀律就顯得相當重要。紀律在工作上可以反映在我們的思考和行動上，有紀律的思考，就不需要官僚制度；有紀律的行動，就不需要過度掌控。而紀律從何而來？紀律來自內心，是內在的力量。自律的來源是自己，當我們決心要有紀律、想改善人生，自律就會自然而生。當決心不要甘於現狀、要闖出一番事業，自律就會由心而生。如果覺得自己缺乏紀律，往往只是因為「還沒」下定決心、「還沒」創造紀律、「還沒」活出紀律。紀律從何而來？紀律就在自己身上。所以，現在就下定決心，立刻做出承諾，馬上活出紀律，就會超越自己，變得更強大、更敏捷且更健康。最重要的是，紀律會為我們帶來更大的自由。

→ True, 紀律會為我們帶來更大的自由。

淑倩：人與人的互動，在於信任基礎的建立，進而達到互重互愛，也唯有先愛自己，才能愛別人，並贏得別人的愛。

好好說話，就是一種尊重對方的表現。說出口應避免讓人倍覺反感而影響到人際關係，比如透過貶低別人來提高自我優越感的習慣，或者是對經驗不豐富進行倚老賣老的不友善「指導」。所以開口說話，要有彼此尊重的態度、說話的技巧等是和諧與平行的。

「好好說話」，代表著我說的態度是你可以接受的，代表我的眼神是在乎你的，代表我所說的是你願意聽的，也代表我所表達的文字訊息，是讓人覺得舒服的。說話是一種互動的行為，既然是互動，就需要彼此尊重，而不是單向式權威無禮的陳述。簡單來說，這就是道德層次上的「口德」。

艷梅：《世说新语》有言：「小胜靠智，大胜靠德。」一个人是否聪明，决定了他能走得有多快；而有没有德行，则决定了他能够走多远。厚道做人，短期看似吃亏，但从长远看，却是为自己积攒好运。少些精明算计，多些忠厚实诚，人生之路必定宽广平坦。

雲丞：做任何事之前「多想三步」

小故事分享：「老闆對著秘書問：訂書針在哪裡？」

選項一：跟老闆説：「老闆，對不起，我不知道在哪裡。」但相信即便真的不知道，也不會有人這麼誠實地回答。

選項二：跟老闆説：「老闆，訂書針在文具櫃從上數下來第二個抽屜的右邊。」記憶力超强，但意思是請老闆自己去拿。

選項三：找到訂書針後跟老闆説：「老闆，訂書針在此。」不過，老闆自己還得用老花眼把訂書針裝進訂書機。

選項四：找到裝滿訂書針的訂書機，而後跟老闆説：「老闆，請讓我來幫忙裝訂文件。」

做任何事情，都一定要多想三步，才能讓事情總是事半功倍，也讓事情最後如我們所布局地發展！

→ 這正是我們要推產「多一小步服務」的精髓.$wr$, $wr$$wr$,
