本週試寫一次 => 行動生活專欄：

不只 iPhone 要改用 USB-C！歐盟新法：6 大 3C 產品皆必須「統一接孔」

原文：https://3c.ltn.com.tw/news/48702

歐盟積極推動手機統一 USB-C 接孔，近日又再度邁向一步。

近期與歐盟市場、消費者保護委員會，以 43 票贊成、2 票反對的投票，通過最新的修正案，更明確將統一範圍擴大。新法案的目標是避免產生電子垃圾，且讓消費者在購買 3C 產品的時候，不用添購充電器、充電線，涵蓋的產品包含手機、平板、數位相機、耳機、遊戲掌機、攜帶式喇叭。要求製造商一定得使用 USB-C 接孔，只有智慧手錶、健康手環等運動周邊，因考量體積不必跟進。

除了有線充電規定 USB-C 以外，歐盟也著手瞄準「無線充電」，希望在 2026 年前提出政策，確保有統一的無線充電規範，讓各種設備彼此互相支援，至於要採用何種協議，目前尚無定論。

歐盟還希望在產品的外盒上，要有更清楚的標示，明確告知是否包含充電器，避免造成消費者混淆。

行動生活專家觀點：

標準與規範，是足以左右我們生活品質的一條線，從產業面來看，又有區分為國家標準、產業標準、業者標準（如 Apple 認證），而國家標準又分為強制性與推薦性標準。這次 USB-C 的推動，是從環境面的衝擊與消費者權益兩個層面去考量，優點當然是可以減少不必要的資源浪費，也可以降低消費者成本，但仍有一些問題需要探討：

A. 一般消費者換機潮大約是 3 年或以上，在較為支持環保理念的歐洲或許更長，加上近年來手機創新幅度甚低，新購手機若沒有配置充電器，恐不是大家都有充電設備，但此同時也造就了配件廠商的商機。

B. USB-C, PD 等規範仍在迭代成長中，舊的充電器未必能發揮新手機的效能。

C. 若是強制性規範，將會影響市場供需機制，進一步恐會抑制創新。

D. USB IF 與 WPC 等聯盟背後的組成也都是目前檯面上的各大業者，相關的授權與認證機制也都牽涉一定的成本與利益，對於產業中的後進者或競爭者也會形成進入門檻。

E. 如以充電為主議題，蘋果大可以宣稱充電採用 Qi, 但仍然能保留 Lighting，發展自己的生態系，不受 USB-C 所規範。

