OK 超商「店面變倉庫」營運績效竟大勝統一超、全家，當兩大對手開上萬店它關店、讓貨架給網購包裏

今年 3 月──OK 與蝦皮店到店攜手展開「雙向寄件服務」。顧名思義，消費者從此可在 OK 和蝦皮店到店合計 1 千多家門市之間，自由選擇要寄、取件的地點，不再受限於單一通路。蝦皮為何獨獨與 OK 展開雙向寄件？蝦皮購物資深執行總監梁日威透露，最關鍵的是，「我們對於將『用戶體驗』放在首位的發展理念非常接近！」

去年，由於 3 級警戒長達數月，街上人潮大幅減少，絕大多數零售業者的生意都受到衝擊，例如超商雙雄統一超、全家，雙方均罕見衰退，各自交出了稅後淨利年減約 13.5％ 與 37％ 的成績。

然而，與此同時，一匹意想不到的黑馬殺出重圍──OK 便利商店（OKmart，以下簡稱 OK），去年營收持平，營運績效竟逆勢成長逾 20％！整整 5 年，OK 只全心投入一件事情：把自己的弱勢縮小，優勢全力放大。OK 總經理魏國志用賣車思維想 5 年策略，「3 層次評估法」開發市場，「以前一台新車要改型，從設計到量產至少 5 年起跳，所以你要判斷的是 5 年後的事情，」憑空想像的難度當然很高，因此他習慣把判斷基準拆成 3 塊：大環境（整體社會環境、經濟、科技演變）、中環境（競爭同業的情況）、小環境（自己公司的內部評估，包括財務、員工、合作廠商體質等）。3 者層層對照，就能找出看似崎嶇，但是最適合自己的路。$wr$, $wr$雲丞：溝通前先想想：你希望自己是「被行銷」的大多數人，還是「被傾聽」的少數人？

最近接到一個雜誌電話行銷來電，不像是一般電話行銷一樣，她先確認了我的身份，另外還多問了一句：「現在是否方便通電話？」聽她跟我介紹目前提供給訂戶的優惠方案。就算我跟她説我好像已經有用 App 訂閱，她也不會馬上說謝謝再聯絡，而是跟我說明 App 訂閱跟電話行銷方案的優惠差別，也詢問我是否方便寄送相關訊息到登記的 Email。

通話結束後整個內容感覺到自己是被傾聽而且對於通話與否是有主控權的人。不但沒有被迫聽著電話推銷，或是被迫要馬上決定購買、一直被緊迫盯人詢問的壓力。

其實，產品行銷或是個人行銷不也是如此嗎？銷售的發生就在雙方主客觀意願與需求的對焦，而對焦又有賴於對於雙方出發點與利益的溝通。即便知道不切實際，但很少人會願意承認自己只是一大群模糊面孔的行銷名單上的名字和號碼，而更希望自己是被傾聽的那個特別的少數人。無論是知道自己原先我不知道的事情，或是自己的需求是否有些不一樣的解決方案，這都取決於對話的兩端，是否都有溝通意願以及是否有接受訊息與承接情緒的能力。

或許在下一次，當我們有需要跟一個或一群素未謀面的人溝通之前，是否能先問問自己，你希望自己是被行銷的大多數人，還是被傾聽的少數人呢？

振慈：保羅·賈維斯《一人公司》這本書主要是寫給創業者，或者在經營個人品牌、小型工作室的自營者，說明如何建立一人公司的思維模式，並且關注客戶與建立系統化的業務，但我認為這樣的思維也可以運用在工作上，我們的工作其實也就像一人公司，我們也希望可以找到適合自己生活步調，同時又能滿足自己對工作的期待。書中提到熱情與勇氣，談到許多人踏上一人創業時汲汲營營地尋找「熱情」跟「勇氣」，但這件事情不會一夕之間發生，而且「沒有捷徑」，不必浪費時間去找出你對什麼事充滿熱情，也不必期望哪一天突然找到內心的勇氣，只管全心投入你想做、正在做的事情。你專心在解決問題或者做出改變時，熱情可能也會隨之而來，因為你確實「投入」在你正在做的工作當中，而不是「想像」著你可能對某件事充滿熱情。專注於你能為世界提供什麼，而不是世界能給你什麼，就像我們應該先想著我們可以為客戶提供什麼，可以如何展現我們的價值，而不是先關注可以在這個客戶上賺多少錢，我們應該要採取工匠思維，專注於自己能提供的價值，工匠思維可以讓你專注於你能為世界提供什麼，而熱情思維則是專注於世界能給你什麼。

芳杏：業務的 12 項基本職能

1. 感染力與影響力：具有親和力，並能注意到客戶注重的事項，讓客戶有信賴感，進而產生間接的影響力：客戶願意影響其他客戶！

2. 成就導向：由於業務的工作時間較自由與彈性，需有效率與紀律的運用時間，並設定具挑戰性且可達成的目標以鞭策自己。

3. 積極主動：善於把握任何對業務行為有益的己方優勢與外部機會，對自身劣勢與外在威脅也能迅速有效反應，並堅持到底，不輕易放棄。

4. 了解人性：洞察他人的態度與意圖，瞭解非言語的行為，注意潛在有利的機會，最終能正確預測他人的反應，以超前部署因應方法。

5. 顧客服務導向：發現並滿足顧客潛在的需求為首要目標，付出額外的努力來達到此目標，保持與顧客的接觸並處理其抱怨，最終成為顧客信賴的顧問。

6. 自信心：對自己的能力有信心，但又不會自我感覺良好。樂觀面對挑戰，凡事找方法而不是找理由。

7. 建立人際關係：業務不只跟客戶因為工作上的利害關係而接觸，能維持工作上的友好關係，最佳狀況是進一步變成關係正向的朋友關係，組成可雙向交流的人脈網路。

8. 分析思考力：做事不憑直覺，而能以邏輯思考能力，對所有可能發生的情況已做好沙盤推演，才步步為營的行動。也就是孫子兵法講的「勝兵先勝而後求戰、敗兵先戰而後求勝」（先有了勝算才去打仗；並非仗先打了，才去想戰勝的方法。）

9. 歸納思考力：能夠把複雜的問題抽絲剝繭，拆解成個別部分，再應用知識或經驗法則，歸納與整理，使之綱領化、條理化，找出解決方法。

10. 資訊搜索能力：不只利用實體的人際關係獲得資訊、情報，也擅長利用 IT 科技收集資訊。首先能利用各種網路訂閱方式（如 google 快訊）建立自動化資訊收集管道。其次則能善用數位社群蒐羅更廣泛的資訊與觀點。再者熟悉搜尋引擎規則，能快速透過網路找到所需資料。如果擅長的語言越多，或善於利用網路翻譯，則能獲得更多加倍效果。

11. 組織架構洞察力：客戶往往會以單一窗口人員，與業務接洽、聯繫，但窗口背後的客戶公司或組織的結構與功能，也必須想辦法研究、了解，並認知與分辨在整個組織中，對相關事務的關鍵決策人物。

12. 技術性專業知識：業務人員具備產品或服務的相關專業知識，是基本的門檻性職能，但更重要的是，對於整個產業、甚至相關產業都應有所了解，並能「與時俱進」的更新或修正相關知識。$wr$, $wr$$wr$,
