除了將向參與亞馬遜物流計畫的第三方賣家提供使用，預期亞馬遜未來也會持續將此項服務擴展至更多賣家使用，吸引更多非亞馬遜服務使用賣家，依然可以透過亞馬遜物流服務提高商品銷售效率。而為了提高商品遞送效率，亞馬遜目前除了持續擴展自有物流系統，更與更多物流業者合作，以利讓商品能在更短時間內交到買家手上。

