想想，每個人都是一個多面體，有困惑，有焦慮，有優點，也有缺點。如果只抓住別人的缺點，只會接收到負面情緒，對別人不好，對自己更加不好，所以，學會欣賞別人尤其重要。其實，欣賞別人是一種換位思考的思維，是一種個人修養；也是一個從裡到外，由己及人的自我提升的過程，欣賞別人多一點，矛盾和誤解就會少一點，人和人的距離才會更近一點。

總盯著別人缺點，其實就是變相地懲罰自己；好人緣就是好口碑，好心情就是真幸福，善於發現別人的優點，其實就是善待自己。

可欣：這二年多來的疫情肆虐下，有人因為親身經歷而對疫情變成專家，但也有是因為對疫情有著警覺心及敏感度而成為專家，這也讓我思考在工作上，自己是不是也能有著隨時有著警覺心及對周遭環境變化的敏感度，而不只是鑽研自己專業上的知識而忘了環境變化帶來的衝擊，那很可能會讓自己成為無法解決問題的人，或甚至是變成製造問題的人，又或者是問題臨到時，連判斷解決問題方向的能力都沒有。若自己的成長不夠快速，那成長只能使自己留在原地，如果想前進，就必須用盡全力不間斷的努力向前奔跑，才能跟上這個變化萬千的世界站在浪頭上。

文千：跟外购厂商的交流中，很容易感受到厂商的「主动性」与「被动性」。无论新品询价，样品需求，产品规格资料等，厂商的回应积极性，时效性，细致度等都有一定的差异性。这样很容易自我反思，在做新客户开发或老客户客勤时，应该注意的部分。

工作或生活本身就是多角色的扮演，同理心的换位思考，配合度会更加顺畅。

振慈：先苦後甘這個道理大家都知道，但真正在面對苦和樂時，往往很多時候會被眼前的樂給所動搖。如果現在眼前有兩條路，都很想嘗試，但分不出兩者之間的高下，那麼就選擇短期比較辛苦的那條路，人生中大部分的收穫，都來自於短期要先吃點苦，才能獲得長期的複利效益。選擇運動，短期內會覺得身體又累又痠痛，但長期看來，會逐漸提升自己的體力，讓自己更健康; 選擇閱讀，短期內會讓大腦覺得辛苦有負擔，但長期看來，會拓展我們的知識，吸收到不同的新觀念。每天看似不經意的小決策，將引領我們邁向渴望的人生，或是導致走向不幸與失敗。不是大事累計起來發揮最大功效，而是成百上千、成千上萬，甚至數百萬件小事累計起來，區分出平凡與卓越的。

