紹軍：「憑經驗」做事，就像大海撈針！台積電前主管，一招系統性歸因

層別法應用：飲料破損率過高，怎麼解決？

回到產品破損高的問題。假設，產品破損的瓶子數量總共有 100 瓶，我們想了 4 個類別來做分類。此種分析稱為「個別層別」，也就是針對一群資料做單獨層別。

1. 產品別：哪一種產品的破損率較高？
2. 排班別：哪一個班別的破損率較高？是日班、中班，還是夜班？
3. 破損位置：瓶子破損都在哪些位置？
4. 破損缺陷：所謂破損，是裂掉？有很大的裂痕？還是一點點損傷？

我們針對這 4 個類別分別找出數字，結果發現，在破損的位置（分為瓶子上面、中間、下面），居然有 90% 的破損位置，都是在瓶蓋附近的位置，也就是瓶子上方。

接著，我們根據破損位置，再做層別分析。這稱為「連續層別」，也就是根據一群資料做層別、層別、再層別，由此畫出層別法的樹狀圖。我把這個樹狀圖稱作「層別樹」。層別樹可以幫助我們看出問題分類的全貌。

接著我們用排班別來做分析，後來也得到一個非常關鍵的線索，就是 90% 瓶子上面的位置，居然有高達 90％ 都是在夜班發生的，等於有 81％（90％×90％）的產品破損來自於此。從上面的例子換算，破損的 100 瓶中，有 81 瓶破損是在夜班發生，破損位置在瓶子的上方。

分析到這裡，教室同仁的眼睛為之一亮。接下來，只要針對夜班同仁去了解，去實際現場看一下，就能快速找出破損原因。問題經過拆解之後，關鍵問題浮現，原因出來了，對策也出來了，問題就可以快速解決。

層別法的優點，不僅在於能幫助我們找到解決問題的曙光，更重要的是，它一點都不難。只要我們在解決問題時，記得踩住煞車，先拿出層別法來分析。這就所謂的思維切換。

如果擔心自己會忘記，建議製作一個層別法的 PowerPoint 模板，往後每當需要解決問題，就可以拿出這份模板，套入各種情境。不論生活或是工作，好好運用層別法，會讓你解決問題更加容易。$wr$, $wr$$wr$,
