雲丞：勇氣不是與生俱來的東西

我們常以為, 有些人天生就很有勇氣。但是, 勇氣並不是與生俱來或既有的東西, 勇氣是獲得的、爭取到的東西。

第一次公開貼文很難。你試了, 沒有想像中的酸民留言。

第一次上台報告很難。你試, 沒有想像中的嘲笑挖苦。

第一次開口拒絕很難。你試了, 沒有想像中的死纏爛打。

當你邁出第一步, 發現想像中的艱難, 其實沒有那麼難。

勇氣並不是一個人在艱難開始之初就擁有的東西, 勇氣是一個人在經歷艱難、但發現它們並不是那麼艱難之後, 所獲得的東西。嘗試愈多, 勇氣愈多。勇氣是後天養成的。$wr$,
       $wr$我們即將進入沖牙機的市場，對此，我做一點背景說明：https://www.porclean.com.tw/

We, COMART 是 PORclean 的策略股東，未來我們也會是 PORClean 的開發與製造夥伴（目前為止有協助開發，但尚未正式開始生產）。銷售（包含台灣與海外）也有可能涉入，這對 COMART 是一個加分，因為我們已經有酒精消毒機、給皂機的產品，再加上沖牙機，未來不排除再陸續開發空氣清淨機、眼部按摩機等相關聯的個人醫護產品系列。www.hmplus.com.tw

PORClean 創辦人 Jacky 是我好友，也是台灣重要資訊通路欣亞數位的創辦人，是典型的連續創業家，產官學關係良好。https://www.sinya.com.tw/

PORClean 也已經登陸台灣創櫃板，其企圖心是要成為全球沖牙機（品牌與代工兼營）最專業的廠商。

為何選擇沖牙機？有兩個原因，第一，是因為在他輔導產學的過程中（他跟我都在新創平台中擔任新創的輔導業師），接觸到陶瓷材料科技，能夠淨化水質，聯想到，最需要淨化水的一個前提，就是會進入口中的應用，沖牙機是一個可能。另外，他觀察到，在包含台灣在內的許多已開發、開發中國家，對於牙齒清潔的衛教知識是落後的，刷牙、牙線都是每次用餐後必要的動作。

至於沖牙機，是可以深入牙齦，有效的降低齲齒跟牙周病，並且對於幾個族群如植牙者、牙套矯正者更是必備品，但已知數據上家戶使用率並不高，並且，此類跟口腔接觸的清潔用品，每人都能有一台是更加理想，不宜與人共用，沖牙機市場因此存在著巨大的成長空間。另外，在市場發展的初創期與成長期，先行者品牌通常具備教育市場的責任，通常也就會是消費者的第一選擇，並且能夠累積高度的知名度與指名度。

寶可齡在這個前提下開始嘗試進入沖牙機的市場，各位目前在網站上看到的產品，多是跟大陸廠商合作貼牌的產品，當然有一些設計變更（需要裝上濾心），但是這個濾心的作用並不是過濾，是浸入水中透過陶瓷的材質作用達到淨化水質的目的，該機器若不安裝這個濾芯，也不影響功能的。重量上，這個濾芯並不重，僅約 20g。

經過兩年多的實際市場測試與操作，PORClean 已掌握了部分通路與市場經驗，以及許多過程資產，包含行銷資料、與牙醫領域行業內專家的代言與佈局，因此決定開啟全新自我開發產品線的設計與製造，從旅行到家用，都會陸續完成，開始先在台灣設計製造，之後可能會在 COMART 的東莞及越南廠生產製造。我們也可以同步考慮推廣中國與越南的市場。

整理至此，寶可齡 PORClean 的競爭優勢至少有以下五點:

1. 專業化的形象佈局（進行中）
2. 完整的產品系列（我已看到四款的設計進行中）
3. 差異化的產品特色（陶瓷淨化技術）
4. 台灣設計與全球生產、行銷的能量（我們是夥伴之一）
5. 品牌、代工與貼牌的彈性服務$wr$, $wr$惠卿：今周刊看到分享:

對工作保持熱情的祕訣：找到你喜歡的事、找到你的熱情。但最難的是，該如何讓自己持續保持在這些狀態呢？可以試著重新看待與定義「進步」這件事，每天的進步是來自於一些微小「差異」累積而成的感受。可能是幫忙不同人（包含內部伙伴、外部客戶）達到不同目標；介紹一個新的人脈；訓練自己不一樣的思考角度，能針對同一件事分享獨特觀點；刺激團隊的想法，甚至只是閱讀到一篇好文章。嘗試把進步拆解成每一天都能滿足的任務與成就，而並非為了要進步，就訂定一個很遠大的目標，否則為了到達終點，一路上可能已耗費心力。

→ 是的，反過來說，應該先制定一個遠大的目標，再拆解成細緻的小步驟，每次完成一小步，是為「登月計劃」的精神

淑倩：正確的價值觀是每個人在成長過程中不可或少的重要環節和基本要求。只有正確的價值觀，才能在學習、生活、工作中付出貢獻和利益，也就是不要時時刻刻只想到自己的個人利益，而是要更多的考慮團體的利益。當個人利益與團體利益發生衝突時，就必需以團體利益為重。

人在做決定的時候，都會依靠內心的一套價值體系，選擇一個相對而言更值得的去做。在這個價值體系裡面，應努力提升自己的知識與修養，用自己所知的為團體做出貢獻。用正確的人生價值觀指導自己的人生，要求自己在處理個人與他人的關係時，應當遵循「我為人人，人人為我」的原則。只要在自己的工作生活中，積極認真結合誠信、正直、辨是非、守法、分工合作、服務熱情，才能匯出一股向上提升的力量。

→ 很欣賞 Sandy 的分享，常有佳作，蘊藏很多好的人生智慧。謝謝。

振慈：「自律」是一個被高估的詞，我們誤以為一個人必須保持自律，才能達成最終目標。我們誤把自制力和成功畫上等號。「自然」是把你自願去做的事情，變成一種不需要自制力就能輕易執行的日常習慣，你的身心不會抗拒自然的好習慣。「自願」是當你發現一件事情對你的有好處、充滿樂趣，然後發自內心願意去做，儘管偶爾困難，但仍會樂此不疲。上面三項反著順序再看一次，那些我們以為他們很自律的強者們，只是一直在做發自內心喜歡的事情，因為他們理解那件事情對自己的好處，所以自願去做、自然去做、自律去做。自願才是內在的驅動力，自律只是外在的表面結果，不要浪費心力強迫自己自律，我們該尋找的是你發自內心想做的事。

→ 我認為，自願之前還有一關，叫做「自覺」，自己有所認識而覺悟，進而自願採取行動。

艷梅：今天是 5 月 20 日，是近年互联网世界悄然兴起的一个由数以万计的网民自发组织的网络节日—520 网络情人节。生活，除了有爱，工作，还要安全。我们来个安全人的 520：

5 是指「五到位」：安全责任到位、安全投入到位、安全培训到位、安全管理到位、应急救援到位；
2 是指「两个主体」：政府是安全生产的监管主体、企业（即生产经营单位）是安全生产的责任主体；
0 是指「零容忍」：安全事故零容忍。

安全了，每天都是 520！

→ 0 是指「零容忍」：安全事故零容忍。

怡芳：每個人都是業務, 在面對內部 & 外部客戶時, 我們應該保有第一天工作的熱情 & 態度, 目標 & 心態決定了我們可以走多遠, 幫助提升自我。不論投入什麼工作，第一天一定都有個夢想與熱情支持著你，還記得那個屬於你的「Day 1」嗎？當時間久了，不自覺地陷入了「Day 2」，開始持久而緩慢的衰退，將是多麼可怕的一件事。不論工作多久，莫忘初心，存著看不見終點的「Day 1」活力精神，時時避開「Day 2」的停滯心態！

→ So true, 業務背後的精神就是服務的熱情，那是我們期待與肯定的態度。業務歷練是晉升主管職的重要過程。$wr$, $wr$$wr$,
       'C00001', '劉恕偉', timestamptz $wr$2022-05-21 09:00:00+08$wr$, now()
where not exists (select 1 from public.woody_reports where report_date = $wr$2022-05-21$wr$);

