select $wr$b00000086m9rs8g$wr$, $wr$2022-05-29$wr$, $wr$・越南供應商與宿舍事務處理$wr$, $wr$・產學合作計畫擬定$wr$, $wr$最近業務與產品單位在進行通路研究分析，這是我認為我們組織的特色與優勢，要了解各層次供應鏈與經銷通路的需求，才能提供最好的產品與服務。代工業務透過瞭解通路可以更了解品牌商的需求，通路與品牌業務透過瞭解供應鏈能夠放大產品競爭力，跨層次的交叉探索更是優質服務與創新創意的來源。

彥菩：代理商就像是媒人，要了解品牌和通路各自的需求，協助雙方合作。而要扮演好媒人並不容易，必須幫客戶和通路再多想一步，提供更多附加價值。不只幫助品牌，甚至還要站在通路立場，思考怎麼賣、怎麼增加業績。例如，建議通路將電池和小熊軟糖看似不相干的兩項產品，一起掛在玩具區賣。因為玩具需要電池，逛玩具的小朋友也會想吃軟糖。「否則只是把產品推給通路採購，而沒有協助解決問題、創造額外價值，關係就不會長久」，純做買賣的代理商已經失去競爭力。必須更像是貼身顧問，協助品牌找到連他自己都不知道的成長動能。$wr$,
       $wr$中國手機品牌在越南表現非常強勢，有近 50% 的市占率。

https://reurl.cc/Yv3bmo$wr$, $wr$雲丞：有益的焦慮

遭遇困難的時候，我該怎麼去克服? 如果這項能我還不會，我該怎麼學習? 這次失敗很痛，但我該如何捲土重來？

為什麼我要搞得自己這麼焦慮？

遭遇困難的時候，我改挑簡單的做。如果這項技能我還不會，讓會的人去做。這次失敗很痛。那我下一次不再嘗試。我能過得既舒適、又平心靜氣。

如果你不甘凡，想要有一番成就，你要慶幸自己感到焦慮。

有益的焦慮是成長的助力因為你對未來還有想法、有掙扎、有渴望。而那些不再感到焦慮的人，只能停留在原地。

→ 這就是跳出舒適圈的意義。離開舒適圈，通常會有正向改變。

慶鐘：現代父母在家中對孩子的教育，常是寬容、寵愛，任其自由發展，遇到問題時也會盡力協助，甚至主動幫忙解決。在職場上，主管希望年輕同仁能有主動解決問題的能力、足夠的抗壓性，以及對工作負責的態度。實際上，家中的孩子與職場上的年輕同仁是同一群人。在家中缺乏練習、解決問題的機會，到職場上也不會一夕長出相應能力。因此，父母、主管的角色要先調整，才能對年輕人做出正向影響。

→ 家教是最重要的社會教育。

美玲：這個世界上，有一群人成功的祕訣，就是把工作當成玩。他們正在用各種語言悄悄告訴你，只是你未必聽見。牛頓因為工作太專心，把手錶當成雞蛋放在鍋裡煮，不是想說自己多麼敬業，只是想說自己玩上了癮。有人會質疑因為成功人士優秀，所以才能把工作當成玩，但應該換個角度想，就因他們對工作有熱情，主動賦予工作崇高意義和無限的樂趣，才能擁有高成就。找到工作的樂趣，就有源源不斷的熱情、創造力，也許這就是人與人之間的區別：都把工作看成是一場遊戲，但有的人只是玩玩而已，有的人卻在努力打怪升級，一心要成為最強王者。把工作當成創造而不是消耗，才能在事業上有好的成就。

振慈：降低期待值並不是悲觀或是不積極，是因為人的心理是很奇怪的，採取一個行動以後，即使有一些效果，但是成功比例不高，就很容易全盤放棄，我們的大腦會自動放大未成功和失敗的，這時候，降低期望值，會幫助我們提升動力。例如在開發客戶時，有 1000 家名單，如果我們只檢視了前 100 家，這些資料都沒有用，你可能會放棄，但這是錯的！只要堅持下去，往往會發現，好機會藏在後段的資料當中，說不定成交一兩家，就夠本了。所以當我們採取行動時，經常放大 80％ 至 90％ 的失敗，認為做這些事沒有用，早早放棄；卻忘了 10％ 至 20％ 會成功，以致喪失了機會。要克服這種失敗主義的心態，一個好方法就是降低期望值，如果有少許成功案例你就滿意，就會有動力繼續做下去，直到成功。

→ 這就是業務的態度

涵暭：客戶來信詢問卡車專用的沙包座，依照客戶的使用需求，本廠的可能沒辦法滿足，思考可能要尋求外購資源，過程中要考慮客戶實際的產品使用情境、客戶預計下單的數量、客戶的預期價格等，如此才能有明確一點的方向。然而因還是希望能從廠內來做（當然也不能設限），所以從外廠得知了標準品可以如何運用較少的成本來替客戶客製化產品後，也試圖跟廠內溝通詢問。多問、多了解，目標都是希望能提供客戶解決方案，要一直有朝這個方向前進的感覺及動力。

→ 同意，幫客戶解決問題是為首要，資源不分本廠或外廠。

可欣：現在的疫情尚未結束，國外又掀起另一波猴痘疫情，這些都是我們無法預測到的危機，其實在工作上也常是如此，像本週配合良好的房客突然解約，這些都時無法預測的變化，但我相信唯一能控制的就是自己的努力與態度。有位傳道家曾說『所謂人生，10% 是發生了什麼事，90% 是你用什麼態度面對』；面對危機時，你若能透過積極的態度從中抓住機會，將阻力化為自己成長的動力，那你才能做自己人生的主人。

佩华：「有机会一定要试一试。其实试错的成本并不高，而错过的成本非常高。」

试错，是互联网思维的精髓之一。

试错，意味着开放性、妥协性、可能性，还有不断复盘之后获得的经验与教训，最终收获了对未来事件概率的预判能力。

湄涵：呼應之前同仁分享，先自願再自律的概念，《原子習慣》提到的身分認同去改變心態：「焦點永遠都要放在成為某一種人，而非得到某一種成果」。目標不要放在每個月早起 30 次這種結果上，要打從心底相信自己會成為「掌握起床就掌握人生」的人。早起是自律的結果，要先找到內在的動力，從身份認同的角度去思考，自然而然會知道怎麼做，然後養成自律的習慣。

瑩如：真正的成就，不在於做了一件偉大的事，而是累積每天的平凡。擁有什麼習慣，幾乎就決定我們是什麼樣的人。有「每天跑步 5 公里」的習慣，我們會成為身體健康的人；有「提早 10 分鐘到」的習慣，別人會覺得我們是負責任的人。擁有的好習慣愈多，我們工作愈高效、生活愈快樂，形象更積極正面，有機會時，別人也容易先想到我們，使我們更接近成功。持續把一個習慣做好、做到位，用每天一點小贏，累積成長長久久的成功。$wr$, $wr$$wr$,
