每家公司都有三多。

文章中提到的「豬隊友」，其實不多，我認為有以下可能：

・自己太過於自我，是馬謖型的人，自視高，看不起別人
・自己缺乏影響力，見 Lydia 分享的：「權力之外的力量」
・太過強調分工分權的組織制度使然，組織僵化
・欠缺團隊合作文化，領導者有責任
・若真是「豬隊友」，應與教育，若無法改善，再輔導轉任$wr$,
       $wr$https://www.businessweekly.com.tw/archive/Article?StrId=7005997

總體經濟環境堪慮，成本不斷高漲，庫存積壓，消費緊縮，wal-mart 還是堅持低價，甚至再更低。

文章說：「擇便宜而固執」不容易，短期甚至可能侵蝕利潤；但長遠來看，留得住顧客，並化累贅庫存為搶得新客的武器，或許能讓它在需求與成本黃金交叉的年代中穩住腳步，成為潮水退去後真正的零售霸主。

我們身為供應鏈的一環，此事與我們有關。$wr$, $wr$怡琪：本週部門教育訓練分享 QBQ：解決問題的原點在於發現問題，發現問題是本事，解決問題是能力。我們必須要拋開我們過去的知識與經驗，逃脫出這些限制，才能真正發現問題。長期做同一份工作的心態也是如此，過往發生的事，並不一定適用於現在的情況，針對現在的情況重新去思考，才能夠真正解決問題。

慶鐘、芳杏：為客人解決麻煩，我們的服務就有價值，創業要找到客戶的「痛點」，針對「痛點」提供對應的產品與服務，為客戶解決問題，就能創造價值。懂得站在客戶角度看問題，捕捉並滿足對方的需求，都是工作者的重要能力。在職場上，每個人都在想辦法優化自己的投入與產出，為個人建立好口碑，為公司打造更好的產品與服務。懂得觀察內部與外部客戶的「痛點」，有助於我們在組織中改善相關流程，提供更好的服務，放大你的專業價值。學會把客戶、主管、同事的「痛點」放在心上，能為自己塑造良好的職涯道路。

→ 是為：顧客價值主張

可欣：在工作中常常會遇到複雜的事，想著要如何化繁為簡的將事情順利處理完成，但發現有時只要『換個角度』看待問題，就能將那些原本雜亂如麻的難題理出一個頭緒並找到問題的癥結。馬雲曾說：「複雜的事情簡單做，你就是專家；簡單的事情重複做，你就是行家；重複的事情用心做，你就是贏家。」能將複雜的事情簡單化，其實也是工作能力的養成。

惠卿：這周代工安排職訓課程「問題分析與解決技巧」，同仁們在後續討論中延伸出來另一個話題：發現問題比解決問題還要難。解決問題屬於被動，發現問題屬於主動。但要如何訓練自己能夠意識到一個問題存在，進而去主動發現問題、提出問題，不要等主管、客戶來告訴你問題在哪，變成是一個很需要去培養的的能力。

佳玲：真正的紀律無法外求。因為外在紀律的力量不強、不會持久，也無法自給自足。自律的來源是自己，當你決心要有紀律、想改善人生，自律就會誕生。如果你覺得自己缺乏紀律，往往只是因為「還沒」下定決心、「還沒」創造紀律、「還沒」活出紀律。

紀律就是要面對恐懼、克服恐懼，紀律代表走困難的路、辛苦爬坡，為了自己，也為了別人，堅持做對的事。輕鬆的道路往往會誘惑著我們，一時意志薄弱，一時失去自制，抓住眼前的欲望和短期的滿足，紀律不會容許此事發生。紀律需要力量、堅毅和意志，不會接受軟弱，也不會容忍意志潰散。我們需要的其實是活出紀律，是「自律」。$wr$, $wr$$wr$,
       'C00001', '劉恕偉', timestamptz $wr$2022-06-05 09:00:00+08$wr$, now()
where not exists (select 1 from public.woody_reports where report_date = $wr$2022-06-05$wr$);

