select $wr$b0000002v9otg7k$wr$, $wr$2022-06-12$wr$, $wr$・股東會報告事項準備
・金點新秀設計獎遴選$wr$, $wr$・高雄科技大學產學合作
・TA 新創平台評估$wr$, $wr$能夠存活下來的物種，從來都不是最強大與最有資源的，而是能夠適應環境的！

https://www.businessweekly.com.tw/magazine/Article_mag_page.aspx?id=69841

公司資源不足？真相是，如果你去訪談，會發現每一間公司的資源都不足。資源從來都不是決定成敗的關鍵，否則 Nokia 不會倒閉。本週讀的書，《讓少變成巧》（https://reurl.cc/zZXGye），是一本每位（現在或未來的）管理者應讀的書。我們很多同事去參訪過我們的最強的同業，對方的資源與能力絕對少於我們，但成效卻優於。在某個時間點，我們能夠成長的原因是因為我們願意嘗試一切方法與可能，把資源做最有效的運用，而非追逐資源。「當你手裡只有錘子，所有東西都像是釘子。」，解釋的我們應要破除慣性的負面思維。破除慣性，當我們只有錘子時，就應該善用這把錘子，誰說修樹枝、鑽孔、測距離，一定需要鋸子、電鑽、尺？當我們只有錘子的時候，請讓我們用僅有的資源完成必要的工作。誰說只有業務能開發客戶？只有裝配人員能做生產？我們現在的困境，可能正是因為習慣擁有太多，而非資源不足。

可欣：有時進修 HR 相關課程時，會發現法律是保護那些「懂法律」的人，但其實也可以正面想成『資源』是留給『懂把握的人』，不論是在工作中或是生活中，很多的資訊（源）取得非常的方便，但重點在於你有沒有懂得去把握、去善用…$wr$,
       $wr$艷梅：罗永浩有句神预言：「卖手机不如卖手机壳的赚得多。」

不想竟是一语中的。随着中国智能手机市场日趋饱和，手机厂商之间的竞争越来越激烈，淘汰赛进入倒计时。

据市场调研机构 Counterpoint Research 发布的统计数据显示，目前手机用户的平均换机周期已经超过 31 个月。

压力之下，各大品牌都在通过外观创新来提升新机上市密度，进而刺激消费者的购买欲望。然而事与愿违，就在前段时间，「年轻人为什么不愿意换手机了」的话题，还一度冲上热搜。

一方面，随着手机技术越成熟，性能衰减周期也变得越来越长，虽然手机使用频率很高，但就产品本身而言，并不具备快速消耗的特点；另一方面，手机迭代的性能改善并不大，不少甚至有鸡肋之嫌，而所谓的多个色卡，则根本不足以成为换机推动力。

与之相反的是，年轻人却更喜欢频繁更换手机壳。像盲盒、潮玩手办一样，手机壳正成为年轻人的新晋社交货币，甚至变得和穿搭配饰一样重要，彰显的是个性，提亮的是心情，绝不能拉垮。据天猫公开数据播报，光是每年购买 12 个以上手机壳的人就超过一千万。$wr$, $wr$黄氏合：「愤怒永远都是弱者的象征」——奥修

当事情达不到我们的预期，同时我们又感觉没有能力去改变它时，我们使用愤怒来隐藏我们的无能。愤怒让我们看起来好像很强大，但它是弱者的行为。

陈氏红：永远都不要停止学习

我们生活的世界在不断变化。几乎每天都有新产品、创新和新技术出现。你现在做得好不一定你永远会做得好，如果你想保持领先并成为专业人士，你需要不断了解正在发生的一切。向更有才华、更聪明的人学习书籍和现实生活，为了可以跟上世界的发展进度。读书很重要，正如商人吉姆恩（Jim Rohn）曾经说过的：「有些人读书很少，所以目光短浅」但是我觉得这句话也不完全对因为知识不仅来自书本里，更来自生活经历甚至来自你自己的错误，主要是你如何接受和累计。

振慈：我們都知道努力很重要，但方向比努力重要，選擇比努力重要，思維比努力重要，學習比努力重要，有很多東西都比大家認知中的「努力」重要百千倍。只是在整個過程中，努力也一定是如影隨形，不能缺少的。努力不是萬能的，必須不斷自我增值，優化工作流程，反覆運算思維方式，一次次撕裂自己，重新構建技能，而不是努力卻重複著機械的工作，維持僵化的思維方式而不加改進。不要做行動勤奮但思維懶惰的人，努力只能讓你過得下去，但無法保證你過得很好，無法保證你成功。成功需要在努力的過程中，不斷優化技能，不斷更新思維。

→ 怡芳說，沒有功勞，苦勞何用？意義相同。我們需要一點改變，透過思維、學習、選擇方向，不斷調整。

魏湘芸：我們的 Slogan 是「成為客戶信賴的夥伴」。當我把自己的定位從銷售者、製造商轉換成與客戶一體的商業夥伴，抱持著共好的心態把「客人的客人當做自己的客人」，把「客人的產品當作自己的產品」，把「客人的業績當成自己的業績」後，投入時間精力與客戶一同討論、思考、設計產品、解決問題、訂單 forecast、行銷設計... 等。初期覺得額外花了時間精力多做這些事有些累，但慢慢地覺得自己也是收獲不少，多學習到了很多市場面的資訊、消費者思維、客戶觀點... 等。心得學習，在商業合作的關係中，當我們能換位思考，為客戶創造利益、解決問題，才能彰顯我們的價值。但若能取得客戶信任，抱著共好心態，才能成為夥伴關係走得長久。

→ 完全認同，太好了

淑倩：善於發現別人優點的人，一般是能虛心接受意見的人。

與同事相處之間，本著互相學習，如果能集中精力來觀察別人的優點，然後再加以學習，將使自己如虎添翼。人是没有完美的，但透過不斷思考、感悟以及發掘與努力而修正不美好的自己。若發掘別人的優點然後思考自己，領悟到自己需要怎麼做，這學習將是對自己的一種提升！所以努力學習他人優點，才能讓自己變得更加優秀，使自己更進步。$wr$, $wr$$wr$,
