上面這個故事，讓我想到怡芳曾經做過的分享：「誰搬走了我的乳酪？」，故事都極其真實，是大多數組織經常會遇到狀況，過往的成功正是今天問題的根源。期待怡芳再幫大家做一次分享。因為我們今天的現狀正如故事中的兩隻老鼠。各位都是決策者，革新，必先革心。

秋妝說：每天早上，当一头非洲羚羊醒来时，它就知道它必须比最快的狮子快，否则它就会被吃掉。每天早上，当一头非洲狮子醒来时，它知道自己一定要比最慢的羚羊跑得更快，否则它会饿死。无论你是狮子还是羚羊，当太阳升起时，你已经开始奔跑了。

总结：奔跑吧！在这个竞争激烈的社会，如果企业停滞不前，老是沉浸在昔日的荣光中，最终的命运将是要么被吃掉，要么被饿死。$wr$,
       $wr$承前：

于嵐：市佔曾高達 95% 的 IE 瀏覽器，被使用者不斷嫌棄之下，最終還是退出歷史的舞台，世界隨時舊換新的在更新，但也是先有才會有之後衍生更好的服務，有些事物總要有人先做出來，後來的人再根據需求來改進讓功能更好更完善。$wr$, $wr$振慈：學習是終身的事情，很多人在大學畢業後進入工作崗位，工作多年都沒看過幾本書，透過一本書，我們能接觸到作者的想法和經驗，觀點和特質，一杯咖啡的錢，也許就能獲取別人一輩子鑽研和琢磨出來的好東西。三人行，必有我師，我們要學的不僅僅是跟工作有關的內容，更多的是為人處事的方式，解決問題的能力，談吐和氣質。除此之外，還要學習如何終身學習。如果不學習、不進步，就難以跟別人競爭，工作機會就會減少，就可能形成惡性循環。你花大把時間努力，或許方法遠不如別人，也缺乏專業化的引導，結果一天的產出還不如別人一小時多。市場經濟遵循優勝劣汰的自然選擇，你的價值決定了你的未來，如果你不學習，空長了年齡，以後一代一代的年輕人都會成為你的老闆、你的主管。

张燕婷：和谷歌、亚马逊、Facebook 并称为「美股四剑客」的 Netflix 公司，内部流传一本《奈飞文化准则》的手册，主要包含 8 大准则，其中第一条就是「只招成年人」。这里所谓的成年人，是和巨婴相对的概念，其标志不是年龄，而是思维方式。

A「职场巨婴」有以下特征：

1、脆弱玻璃心 2、消极抱怨，充满负能量 3、缺乏边界感 4、推卸责任，逃避问题

B 什么是企业需要的「成年人」

1、自驱力：是自己驱动自己，让自己「奔跑」起来的能力。
2、皮实：要耐挫抗打击，越挫越勇。（皮实程度：乒乓球型 > 枕头型 > 玻璃杯型）
3、靠谱：靠谱的人至少具备 2 种思维：闭环思维 & 底线思维。
4、有担当：这是一个职场人是不是成熟的重要分水岭。

黃氏菊：每天告诉自己要努力控制自己的情绪，不要抱怨，要小心自己的言行举止，这不是让你软弱没有个性，而是慢慢提升自己。在工作和生活中，事情并不总是像我们想要的那样顺利，当你抱怨时不仅不会帮助你解决问题，还会成为一种习惯，一种坏习惯，一种懒惰的思维，不想想解决办法，只能抱怨。$wr$, $wr$$wr$,
