主管用人大多喜歡傑出的人才，傑出人才能說善道、會做事當然是好事，可是這種人才如果自以為是，太過自負，終究可能犯下不可思議的大錯，這種人是歷史上讓孔明兵敗失街亭的馬謖。

馬謖型人才的特質包括：（一）聰明靈敏，學習快速；（二）因一學即會，故沒耐性虛心學習；（三）自以為是，大而化之，不在意遵守規範；（四）好大喜功，求勝心切。

主管永遠要小心馬謖型的人才：自以為是，好大喜功，求勝心切，不接受約束。

組織中絕對不乏馬謖型人才，這種人才很可能會受到重用，但是在當他獨當一面後，卻會在關鍵時刻，因為大意、疏忽，而犯下不可思議的「低級錯誤」，而使公司蒙受重大損失，公司要非常小心預防「馬謖型人才」的災難。$wr$,
