潔牙得力助手「沖牙機」出線！美國牙醫協會也認可

而近期非常火紅的「沖牙機」，更成為眾多網友的潔牙必備工具，直說：「牙齒刷的再乾淨，還是能沖出許多細小的髒垢！」但沖牙機真的這麼神嗎？李世偉醫師不諱言，沖牙機確實是幫助口腔清潔的實用工具之一。

沖牙機的原理，是利用強勁的「噴射＋氣泡水流」沖洗牙齒，能更深度清潔牙齦與牙齒交接處的牙菌斑，以及清除卡在牙縫間的食物殘渣，對於配戴矯正器者、戴牙套者，口腔較多死角、縫隙者更適合使用，此外有牙周病問題的人，還可藉由水流按摩牙齦、清潔。

…$wr$, $wr$彥菩：…

雖然都說銷售是有套路的，但真誠，才是最大的套路。「沒有什麼單子是一定要談下來的，凡事都有一定的底線和原則。」真誠，就是你的底線和原則。

→ 是的，銷售不一定是話術，但真誠肯定是一條道路，可以放心告訴客戶我們產品的缺點（與優點）。沒有道路可以通往真誠，選擇真誠就是光明的道路。

于嵐：這周碰到一位商城窗口，提出客戶的疑慮，當我跟商城窗口確認客戶真正的疑慮是什麼時，商城窗口卻沒有確認客戶的疑慮是什麼，是猜測應該是怎樣怎樣的，我最後請商城窗口提供客戶的資料，讓我直接聯繫客戶，並了解客戶的想法，並解決客戶的問題。在處理客服時，不要猜測客戶的想法，要就是直接確認客戶真正的需求是什麼，才能最好的解決客戶問題。

振慈：特斯拉公司有著與眾不同的員工規則，「反手冊」手冊（Tesla Anti-Handbook Handbook）充滿馬斯克的風格，「我們與眾不同，我們喜歡這樣。與眾不同讓我們可以做別人沒做的事；去做別人告訴我們是不可能的事。」員工手冊的開頭如此寫道。「反手冊」的 15 項重點，包括信任、溝通、職責、目標與反饋、安全、出勤、遲到、病假、無故缺勤、外部雇傭關係、蠢事、樂趣、訂出這些守則的用意、解決疑慮。其中我認為職責與我們的企業文化當責和團隊很相像，了解公司對你的期待，這是我們的責任。如果任何時候覺得不清楚，直接問，在這裡，「沒人跟我說過」這種藉口永遠說不過去。我們的的首要職責，也是每個人的首要職責就是讓這家公司成功，如果團隊裡的任何一個人看到能夠改善我們工作方式的機會，都要大聲說出來，就算它不屬於我們的工作職責領域，團隊裡的每一個人都望著相同目標，有著相同的信念才會讓整體、讓大家變得更好。

慶鐘：成長型思維的人面對學習時的態度是想不斷學習，面對挑戰，期望迎接挑戰，挑戰越大，學習和成長空間就越大，對於挫折戰鬥到底。對於對方的反饋，從負反饋中積極學習。面對批評，歡迎批評意見，並且快速改正。看見夥伴成功，內心因夥伴的成功而開心。相反的固定思維的人，面對學習，只想被認為聰明，面對挑戰，迴避挑戰，遇到挫折就想放棄。對於對方的反饋，因得到負面反饋而備受打擊。對於批評，不願理會批評意見。對於夥伴的成功，而備感威脅。

→ 認同，格局決定結局

淑倩：有些事，我們做多了會心不甘情不願的計較，認為自己做的比別人多。其實，在做的每件事的同時，做多了學到的都是自己的，也讓自己又多學到一點東西；做少了不用慶幸，因為那是讓自己少了一次學習的機會。

每一個專家，都是比別人多付出很多的努力，才會有今日的成就，成功的人永遠比失敗的人做得更多。所以，「多做多得，少做多失」，凡事盡力而為，能力做得到的就盡量去做，不要錙銖必較。因為從做中學到不少技巧和訣竅，比起斤斤計較或抱怨推諉的人成長更多。即使多做可能多錯，但可從失敗中記取經驗，也是一種成長。現在分分秒秒的付出，就是未來點點滴滴的收穫，眼光放遠，必有後福。

怡琪：最近開發客戶發現很多客人都還在銷售車架，但都不是我們的車架了。造型上也很多變，也滿有質感。想到過去因為我們高貴的報價讓很多客人都跑了，要再拉回來要花費更多的心力。現在在報價上都以客人的角度來思考，不再像過去一樣想要賺多少，而是要報多少才有競爭力。我們有競爭力，客人在市場上也會有競爭力，才能銷售更多我們的產品，滿足客人的需求，永遠是讓客人選擇我們的關鍵。

→ 完全同意。如若，直接代工客戶無法接受我們的「成本」，那麼當再往下開發，如品牌商無法攻克，那麼當開發「代理商」、「經銷商」等客戶，這正是我們最近探討各種營運模式的原因。歡迎大家 7/12 來聽 Maggie 的「貼牌」營運模式的分享，這是我們現階段很重要的業務思維。

惠卿：面對例行性工作，尤其有些繁複的例行工作，我們可能會誤會很簡單，也可能覺得它不重要又很煩人，這時候往往就會不自覺的想要「靠感覺」工作，而不是「靠方法」。一時大意的結果往往就是造成工作上的錯誤，後續要花更多精力來補救。解決辦法其實很簡單，就是建立真正具備每個小步驟的工作流程檢查清單，要求自己每次一定要跟著步驟清單執行，出現新問題或是有了新想法，就把更好的行動改到這份步驟清單，最後也是最重要的就是一定要按著步驟執行，不認真執行做再多也是徒勞無功。

→ Yes, PDCA, 不要跳流程$wr$, $wr$$wr$,
