故事中的公司是「數位時代」與「經理人」雜誌，前不久因故去拜訪陳素蘭發行人，印象最深的也是這兩個大螢幕，深深認同何先生所說，營運數字就像人體的健康報告，要分析了解數字背後的原因，找出最佳「營運模式」，以嘗試改變營運成果。要成為更好的自己，我們需要不斷的改變與成長。

這跟我年初開始要求各位主管的概念一致，轉貼我一月發出的指示，其中，為了掌握目標，再加上營收預算目標成為六條線。說明如下：

我們應透過六條線重點掌控經營重點（附範例圖說明）：

・目標，緊盯營收目標，也是今年 OKR 之 O
・營收，應穩定成長向上
・毛利，平穩即可
・費用，配合營收會數字會向上，若營收穩定，則應控制向下為佳
・淨利，平穩即可，微幅向上為佳
・庫存，穩定降低為佳

我們的經營策略應掌握以下四點：

a. OKR, 確認總體與部門目標，協同工作重點，以及進度掌握
b. X-Mind, 針對重點，擬定策略，確認主責者以及期限
c. 六條線趨勢，掌握方針，即時調整策略
d. 各單位之檢討應以周為單位，主管應主動協助各單位，排除第一線之困難$wr$,
       $wr$郁庭：100 個現代最偉大的設計！《財富》雜誌時隔 60 年再次評選

https://www.shoppingdesign.com.tw/post/view/5255

在 60 年前，好設計更多指的是一種純粹的產品美學，而現在，優秀設計的評價重點已經變成一個產品或服務能否更好地去實現特定目的、功能，以及能否為社會帶來持續的影響。$wr$, $wr$雲承：比起策略，執行比你想的還重要

皮克斯 Pixar 的 CEO 曾經分享，若是一個好的創意與平庸的執行，以及平庸的創意與好的執行相較之下，他會傾向選擇後者。因為再好的策略與創意，若是缺乏好的執行，一切只是一場空。聯強總裁杜書伍說：「再談策略之前，我們該知道的事執行才是重點。」

只靠空想、沒有實際去做，很多東西是掌握不住的。所以執行時要步步為營，摸著石頭過河，一面做，一面補充更細的計劃，把策略修正得更精準。

這就像是我們一直在提倡的 PDCA 循環一樣，並從中發掘問題，持續改善，才能有效提升整體工作執行效率與效能。

怡萱：面對例行性工作，特別是那些繁複但又不可避免的工作，我們往往都會認為自己閉著眼睛都可以完成，所以覺得它不重要，流程能省則省，但一時大意的結果就是造成工作上的錯誤，後續又必須要花更多精力來補救。既定流程固然瑣碎和煩人，但多花一分鐘的確認和檢查就是為了避免後面一連串的麻煩和錯誤。

=> 好習慣成就好命運

怡芳：這周看了《王者理查》這部電影, 電影細節就不介紹了, 讓我印象深刻的是我們做任何事情只要有了信念, 就要有計畫, 有了計畫以後就是要堅持的執行, 不可以因為任何眼前的小成功而改變, 過往的成功模式也不代表會永遠的成功, 就算一路順遂也不可以自滿, 要維持謙遜跟堅持執行計畫（紀律）才能達到最後的成功, 不管我們所擁有的資源有多少, 我們應該依照我們的計畫而去尋找規劃資源, 在機會來臨之前就是做足準備, 我們永遠都不知道機會何時會來, 唯有堅持執行計畫才有可能得到機會

