淑婷：遇到點困難，就停下腳步，把困難當成了護身符，很少主動想辦法解決。這是缺乏行動力的典型表現。主動尋找機會，才能做出更好的成果。

主動是一個與效率息息相關的因素，是一種可以讓人變得可靠、讓工作變得高效的好品質。在工作中如果你默默地做，靜靜地等，就會讓自己一直處於一種被動的位置。也會因為沒有抓住機會，只能原地踏步。

