       $wr$昕緯：蘋果近期新專利

蘋果開始擴展 MagSafe 磁吸固定設計，接下來或許也將應用在更多週邊產品及配件。從蘋果近期取得專利內容顯示，有可能藉由磁吸設計取代傳統鈕扣、拉鍊等衣物扣合方式，藉此有更平坦的扣合效果，同時更方便穿脫。

蘋果認為傳統鈕扣不僅讓衣服較難穿脫，甚至必須花費較多時間扣合，但卻無法保證有更好的固定效果，而拉鍊雖然比鈕扣設計更方便使用，但也可能因為拉鍊本身造成難以拉上，或是因為拉鍊造成設計突兀情況。

蘋果新設計專利，利用磁吸方式取代傳統衣物上的鈕扣、拉鍊$wr$, $wr$湄涵：上週觀看吳靜吉教授的專訪節目，主題是關於創造力，吳教授現年 83 歲，談吐幽默、觀點清晰，創造力不是發散的發想，他提到，創造力必須是有用的、有意義的，且必須具備執行力，創意透過執行而變成創新。創造力可大可小（創造力 4C），大至改變世界文明、小至民間創意都是有意義且值得鼓勵的，他認為幽默就是一種創意，在創意的用途上，他建議不要抱怨懷才不遇、資源不足，而是利用有限資源創意組合，無論是個人、生活上、企業、社會，把有限的資源最大利用，盤點擁有的優點，並且有計劃的去執行。

MEMO：

創造力 4P：Product、Person、Press、Process
創造力 4C：Big Creativity、Pro Creativity、Little Creativity、mini Creativity

→ https://www.youtube.com/watch?v=slycvTf8gis

紅卿：創意，是一個設計師的靈魂，千萬不能讓如山般的設計任務消磨殆盡。創意源自生活，怎樣去體會呢？設計師一定要養成良好的習慣，習慣從各種信息中提取到自己想要的信息，這樣的信息可以多種多樣，在超市有很多好的包裝設計可以讓我們學習，看電影有很多構圖和色彩可以讓我們學習，玩遊戲我們可以接觸到很多年輕化的元素。在日常生活中不斷的豐富自己的知識，這樣的日積月累，才會讓我們在設計作品中體現出自己的觀點和特點。

美玲：當公司新品推出時，獎金機制尚無法同步精準的改變，多數業務算盤一打，新品單價低、推銷難度高，於是把公司目標拋一邊，照推舊品，這是人性。但極少數業務卻願意放下短期個人利益，跟著公司一起上山挖礦。主管不是笨蛋，這兩種行為看在眼裡，自不會虧待願者，還會加倍獎勵。再如，線上線下資料要打通、線上線下消費行為要互導，都是數位轉型時最黑手、最麻煩的工作，不但得捲起袖子串接，做得汗流浹背不說，短期還看不到績效被說成沒表現，因此有能力的人通常腦筋一轉，就藉機打退堂鼓，卻有少數人願意接下這類工作，埋頭打磨，把一個個斷點連起來，讓系統運轉，成為轉型基石。轉型時，「願者」一個個浮了出來，「能者」卻一個個沉了下去…

文千：近两年来，亚马逊的平台监管政策持续升级，不仅加大对账号违规行为的打击力度，同时对产品的销售审核也趋于严苛。而就在近日，亚马逊再度发布禁售通知，大量薄膜袋产品受到波及。亚马逊「禁塑令」？8 月 5 日前必须移除这类产品！这一突发事件的背后，也显露出了亚马逊加强风控手段的决心。日前亚马逊美国站披露公告：由于相关法律法规的监管要求，所有不透明或单色的聚酯薄膜袋必须在 2022 年 8 月 5 日前下架。如若 FBA 卖家在 8 月 5 日后之后仍有相关薄膜袋的剩余库存，所有 ASIN 都将被亚马逊移除。

总体而言，卖家的产品包装需遵守相关规定，以规避不必要的入库风险。对于塑料袋包装的透明度亚马逊设有相关规定，但监管较松且没有强制性要求。不过可以明确的是，包装袋必须符合以下条件：

1. 密闭包装袋需带有防窒性标签。
2. 中国制造出口的货需贴上 made in china 标签。
3. 使用有色包装袋需在外部粘贴条形码，确保被顺利扫描。

之前跟 AUKEY 配合时，就是突然应 amazon 进仓要求，支架、黄盒、外箱都必须要贴 made in china 标签，所以后面新品支架都直接在塑胶壳上移印 made in china 字眼。我们若有一些 amazon 平台的客人，若看到相关政策要求，也可稍作留意。

豔梅：曾国藩有言：天下事，在局外呐喊议论，总是无益，必须躬身入局，挺膺负责，乃有成事之可冀。

躬身入局者，不只是对自己的业务或者自己下属的业务深入其中，对于不在自己职责范围的事务也能积极发挥自己的影响力，提供建议或方法解决组织的问题。不论在什么岗位上，都能时时把自己当做「组织上的主人」在行动。

惠卿：… 有時用文字可以一次敘述很多細節，但是因雙方可能在用語上、認知上及理解語氣上的不同，就會像我們這次一樣一直說不清，如果加上直接對話語言上的傳遞，誤解就容易說開，講電話是立即回覆，很多小細節一次就能說清楚。直接溝通有時也是增進雙方情感的方式之一，透過說話的溫度、語調、態度等傳達出各自的觀點及想法，未來太多細節的事件，我會再補強直接電話溝通方式，讓交流更加完善。

