本周公司團建活動：多一小步服務，再回頭看經理人跟曾國棟董事長之前的訪問，其實多一小步服務就是環繞在我們身旁的人事物，背後代表的是我們的態度及價值觀，不論是工作場合還是家庭生活，都可以運用多一小步服務，讓自己的待人處事、協調能力及專業素養更加提升。曾董說的 22 種思維裡最後一項，永遠要比別人要求或期待的多一步：這是「多一小步」最基本的態度，大家共勉之。

淑倩：遇事多想一步，多做一點，看似是在為他人著想，實則是在提升自己。因為在這個過程中，自己已經走在別人前面，化被動為主動。用利他的角度去想、去看問題，設身處地的去思考，還有什麼沒考慮到位、還能不能多做一點什麼、是不是可以交出更好的結果。正因爲考慮問題周全，對事情可能出現的各種變化和結果會預估比別人更充分，因此在面對任何突發狀況時，也能更沉穩的應對，也避免了很多錯誤的發生。

瑩如：本週公司的多一小步服務活動，增進了同仁間的凝聚力，同時也能多了解大家的想法與需求。我們能多做出一小步服務，可以讓伙伴們的工作更順利，進一步也讓自己的工作流程更順暢，看似利他其實也是利己。

可欣：「多一小步活動」的思維比起專業更可貴的地方是可以創造隱形的競爭力！如果我們願意在每一個作業環節的小細節上用「心」去想，從真心、同理心的角度去為對方考量，把事情做得徹底，讓對方深刻感受到你的「貼心」之處，能時時刻刻站在「如何延伸服務的角度」與「從他人立場」來思考，也許小小貼心創意，就能拉開競爭的差距；讓這一小步是『從自己做起』，不要用這個原則綁架別人，說再多不如自己成為別人可以學習的榜樣，讓我們學習創造自己難以取代的價值。

→ 是的，謝謝大家的認同與肯定，謝謝 Vivi 的活動安排。$wr$,
       $wr$見附件圖檔。網家的哀愁，其實就是組織老化的哀愁，每個人都會說，世上唯一不變的就是改變，改變的前提是意識，意識的基礎在學習，學習的基礎在認知。

人的老化需要數十年，組織老化可以在數個月之內發生，那是一種傳染病。本週在跟台北團隊分享，「你不該投資一間公司的理由」重點之一就是要去觀察，團隊是否具備變革意識？然後，從我們自己做起。$wr$, $wr$湘芸：本週討論到了複利的威力，會議上大家對複利的成效驚嘆連連，但複利的成效大都在長時間的累積後才顯的出威力，僅看短期的成果很難看出其巨大的影響力。想想複利的威力就是包含了決心＋堅持＋行動＋時間這幾個要素，當我們拿出這四個要素來做事，例如：學習一項技能、設定業績目標、健身和減肥都一樣，若我們設立了目標後能堅定地朝目標做出實際的努力，長時間下來一定會有所成效。

→ 是的，一篇文章，每個人的吸收程度都不同，尤其是專業領域的資訊。差異是在於每個人的背景知識能力不同，所以我認為，知識學習也是有複利的，越學越多也就越學越快，長久下來，人與人之間的知識落差將會非常巨大。

→ 就像是林森說的：读书能帮我们得到很多被忽略的信息，别人说生活中处处都是灵感，而你没有，可能就是因为人家书读得比你多，而不是因为人家是天才灵感从天而降什么的。

芳杏：「交代事情五步驟」，早在數年前，諸多著作談日本人的領導哲學時，就已經被提出來很多次。但還是老問題，很多好的想法或理論，知道與做到，完全是兩碼子事！

想要交付或是授權他人執行時，可以試試「交代事情五步驟」:

1. 先清楚說明交付的是什麼事情。（這是講解，不是提問。）

2. 詢問：「剛剛交付的是什麼事情？」（確認對方聽清楚了，沒有誤解、不會誤判，而且沒有聽錯。）

3. 詢問：「明白我請你做這件事情的目的是什麼嗎？」（確認對方清楚目標，目標只要清楚，在做決策時，就不容易偏頗。）

4. 詢問：「這件事在執行時會不會出現什麼意外狀況或問題？如果有，你的應對方案和計畫是什麼？」（思考預備方案，以確保任務更萬無一失。）

5. 詢問：「從你的角度來說，有沒有什麼想法或建議，可以讓這件事情更優化？」（讓執行者躬身入局，這不只是我交代的任務，更是你的責任，因為透過你的投入而執行得更好。）

