・拜會曾國棟$wr$, $wr$雲丞：很多人可以在自己每一個作業環節的小細節上用心，把事情做得徹底；但如果我們也可以在作業模式、機制或流程上多用點心，讓我們的多一小步為其他人創造出雙贏、三贏，甚至多贏的結果，不是更好嗎？

從對象上來看：我們可以針對客戶、供應商、同仁、主管、部屬、親友等等無論對象是誰，我們都可以用心對待，關鍵竅門就在於：時時刻刻都應該站在「如何延伸服務的角度」與「從他人立場」來思考。

這次的公司的多一步的活動讓我們用同理心的角度去為對方考量：「在這工作範圍內，我可以多做哪一小步，讓他們感到歡喜、方便？」這對雙方所產生的化學效應或工作環境氣氛，我相信絕對是正面的幫助。

每個人都應該制定多一小步的服務，要落實多一小步的執行並不難，在日常生活或工作中，讓對方深刻感受到我們的「貼心」之處，或是共享雙贏的喜悅。

→ 所謂的服務：為他人做事，並使他人從中受益的一種有償或無償的活動。

→ 多一小步服務，關注的是「我」或「我們」應做哪些行動，為「別人」創造「更多的價值」。$wr$,
       $wr$禹榮：今年下半年大部分企業都面臨訂單減少遠預期情況糟糕，最近在報價一些新品項部份的供應商的報價愈來愈貴高出同業 15~25%，有可能廠商原材料庫存單價高不願意低價承接我們的東西，

或如程天縱先生所言：在生意不好、稼動率低的情況下，銷貨成本增加，報價堅持目標毛利率，價格越高越沒有競爭力。

在經濟規模不夠的情況下，需要被檢討是營業成本及人力配置問題，一味的只檢討報價過低、毛利額不足，是無法看到根本的問題所在。$wr$, $wr$湄涵：昨日的全壘打，贏不了今日的比賽，昨天已經過去，要向未來看，就像本周周會心得主題「誰搬走了我的乳酪」這本書，昨天擁有的乳酪，今天突然不見了，長期擁有的東西突然消失，像是面對生活中的變化，對未知充滿不確定性的事物容易不安，也害怕改變，但是擺脫恐懼的方式就是採取行動，開始尋找新乳酪，才有可能找到下一個乳酪。

振慈：如何培養高成效的習慣，那就是穩定、持續的專注在高品質輸出。我們時常會把效率和效力搞錯，學了一堆如何讓工作更有「效率」的技巧，一直想著要做得愈來愈「快」，卻很少花時間去想如何做「正確」和「有效」的事情。成敗的關鍵不是做很「多」事情，也不是每一件事情做得多「快」，而是有沒有「持續」創造出關鍵的「高品質輸出」。當我們都有持續完成最關鍵的產出，那麼其他次要的事情，只要做到及格以上，別人就會以為你怎麼能同時做那麼多事，又做得那麼好。穩定取勝、按部就班前進，持續的成長才是最重要的。

→ 要做對的事，而不只是把事做對

可欣：最近看了一篇文章：從「心」培養影響力！文章有句話很觸動人心：「影響力是一種讓人舒服又信服的能力」，這就像綻放的花朵「吸引」著蝴蝶來追隨。

「一個有影響力的人，是以他人為中心，優先考慮他人的利益，站在他人的立場想，而不是要求他人站在自己的立場想；尊重他人，關愛他人，且不帶任何條件。這樣的結果，就產生影響力。」

簡單來說就是『從自己做起』！讓「影響力」由內而外的散發出來，說得再動聽，不如把事情做到位，用「以身作則」來展示成為大家的典範，讓自己身上散發這種「吸引」他人願意追隨、跟從的力量。

美玲：在職場上，我們覺得影響自己的是工作能力。但有一個看不見的影子，其實影響了一個人的職場命運。學校很少教、大家很少談，那就是「職場 EQ」。愛生氣的同事和愛抱怨的同事，他們不斷的換工作，因為他們找不到讓他們開心的公司。高 EQ 的同事則有不同際遇，他待在同間公司，除了升遷順利外，也深獲老闆和同事喜愛。也許這聽起來像老生常談，不過好的職場工作者，在職場上都帶著高 EQ 工作，愛生氣、愛抱怨，不只影響組織氣氛，更是組織裡的不定時炸彈。

→ 組織內不歡迎愛生氣、愛抱怨的炸彈，之前有同事分享，生氣是因為沒有能力解決問題。我們需要的是能解決問題的隊員。$wr$, $wr$台北的同事，請於每週週會時增加一個程序，週報分享時間，以抽籤的方式挑選 1-2 人，做 Woody 週報讀後分享。$wr$,
