人脈，比的不是認識的人多，比的是我們為多少人做過貢獻。謂之人脈存摺。

公司經營上，我們受了太多親人朋友、老師與同學、廠商、客戶、內外部夥伴們太多的恩情，因為這些貴人的幫忙，讓我們獲得了助益、規避了風險、得到了成長。

很多時候，這些幫助可能只是一句提醒、一份資料、一通電話，但這些恩情的價值卻是無價之寶。受人點滴之恩，當以湧泉相報。$wr$,
       $wr$芳杏：iPhone 也會中暑！蘋果點出手機熱爆溫度：最傷電池

台灣夏季持續炎熱，日間高溫在東部已可突破 40 度，台北亦經常可見 38 度高溫。手邊的 3C 產品，亦可能因高溫受到影響。

據蘋果官方在支援文件中說明，包括 iPhone、iPad、Apple Watch 與 MacBook，最適宜的環境溫度被設定在攝氏 16 ~ 22 度之間，一般也可承受 0 度到 35 度的高溫，但用戶應避免將這些裝置，曝露在高於 35 度的環境。

至於 iPhone 等裝置在高溫環境下「待太久」會遇到的問題，則主要是電池的蓄電量可能會受到永久性的傷害。蘋果也提醒，用戶也應避免在高溫環境中充電，且即使只是讓電池待在炎熱環境，也可能造成無法挽回的損壞。相較之下，在嚴寒中使用，則只會讓電池續航縮短，之後就會恢復正常。

https://3c.ltn.com.tw/news/50319$wr$, $wr$邓氏红：在职场中，一个人能否职涯跃迁的关键，在于格局，也就是看待事物的眼界与思维。当你的格局能因应职务而调整，就比较容易不断被赋予重要任务。所以要懂得「换位思考」，站在老板的位子，模拟他会重视的项目，长期的训练绝对会让你的管理思维有大幅的成长。当然，老板不见得永远都是对的，但当你掌握他的思考逻辑后，同理心就会多一些，也能有效拉近差距。

跨部门的合作，也需要换位思考，而且往往更困难，因为牵涉到资源争夺与立场差异。不过，部门间的互动关系，老板看得最清楚；愿意对其他部门伸出援手，当下也许没有直接利益，但长期来说是为自己广结善缘、累积口碑。

→ 很正確

福威：學習向日葵，做一個積極吸收正能量的人。生活中其實沒有多少大風大浪，人生多數時候都是自尋煩惱。所謂自尋煩惱，就是吸收負能量太多。學習向日葵那裡有陽光向那裡。多接觸優秀的人，多談論健康向上的話題，多想想有利於人身發展的問題。心里若是充滿陽光，即使下雨也變成春雨，滋潤你成長。

美玲：每個人的心中都住著一個「自我批判」。蟄伏在你我身後伺機而動，對我們的工作指指點點，我們必須學會關掉這些內在的自我批判聲音，這些負面的自我對話在日積月累之下，將會對你我的情緒和心理造成極大的傷害。

身邊一定都有認識一個凡事老往壞處想的人，他們常常抱怨和批評。和這種人待在一起會耗盡我們的心神，更糟的是，他們的負面情緒傳染力非常強。和這類人相處一段時間後，你會發現自己正面的心態正一點一滴被黑暗吞噬。

請珍惜自己的時間，不要讓自己的時間被負面的人占據了。應多花些時間和常保正向思維、樂觀看待未來的人相處。這類人自信滿滿、樂觀積極、能完成許多事情，和這類人相處能增強各位的心理素質與認知能力。

振慈：工作環境中免不了有著經常愛抱怨的人，就算大家都知道「抱怨是不起任何作用的」，還是忍不住邊上班邊抱怨，研究指出：「人類會以驚人的速度模仿他人的臉部表情、聲音以及姿勢，就像是高效的海綿一樣，融入他人經歷的生活。」所以一旦組織內出現一個喜歡抱怨的成員，壓力和負面溝通模式就像病毒一樣，迅速傳染給其他人，惡化工作環境氛圍。我們要避免自己成為愛抱怨的人，學習如何把無濟於事的情緒垃圾，轉化成改變現狀的積極力量，懂得換位思考，多一點體諒與練習正向思考、轉念。不抱怨並不是刻意壓抑情緒，而是藉由先停止負面的語言，讓自己歸零，接下來，將不滿轉化成正向的念頭，然後針對抱怨的事情，做出有意義的改變。

→ 曾有同事分享：抱怨像口臭，別人避之不及，只有自己不知道

瑩如：服務的同理心，就是親近客人實際的需求，在對方還沒有提出來之前，捕捉表情的變化、揣摩客人的想望，給予同理的考量。這件事說來簡單，做起來卻很不容易，而能不能真正把自己放到對方的情境中，體察對方可能會有的心情，然後設法滿足對方的需求，就是服務有沒有溫度最大的差異。服務最重要的就是同理心的思考，設身處地地為對方想，你就能知道怎麼解決當下的問題。要做好同理心服務、理解顧客到心坎裡，除了觀察力與服務心，還必須具備高度的服務專業。$wr$, $wr$台北的同事，請於每週週會時增加一個程序，週報分享時間，以抽籤的方式挑選 1-2 人，做 Woody 週報讀後分享。$wr$,
