・「創新研究獎」實地審查$wr$, $wr$將心得轉化為 Action 是塑造學習型組織的好方法，我們現在的週報已經達到大家關注產業發展與工作思考成為個人心得的目的，請各位繼續發展，將心得轉為行動方案，期待看到成果：

https://www.youtube.com/watch?v=xe6gMzH5wvY

1. 無論是聽演講、閱讀文章或觀看教學影片，你接收的都是別人的故事，要轉化成自己的行動才有用，也才是你的。

2. 心得轉化為 Action 的三個步驟很簡單：看完文章或影片後，馬上想一想最大收穫及啟發是什麼，過去自己的問題或迷思是什麼，準備改變什麼或採取什麼行動。

3. 內部講師培養有難度，觀看教學課程影片，讓主管成為引導討論者相對容易，討論的內容與部門行動相關，提高培訓的實用性

4. 牽涉到各行業的專業，最好請高階主管參與製作經驗傳承教材，扮演傳承的推手。

5. 人資規劃培訓課程內容，學員準備心得報告主管引導討論，就是把老師請回公司的元宇宙培訓，又可從心得報告中考核同仁的各項能力，一舉數得。$wr$,
       $wr$https://3c.ltn.com.tw/news/50432

這是一則應該沒有人會關注到的新聞，但這畢竟是台灣最大 3C 品牌的手機，台灣之光，但是不賺錢的生意，那，為什麼還會繼續研發生產？$wr$, $wr$美玲：AI 當道，不代表人的價值會被取代，個人技術再高超，還是需要團隊合作。一個作品的完成，不單靠產品與個人，還有當下的技術進化，之前做得再好，總有可以更好的空間。而成事與否，端看你用什麼態度與精神去面對挑戰。一個我行我素、無視規定的行事風格的人，對組織運作帶來的麻煩，就遠大過他的「能力」所帶來的正面效應。在職場裡，任何類型的人、專長、行事風格，都有其市場。只要你足夠認真、足夠專業，把屬於你的特色發揮到淋漓盡致，他人取代不來，你自然會在領域裡有自己的一席之地。絕大多數工作，都需要靠團隊合作才能成就。比起一位「超級明星球員」，組織更需要的是「明星團隊」，而成事與否，端看你用什麼態度與精神去面對挑戰

雲丞：同理心銷售

簡言之就是業務員站在客戶的立場，思考客戶想要得到什麼服務及什麼感受。

同理心銷售聽起來簡單，實務上並不容易做到。因為業務員面對客戶時，頭腦中幾乎無時無刻不在想如何快速成交。由於業務員無法告訴客戶「我來拜訪你是為了成交並賺錢」，反而要告訴客戶「我來拜訪你是為了提供優質服務與產品」，首先，業務要了解一點，其實客戶並不喜歡「被推銷」，而是喜歡「主動購買」！「主動購買」帶來愉悅感及滿足感！因此業務夥伴不妨定位自己是「協助客戶購買的顧問」，而非推銷員。其次，業務夥伴本身就有很多購買的經驗了，可以先回顧自己過往快樂及痛苦的購買經驗，然後類推到潛在客戶會期待的快樂購買經驗中必備的要素，再設法透過言行避開潛在客戶可能會感到痛苦的情境。

同理心的做法是：要站在客戶的立場感受客戶的感受。不只為客戶現在著想，要為他的未來著想。找方法解決客戶的擔心。當業務員能真實站在客戶的立場，思考客戶想要得到什麼服務及什麼感受時，客戶也會感受到業務員的真誠，將營造出開放坦誠的氛圍，有利於銷售過程中的雙向溝通。

→ 多一小步服務

文千：情绪价值指的是一个人影响他人情绪的能力，一个人越能给他人带来舒服、愉悦和稳定的情绪，他的情绪价值就越高。一个人总让他人产生别扭、生气和难堪的情绪，他的情绪价值就越低。情绪价值高的人，懂得为自己的情绪负责，还能给身边的人提供积极的情绪。我们可以根据自己对内容的理解和双方的关系亲疏，给予正面反馈。关注积极正面内容的反馈方式，能够引导别人把注意力转移到积极的事物上，再提供建设性意见而非消极意见，来解决问题。

可欣：在怡業行為準則中有說到：「雇用員工要看三種特質：正直、聰明與活力。如果沒有第一種特質，其他兩種會害慘你。我們拒絕喜歡走捷徑的聰明人。」人脈經營亦如此，別想撿現成的，才剛認識甚至才剛換過名片，就要請託幫忙；人脈存摺上的數字，來自價值互換，但存提款的順序若搞錯，效果天差地別；要將人脈變現前，得先問自己兩個問題：一、自己的價值，值得別人付出嗎？二、你付出了什麼努力，讓人家願意跟你交換？這二個問題實在令人有深刻的省思；的確成功有途徑，但沒有捷徑，唯有腳踏實地才能邁向成功，不要衡量別人付出，而是要問自己值多少的價值，值得別人的付出。$wr$, $wr$台北的同事，請於每週週會時增加一個程序，週報分享時間，以抽籤的方式挑選 1-2 人，做 Woody 週報讀後分享。$wr$,
