  (id, report_date, work, plan, reflections, intel, feedback, other, author_id, author_name, created_at, updated_at)
select $wr$b0000003t18upqp$wr$, $wr$2022-08-14$wr$, $wr$・「數位行銷」教育訓練－「數位行銷與會員忠誠度計畫」
・Q3 面談
・「創新研究獎」實地審查$wr$, $wr$・業務訓練教材評估$wr$, $wr$https://baike.baidu.hk/item/八大浪費/2272340

從同仁週報中學習到有一種浪費在八大浪費之外，叫做「知識的浪費」，表示組織中充斥的很多好的知識能力但未能善用，但我找不到同事的原文，哪位發的請回覆我一下，我要給予感謝。

延伸一下，一些「僵化」「老化」的工作者，會慣性地拒絕新的工作任務，甚至有些主管也會先選擇「排斥」，這是極大的浪費與罪惡。

各階主管要有意識的破除這種「浪費」，因為這是工作者的「成長機會」，新能力的培養是花用組織時間資源造就個人成長的機會，而開發團隊成員的能力是各階主管的使命。面對新任務的挑戰，應先考慮培養既有團隊的能力，而不是盲目的擴充團隊，造成資源的浪費與管理成本的提高。這個觀念極其重要。$wr$,
       $wr$涵暭：近日聽了一些 Open-RAN 的資訊，但網路上查詢的到的資料不多，提供幾個網頁如下，主要是想改變大型電信基地台由少數幾間廠商（NOKIA 等）壟斷的生態，「從技術上來看，Open RAN 是個虛擬化開放架構，它把傳統的大型電信基地台給解構了。傳統電信基地台設備供應商，是把軟體、韌體、硬體整合在一起。開放架構則分成 RU（Radio Unit）、DU（Distribution Unit）、CU（Central Unit）、基地台完全解構，將核心網路留在雲端，再把軟體、韌體、硬體通通獨立分開。一但架構形成，就可以由電信運營商自行引進一些白牌設備、亦即非傳統電信設備商所供應的產品，讓其他網路設備商更容易進入、共享大型電信基地台的設備商機大餅。」在理解 Open-RAN 的過程中想到早期 WPC（Qi 聯盟），一開始也是很多廠商加入，但是一直到 Apple 加入後才讓 Qi 更加蓬勃發展。我認為 Open-RAN 可能也會面臨這樣的挑戰。這個商業模式的發展也值得關注。

https://mic.iii.org.tw/industry.aspx?id=430&list=3$wr$, $wr$申氏秋妆：古人教导：三人行，必有我师焉。择其善者而从之，其不善者而改之。（《论语》）。任何人都可以成为我们的老师。不要怕与他人分享知识，分享的越多，学到的越多，付出的越多，得到有用的东西越多。仅从书本中汲取的智慧不会是智慧。人生没有不艰辛的工作，没有不复杂的知识，更没有完全平静的挑战。

振慈：80/20 法則，指的是 20％ 的變因素，操縱了 80% 的局面。在全局當中，能影響、決定結果的是「關鍵少數」，在組織中，重要的變因佔少數、不重要的變因佔多數，只要能控制重要的少數變因，就能影響全局。這個原則如今在管理中被廣泛運用，例如「公司 80% 的營收，來自 20％ 的客戶」，所以懂得掌握 80/20 法則，就知道資源該如何分配，才能創造更高的效益和效率。應用在工作層面上，使用 80/20 法則來優先執行一天當中必須先完成的任務，完成整個任務清單中 20% 最應優先執行的任務，就能為當天的工作成果帶來 80% 的影響。若要完成最具影響力的工作，就要辨別哪些任務對團隊有最大的影響，並在一天當中專心投入這些任務。我們的目標並非把付出的心力最小化，而是將心力專注地投入在具體的工作。我們仍必須投入 100% 的心力在那 20% 的重點工作，才能達成 80% 的成果。

→ 這是重要概念，但是最後一句可修正，我們應將 80% 的心力照顧 20% 的重點客戶，但一定要撥出 20% 的時間與資源經營其他的 80% 客戶，這是我們過往忽略的。亡羊補牢、猶未晚矣。

慶鐘：… 當我們只站在自己的角度看問題，很有可能忽略了對方的想法和感受，而所謂的同理心，就是試著去感受對方的感受，體貼對方的需要，站在對方立場去考慮同樣的問題。當我們用同理心去了解內部客戶或是外部客戶時對方也能真心感受到我們所釋出的真誠，進而產生更好的化學效應讓彼此都有更好助益。

→ 是的，先把手伸出去就對了。

可欣：『想辦法』是這次績效面談最深刻的提醒；公司找人就是為了要解決問題，當我們遇到困難要拋出問題時，目的應該是為了找出解決的辧法，而不是將問題丟給別人，所以在問問題之前，應該先試著自己「思考到答案出現為止」，不要一接到任務，只是問「該怎麼做」，應該要學習著「主動思考」，而不是只想跟別人要答案、要結果；當責是交出成果，不是交出藉口，思考…這個成果是為了要交差了事，還是你盡了全力交出了自己的價值。

→ 是的，切割問題不代表切割責任，問題還是問題。上帝的規則：給困難 找方法；魔鬼的規則：把麻煩 合理化。

林森：生活中与其他人意见不同是一件很正常事，毕竟每个人所处环境、心理状态等等都不相同。但也有一种人，意见不同时就习惯反驳别人，以突显自己的观点正确性。其实我们每个人都有自己的认知盲区，生活中更多的是我们不知道的东西。所以与其反驳别人，不如先向内求索。当层次高了，认知广了，原来的「不认同」，或许就会自然而然，变为「认同」。只有试着去用理解代替争辩，用内省代替反驳，不断完善自我，才能更加轻松地与人相处。一个人成熟的标志，就是脑海中能够同时存在两种看似对立的观点。

→ 很認同，成熟的人，有能力區分「觀點」與「事實」，前者是個人的「認知」，後者是科學的「真理」，每個人的「我以為」都存在一定的偏誤，用觀點來溝通會造成大量內耗，應用事實來溝通，這需要學習，也需要組織團隊的刻意提醒。

淑婷：除了工作交辦外，也要留意到工作上的細節及注意事項是否也有交待清楚，不要認為是常識或簡單對方應該要知道也或者對方也沒有問所以就不用講。等到發生問題時，究其根本原因，就是沒有從細節著眼──或許是你沒注意到，或許是你注意到了，卻因為過於微小而沒去做……林林總總的失誤，都是因為不注重細節導致的，有時真的可以避免「不經一事，不長一智」的發生，因為長一智的結果有時付出的代價是沒有辦法承受的，但是其實是可以透過經驗的傳承來降低錯誤問題發生。

→ 我準備教材給各位$wr$, $wr$台北的同事，請於每週週會時增加一個程序，週報分享時間，以抽籤的方式挑選 1-2 人，做 Woody 週報讀後分享。$wr$,
