select $wr$b0000008x40oekg$wr$, $wr$2022-08-21$wr$, $wr$・業務訓練教材評估$wr$, $wr$・教育訓練書籍選定$wr$, $wr$怡琪：最近接了一個通路商的客人，推薦他代理 peripower 品牌，對方也有興趣，跟客人開會之後，發現對於通路商的需求跟實際行銷方面的運作，我不是很了解，也沒有很多經驗。因此請教了 Jamie，Jamie 無私分享了很多過去的經驗，也花了時間跟我討論，給了很多建議，感覺到我們真的是一個團隊在合作。雖然過程中因為不熟悉覺得有點不安，且要花更多心力去處理，但透過每次學習新事物的經驗，又可以再成長了一點。

=> Thanks Emily and Jamie,

Yes, 這是我們團隊特色之一，所以我們業務會議一起開，就是為了一起學習與分享，通路多了解代工業務可以了解產業前沿發展與製造知識，有助於客戶服務與產品佈局；代工業務多了解通路經營有助於了解代工客戶的需求與產品的服務流程。最終都能夠開拓所有業務同仁的視野，有助於客戶的服務，也有助於業務人員的成長。

And, peripower 的國際化，可以讓我們接觸到海外廣大客戶族群，有效分散風險，降低價格門檻，但不可按照台灣的價格加成方式，因為現階段，我們能賺的就是按照代工的成本加上包裝製作的成本以及小批量製作的成本加乘，再加上品牌溢價，但是我們的品牌溢價現階段並不高，比較合適的定價方法，是回歸量價結構，製作階梯式價格報表，一到 10 個、10 個到 100、100 到 500、500 以上，諸如此類。這類客戶對於品牌產品線的完整度、廠商配合度等需求遠高於價格敏感度，單量可能不大，但穩定且後續可期，更重要的是，可以讓我們瞭解產業第一線的需求與變化，藉以改善我們產品佈局，最終也可以有效回饋並且有助於我們的代工業務及品牌業務的雙線發展。想了解更多？我有論文可以分享，但要寫心得報告。$wr$,
       $wr$怡芳、振慈：蘋果生產線南移！手錶和筆電將在越南生產，iPhone14 也將跟進？2022/08/18 數位時代

蘋果近來積極在其他國家建立產品生產線，除了手機已開始在印度和巴西等地生產外，智慧手錶和筆電等產品也有在越南進行生產的計畫，盡可能避免生產線的過度集中。由於今（2022）年上半年中國的防疫政策對電子供應鏈造成嚴重影響，包括蘋果在內的許多科技廠皆計畫將生產基地轉移至越南、印度等東南亞地區，避免生產重心過於集中在中國，盡可能地分散風險。

Apple Watch 其他產品相較起來屬於更精密的裝置，因此在生產時需要更高度的專業技術，而隨著越南進一步對科技製造業進行升級，在生產 Apple Watch 方面具有一定的優勢。除此之外，蘋果還有將 iPad 生產線轉移至越南的想法，以實現生產多樣化的目標，目前也正在和供應商密切討論有關在越南建設 HomePod 智慧音響生產線的相關事宜。

全文：https://www.bnext.com.tw/article/71285/apple-watch-production-in-vietnam$wr$, $wr$惠卿：經驗的傳承其實從最基本的工作日常中就可以開始學，就像前二周看過的「心得轉化為 Action」，當同仁們平日在分享經驗時，我們是把它想成故事，覺得跟自身沒關係，聽過就算了？還是從中找出能夠符合自己學習的事物轉化成行動力呢？

在職場上就算沒有正規的訓練管道，也可以利用偷師的技巧來加強自己的能力。所謂的「偷」，就是不知不覺，所謂的「師」，就是向比你強、覺得值得模仿的對象學習。所有的學習都是從模仿、效法開始，重要的是，如何把效法轉化成自己的想法與概念。身邊的各位同仁就是最好的偷師對象，但是要想學到真本事還是要靠自己留心地觀察揣摩才是。

→ 是的，組織內的學習資源俯首皆是，若一定要刻意停下工作另外安排時間才能學習，會自然被淘汰的。

涵暭：面對未知的產品開案領域，還是要多多討論，業務端不能只是把問題丟給工程，有時候還是需要跳下去一起思考方案。另外，與客戶面對面的討論，有時候還是非常必要的，很多問題可以討論的更全面一些。目前案子還需要工程方面的努力，這部份很感謝福威及各工程同仁的協助。（愛比科技案子）

→ 順帶回應 Julia 談到的「得踏入，然後一直做一直做，越來越了解，也就能掌握得宜，面對問題也會越來越游刃有餘。」a. 這就是「躬身入局」的思維，是知識工作者必要的態度；b. 如之前所討論，學習是一種「複利」，不斷累積基礎知識，一通萬通，越學會越快速的。

紅卿：需要是創意設計的泉源，認識到一種需要，本身就是一種創造的過程。「認識需要」是從生活或是生產的實在情境出發，去尋求想要解決的問題。問題的產生須要解答者自己定義，且答案也不是唯一。能否識別需要，關鍵是要有一個『問題意識』的頭腦，只有細心觀察，不滿足於現況，才能感覺到有問題存在，才會去深入探索。

我們更要經常注意去發現人類的潛在需要，許多偉大的設計師就是在社會大眾還沒有領悟到某種需要以前，就已經認識到這種需要。例如，社會大眾對電燈尚未有明確的需要之前，愛迪生研製電燈的工作已經進行了一段很長的時問。所以創造設計問題的關鍵常常不是解決技術上的難題，而是能就新需要產生新構想。

芳杏：越害怕越要不斷地刻意練習，讓自己的身體習慣成自然，在每次的練習時候發現自己的錯誤即時修正、重點加強，在練習的過程提升專注力，透過反饋來優化自己的錯誤和精進技巧，不斷地打破自己的紀錄，而使自己精益求精。

美玲：為感冒的常客煮一碗雞湯！晶華潘思亮的服務哲學：經營企業，文化比策略重要，好的企業文化可以是團隊由平凡變非凡的力量。碰上危機時，愈能體現企業文化的價值，因而，企業之根最好能是普世價值（golden rule），不會隨著物換星移消逝。稻盛和夫曾提出的一個成功方程式：「人生．工作的結果」＝「想法×熱情×能力」。這個方程式裡，最大影響變數是人的想法，可以是正向也可以是負向，會影響相乘結果。

https://www.managertoday.com.tw/books/view/65601

佳鈴：稻盛和夫曾提出一個成功方程式：「人生．工作的結果」＝「想法×熱情×能力」。這個方程式裡，最大影響變數是人的想法，可以是正向也可以是負向，會影響相乘結果。在這個方程式的想法就是「將心比心」，一切都可以連結到這個原點，也是行事的度量尺。將心比心是進入你我之間的領域，從自身內在走進別人，當在這核心領域可以帶進、包容外在的其他人，甚至是所有人，一個人就能與眾生萬物同在。將心比心是待人如己，透過自己去影響與幫助別人，利人則利「生」。

=> 「人生．工作的結果」＝「想法×熱情×能力」。是的，並且，是乘法。$wr$, $wr$台北的同事，請於每週週會時增加一個程序，週報分享時間，以抽籤的方式挑選 2 人，1 員做 Woody 週報讀後分享，一員針對自己的週報做分享。$wr$,
