・FR 眼鏡美、日市場跟進$wr$, $wr$軍徽、明隆：华为任正非也喊「活下去」。8 月 22 日下午，华为内部论坛上线了一篇关于《整个公司的经营方针要从追求规模转向追求利润和现金流》的文章。任正非在文内提到，全球经济会持续衰退，消费能力下降的情况，华为应改变思路和经营方针，从追求规模转向追求利润和现金流，保证渡过未来三年的危机。

Woody: 怡芳也提到了任總的分享，並且帶出預算的問題，要注意，這兩年我提出業績目標的時間，都是在年中，並且提出：如果明年我們的目標是如此，那我們「現在」要做甚麽？一如，假設，我們要組一個團隊，明年要在明年的 400 公尺接力賽跑進前三名，那麼，我們今天要做甚麽？

注意：

1. 為什麼是前三名？因為只有前三名才有獎勵，團隊才有辦法生存，如果訂一個必然能達成的目標，但團隊眼看活不下去了，或是活得沒有品質，那又有什麼意義？

2. 目標不應該是走了一半再乘以二為標準來調整，這樣達成的目標也不能叫做目標。數字可以看狀況微調，但 a. 要能活得下去也要能活得有品質 b. 要有支持調整的理由。

3. 一個有企圖的團隊目標，應該是以 big hairy audacious goal 為原則，如果還有一年半可努力，目標訂出來，一定有辦法可以達成。

4. 注意我的造句「我們今天要做甚麽」，如果今天照昨天一樣生活，也不需多此一問，這句話的蘊含意義是，「我們今天要做甚麽改變？」。

怡芳分享，任正非：「我們對未來過於樂觀的預期情緒要降下來，2023 年甚至到 2025 年，一定要把活下來作為最主要的綱領活下來，有質量的活下來，每個業務都要去認真執行」，任正非提到，華為要縮小戰線，集中兵力打殲滅戰，提升盈利，華為將會徹底放棄一部分國家的市場。不要再抱幻想，講故事騙公司，損失要從你們的糧食包中扣除，首先要活下來，活下來就有未來。

把人力物力集中到主航道；一定要把邊緣業務從戰略核心裡抽出來，邊緣業務抽出來後，評價能不能做好、需要多少資源才能做好。

「讓寒氣傳遞到每個人」，任正非強調，獎金升職升級與經營結果掛鉤，各責任中心簽署考核責任書，今年各個業務的獎金一定要拉開差距，絕不允許平均逼迫大家實現搶糧食的短期目標，「過去公司的政策是基本擺平，大家沒有感覺到冬天的寒冷」$wr$,
       $wr$承前，找到一篇幫大家整理過的內容，看看吧：

http://www.iceo.com.cn/news2013/2022/0824/310140.shtml$wr$, $wr$禹榮：員工的 80/20 定律

傳統的職位說明書，將「產生 80% 績效的 20% 重要工作」列在兩三張紙上。讓員工只要做這 20% 的工作，就可得到 80 分的績效。但別輕忽員工每天每月所需做的其他 80% 工作。若員工沒做好職位說明書上沒寫的 80% 工作，則容易「敗事有餘」。原來得到的 80 分也會被扣分，導致工作表現不佳。而這 80% 的工作，就會依「個人價值觀」來決定心中的判斷行事的準則。

如：中國員工在大陸亂開車，但到美國上班就慢慢開始遵守當地交通的規定。因為核心價值觀影響到人的行為及習慣。

美玲：每一項令人陶醉的產品，都是創造者在背後付出了數不盡的心血灌溉，並且將自己的理念落實在耕耘的每一步中，才能獲得豐碩的果實。而背後的這一切，往往讓我們敬佩與感動。心中也不自覺想要向他們看齊，將這些善良利他的理念落實在自己的生活中。

幸福不是收穫的多，而是抱怨的少，遇人不苛求，遇事不抱怨!

芳杏：自己具備跟對方溝通的共同知識時，通常在互動上會比較順利。在公司裡，面對不同職能或是部門的同事，如果能夠懂一些對方的工作內容，就比較能理解他之所以提出某些需求背後的原因，站在別人的角度去考慮需求，並做出相對應的行動或改變。我們都能做到換位思考，就可以跳脫出自己的小框框，願意站在更高的角度來綜觀全局，就有機會在團隊中發揮更高的價值，提升公司的勝率。

→ 很好的反饋，其實很多時候溝通不良，有可能是我方的問題，我們是否具備對方的專業？具有對方的高度？了解對方的處境？如果能夠通透的理解，將有助於溝通。

可欣：剛開始寫新版週報時，為了獲得更多材料來撰寫，而增加了搜尋閱讀短篇文章的次數，慢慢開始閱讀文章變成了習慣；這週公司又發了指定閱讀書籍，並限制一周內要看完，對我來說一周要看完一本書實在很不容易，公事永遠都處理不完，無止境的家事也擺脫不了，只能用滑 FB 的時間來換取我翻頁的時間，我還在試著改變自己努力翻頁，也許時間真的不夠時，才會強制改變習慣用自己零碎的時間來閱讀；習慣的養成不容易，找藉口卻很簡單，只能下定決心必須完成，才能將手上的書如期交給下一位，也許傳遞的不只是書籍，而是傳遞出我們的競爭力及企業文化。

→ So true.. 想一下一個經典問題：如何吃掉一頭大象？答案是一次吃一口。

如何一週唸完一本書：假設書本有 280 頁，每天看 40 頁。

惠卿：本周閱讀《CSI 工作術》，最後一章節「豬肉一斤多少錢」的例子貫穿了這本書全部內容，所有作業流程中環節都想一遍（包含跨部門作業），先思考再做事；學會聽話（傾聽）才能真正收到、了解及滿足對方需求。不管職務高低，隨時都要做出大大小小決定，設法讓這些決定做到位，讓你的工作成效彰顯出來，久而久之就會讓同仁主管認同、信任你，並放心將工作交給你完成

