・Gain Switch 案件跟進$wr$, $wr$週報改版已有一段時間，透過「心得思考」的分享，有助於提高組織的溝通品質。我期待看到的回饋方向是：

a. 從工作中總結出的心得與感想，及改進提升的方式；

b. 從學習中的心得反饋。

最近有一些指定閱讀，大家可以從閱讀當中反饋學習心得。閱讀，就是為了學習；不同於網路資訊，透過讀書，能夠有系統有步驟地吸收知識，「學習」是組織前進與改革的底氣，值公司必須大刀闊斧升級之際，我必須加大逼迫大家學習的力度，請各位跟上腳步。

附上怡萱的範例。切記，學是為了用，道理知道，也一定要做到，付諸實現，才是真道理。

怡萱：本周閱讀「多做一小步，創造難以取代的價值」，在職場中想要往上發展、往前邁進，除了專業素養外，更需要其他方面的能量，包括協調能力、待人處事的圓融度和成熟度，「多一小步」不只是一個小動作，是來自於用心、講究細節的關鍵一小步，背後所代表的不只是你的態度和價值觀，也是人際關係的表現，和攸關日後的職涯發展。這種發自於內心的隱形競爭力，是大家在職場奮鬥的不二法門。$wr$,
       $wr$雲丞：歐盟擬延長智慧手機使用壽命，專家：恐消滅低價機

歐盟 8 月 31 日公布草案，要求智慧手機業者提供備用零件並確保電池壽命，讓智慧手機的使用期限能延長至 5 年。專家估計，新規定對 Android 業者影響較大，超低價機種可能會消失無蹤。

金融時報報導，歐洲執委會（European Commission）草案明定，智慧手機問世後至少 5 年，業者必須提供 15 種不同零件，並確保電池能完全充電 500 次、充電量不得低於 83%。

另外，一如洗衣機和洗碗機，智慧手機也需有節能標章。不只如此，提案涵蓋軟體，規定智慧手機上市後，必須提供 5 年的安全更新，並要提供 3 年的功能更新，這是 Android 廠商的一大挑戰。

歐洲的智慧手機銷售以 Google 的 Android 作業系統為主流，軟體更新通常不會持續太久。CCS Insight 行動分析師 Wayne Lam 說，草案對小型智慧手機業者的衝擊較大，對蘋果和三星等產業巨擘影響較小。這是小品牌的一大負擔，他們在歐盟販售的機種將有限制，可能讓智慧手機變得更難以負擔，或是徹底消滅超低價機種。

非營利組織 European Environmental Bureau 研究顯示，歐盟出售的智慧手機壽命拉長至 5 年，能減少 1,000 萬的二氧化碳排放，相當於路上減少 500 萬輛汽車。$wr$, $wr$可欣：稻盛和夫談工作曾說到：要成功，得先愛上自己的工作！熱情才是成功的鑰匙，想要真正的成功，必需先愛上自己的工作。沒錯！當你對工作沒有熱情時，只會想日復一日的把工作「做完」然後準時下班；但熱情，會讓自己想著如何把工作「做好」而不是「做完」，會有動力持續不斷的改善及成長，或是思考該如何在自己的工作上有所創新。沒有一份工作是容易的，也沒有一份工作不會有挫折與低潮的，唯有找回自己的熱情，這一切會迎刃而解，也許我們不用等待伯樂的出現，自己也可以成為自己的伯樂。

涵暭：日本經營之神稻盛和夫於 8/24 辭世，相關報導文章很多，擷取這兩篇：緬懷稻盛和夫｜從 32 句名言看日本「經營之聖」的管理思維

https://www.managertoday.com.tw/articles/view/65656

