・Gain Switch 案件跟進$wr$, $wr$・寶可齡董事會
・HM Plus 網站整合
・業務發展策略$wr$, $wr$你是「對事」負責？還是「對成果」負責？

本周周報有同事寫到了，對於後續工作的跨領域主動跟進，這是必要的。

很多時候，如果我們只是把自己手上的工作交出去，但是卻無助於最終成果，這就不會是當責的態度，當責當中所提到的 one more ounce 就是要我們做個有肩膀的人，在工作上多思考一步，多想一步，上下游多一步提醒多一步的協助，如果有其他單位同事有疏漏。我們應該就要立刻介入，讓整個事件專案能夠有效的推動下去，這個才是真正當責的態度。

所以我們在看待每個工作的時候，一定要想清楚，我們只是把自己的部分做完了，其他「與我無關」，還是一路關注與協助，讓專案有確實達到最終的效果？

你到底是「對事負責」還是對「成果負責」？如是前者，基本就不是負責的態度，交出成果才是硬道理。$wr$,
       $wr$林森：

在苹果 2022 年秋季新品发布会上，苹果除了推出 iPhone 14 系列、Apple Watch S8、AirPods Pro 2 等新品外，还推出了本次发布会最便宜单品——Incase 挂绳，售价 98 元。据介绍，这根挂绳长 23.5 厘米，重 4.54 克，适用于 AirPods Pro 2。用户可将柔软的编织绳像手环一样戴在腕上，也可用自带的卡夹将挂绳固定在背包或手提包上，确保充电盒随身，还方便取用。

→ 是我們可以佈局的產品

政男：

來自木薯可再生材料的生物塑膠射出件：https://www.smartmolding.com/22-06a06/

對於生物可分解材質, 就是以動植物／細菌合成／以及澱粉為原料的塑膠, 又稱綠色塑膠, 在高溫以及特殊環境下是可以自動被分解的, 對於環境的保護, 是有極大意義的, 但是發展至今還不普遍, 除了塑膠製程加工困難, 再來就是成本高昂, 而且材質的物性極差, 要不是綠色意識抬頭, 使用這種原料的機率很少, 所以我覺得我們客戶希望我們嘗試使用這種材質, 這對我們來說是個機會, 如果我們可以開先例, 又能夠成功的以這種材質克服各種缺陷, 對我們後續的發展會更有競爭力 也更有優勢。$wr$, $wr$怡琪：這兩週參與兩次不同的廠商會議，雖然是討論同一款產品跟同一個廠商，但與會人員討論的內容深度是不同的。透過這個案子更加體會廠商資源的重要性，以及談判的技巧。如果希望對方與我們配合，也要提升自己的專業程度，還有讓廠商了解我們可能的規劃，產品只是其中一個案子，讓廠商感受到我們需要找的是一個未來可以長期合作的夥伴，而不只是比價而已。

→ 是的，好的廠商會挑選客戶，一如我們的業務宗旨：「業務開發最重要的事情就是選擇對的客戶」，文化面很重要，但如果客戶專業不足，配合起來就是虛耗資源。面對廠商，我們首先要展現我們的整體經營策略，其次要說明長期的配合利益，至於要有意識的提升我們整體專業是最基本的，才能爭取到配合的機會。

淑倩：我們在出門前都知道，要到達目的地，會事先查清楚哪條路最近，才不會走冤枉路，但換到自己在工作目標計劃時，卻不能如此完成，是因為沒有經過同樣仔細的思考，盲目地跟隨。

究其原因是没有把想法化為縝密的計劃，再把計劃化為有效的行動。所以要先改變方法，改變習慣，先釐清希望有什麼樣的結果，才知道如何規劃輸入，就是由產出回推到輸入，也就是未來要產出什麼，取決於現在就要投入什麼，讓自己能看到一條道路是連貫在始與終之間。

→ 這就是 OKR 的精神，我們即將進入 OKR 2.0，會從部門展到個人，請各位先思考自己對於部門 OKR 的產出影響，我們再逐步發展。

湄涵：最近看到一篇文章「悶不吭聲才會失去信任感」，當中寫到建立工作專業感不單是把事情做好，而是主動回報最新進度，讓合作的客戶放心，別怕暴露缺點而悶不吭聲，讓客戶不斷地來詢問，主動回報進度，不只讓客戶知道你正在為他努力，甚至有機會釋放更多有用的資訊給你，推動事情進展，就像《CSI 工作術》一書也提及到的一點，就是別怕發問惹人厭，或是擔心過度打擾，應該要積極主動和相關人員更新進度，以達成工作目標為前提主動出擊、主動確認，無論是對內的同仁主管或對外的客戶都是一樣的概念，這是我需要再學習的地方。

