康揚輔具結合感測與雲端科技 協助智能長照

涵暭：本周參觀醫療展，一間廠商的業務跟我聊，直接給我們建議，可以找輔具類的廠商合作支架。參觀過程中，覺得做輔具類的廠商不多，而我們要找的又必須是生產輪椅、電動輪椅類的廠商，使用輪椅的身障人士才有可能會需要手機架，其餘的輔具似乎不太有我們可著墨的地方。康揚的業務有特別說需要能夾持管徑的支架，並且要是鋁管型的，會再與對方接洽。

→ 謝謝，若把我們的核心從「固定」改為「模具、塑膠、五金、電子」，再重新跟客戶溝通，或是定位客戶，應該就會有「很多著墨的地方」。走出去、問客戶，就對了。$wr$, $wr$振慈：在工作上每天都要進行的就是溝通，不管是對上對下或是內部外部，溝通都是很重要的一個環節，也是一個技巧。有時難免會有無效溝通的發生，以為對方了解也接收到了資訊，或是自以為了解，但其實中間都會存在著某種程度的落差和誤解。現在習慣在經歷了一場溝通後，會在最後總結剛剛所討論出來的結果，並且用條列式的方式明列出，和對方做再次地確認，並且在掛掉電話後會將溝通的內容再用文字列出，以免忘記了內容為何，有時也會使用選擇題或是是非題的方式來詢問，以再次明確溝通內容是否雙方都認知清楚。有效的溝通是傳遞者清楚明確地傳達訊息，使接收者完整地了解所傳遞的資訊，因此即便你認為自己已經明確地傳遞資訊了，若對方沒有清楚地接收到訊息就不能算是成功的溝通，對於工作上的討論協作也沒有幫助。溝通就是一門技巧一門技術，經常性的練習使用，也會有助於我們工作上的進展。

涵暭：最近與既有客戶電話或是郵件聯繫，得知有些客戶考慮或是已經在做一些跨領域的產品，譬如 Moshi 有另一間公司專門做咖啡設備（https://www.hiroia.com/zh/），韓國客戶 JJ 原本是以 DVR 為主，但因為常看到我們寄給他的新產品 FLYER，也開始思考是否可以賣一些這樣的配件產品在韓國國內。他們都跟我說，大環境是不好的，但還是要 keep going。跨領域做事情真的不是一件奇怪的事情，雖然可以想像還是有很多事情是在做的過程才知道有困難（我們不熟的 know-how），但也是正面看待並當作養分，最近做愛比的案子也是有此感想，我們的確是「能做」，但遇到的困難真的又比我們想像的多，需要一個一個問題解開。

→ Just do it.

慶鐘：內部溝通有時會因為跟對方太過熟絡會忘了應該有的禮節或分寸，導致對方內心的不愉快或是溝通認知上有落差，都會導致工作的延宕或失誤。因此對待同事如果能像對待客戶一樣那麼對方會覺得受尊重，被重視。溝通時保持愉悅、親切的聲音，會使對方如沐春風。請託同事幫忙時對方也一定樂意幫忙，最後也別忘了跟對方誠摯地說聲謝謝! 時時心存感恩的人運氣真的不會太差，境隨心轉當一個人有太多的負能量那麼就真的會一直很倒楣。讓自己多跟正向積極的人相處然後自身也積極保持正向，不管工作或是生活日常都會一切順遂，即使偶有陣雨，但也終將雨過天晴，柳暗花明!

→ 是的，「時時心存感恩的人運氣真的不會太差，境隨心轉當一個人有太多的負能量那麼就真的會一直很倒楣。」$wr$, $wr$台北的同事，請於每週週會時增加一個程序，週報分享時間，以抽籤的方式挑選 2 人，1 員做 Woody 週報讀後分享，一員針對自己的週報做分享。$wr$,
