・OKR KPI breakdown$wr$, $wr$稻盛和夫先生上月辭世，我們曾多次分享過他的人生成功方程式．工作結果＝思維方式（－100～＋100）×努力（0～＋100）×能力（0～＋100）。這個方程式是京瓷哲學的核心。

另一個核心，就是阿米巴組織，簡單說，就是可以獨立核算營收的機制，讓每個專案、每個小組、每個單位都能有效的計算出生產產值與費用，如此才能專注於營收最大與費用最小，這也是我希望打造的組織，請見淑倩的分享。

淑倩：要打造一支戰鬥力、凝聚力強的團隊，是要從文化、制度、培養等各方面入手。亦即做到了解人性、獲取人心，能讓公司持續走得更遠。阿米巴經營把公司劃分成若干個小集體，每個小集體都按一個小公司的方式進行運營，獨立核算，自負盈虧，並對最小的經營組織進行業績評估。它的本質是打造一個員工具有自驅型，而非被動執行的團隊。通過定價和附加值的核算，量化每組每崗的貢獻，同時提供清晰的價值提升途徑，促使大家對「應該怎麼做」思考，最終達成「營業額最大化、費用最小化」的高收益目標。也就是把公司的經營目標分解到各個部門，讓各個部門承擔自己應承擔的經營責任，讓員工看得到自己的績效和激勵。所以阿米巴經營管理可以打造一個好的團隊。先在管理裏設定一個任務，把需要一起完成任務的員工都拉到這個任務裏面來。並且設置好每個人負責的崗位。當做完這個任務時，可以記錄做這個任務的人能夠帶來多少收入，付出了多少費用。爲公司帶來的利潤一目瞭然。$wr$,
       $wr$于嵐：https://www.businessweekly.com.tw/business/indep/1002552

D2C 趨勢崛起，品牌加速落實「以消費者為中心」的經營思維，面對市場競爭加劇、獲客成本逐年高漲的現狀，若品牌的 D2C 經營還只停留在架設電商官網、對消費者投廣告做折價促銷，將面臨效益不斷下滑。而無論是純電商或實體門市品牌，D2C 的關鍵優勢在於運用數據資產掌握顧客需求、發展出更有效的顧客經營和溝通策略，目的是升級顧客與品牌的關係。$wr$, $wr$紹軍：孔子說：「知之者不如好知者，好知者不如樂知者。」對自己的工作學習與了解，把它變成興趣，做有興趣的事，從每次遇到的困難中獲益，才能從工作中得到精神享受。

芳杏：https://www.bplan.com.tw/post/sales-techniques-0511

電話陌生開發，開發時間點很重要，最好的時間建議：

電話溝通（或其他口語溝通）最好在上午 10 點至 11 點 30 分之間進行；Email 溝通（或其他文字溝通）最好選在下午進行，特別是下午 3 點發出的信件，最容易獲得回應。

愈早打電話，雖然對方接電話的機率明顯高很多，但很可能對方正在忙，反而不願好好聽你說話；反而是上午 10 點至 11 點 30 分之間，對方願意接電話並跟你聊天的機率最高。同時，過了中午 12 點之後，對方願意接電話的機率就越來越低，到了下午 6 點之後，更幾乎沒有勝算。

但與電話相對的是，過了中午，客戶反而更願意看 Email。一直到下午 6 時下班前，都是 Email 的黃金時段。所以想要聯繫客戶，最好在下午 3 點之前把信發出去，因為對方最不願意接電話的時間，可能都在認真看信。

振慈：混亂是上升的階梯，當處於隨時變化的狀態裡，要保持非常靈敏的嗅覺，能夠隨機應變，隨時調整自己的心態和知識技能。到最後可以成為一個六邊形人才，什麼都懂，什麼都會，而若是每個人只守著自己原有的那一畝地，久了也會忘記要打破邊界才會有互相融合的機會，如果一直做自己容易上手的工作，永遠都是原地不動，只有做過一些重大的，艱難的，超出自己能力範圍之外的工作，才能起飛，主動去做一些超出自己知識體系之外的事情，Learning by doing.$wr$, $wr$台北的同事，請於每週週會時增加一個程序，週報分享時間，以抽籤的方式挑選 2 人，1 員做 Woody 週報讀後分享，一員針對自己的週報做分享。$wr$,
