・OKR KPI breakdown to everyone.$wr$, $wr$・2023 預算細化，從 2022 Q4 開始
・數位行銷課程與專案檢討$wr$, $wr$公司是誰？$wr$,
       $wr$雲丞：Apple Watch Ultra 支援 GPS L5，什麼是 L5？

多年來，消費型電子產品利用單頻的 GPS 接收器來定位，但隨著更多新推出的產品開始增加對第二個 GPS 支援，這種情況正在逐漸發生變化。「支援 GPS 定位」是最常聽到的籠統說法，但最近從 Apple Watch Ultra 的官方規格中，你可以看到「支援 L1、L5」這樣的說法，這次我們就來了解關於這些名詞的新知。

在過去很長一段時間裡面，智慧型手機、車載系統與智慧手錶使用被稱為「L1」的傳統頻率獲取 GPS 訊號並確定位置，L1 的廣泛使用幫助改變這個世界，但這個頻率很容易受到影響而失準。

因此，美國政府一直在推動 GPS 現代化計畫以跟上時代變化和技術的先進，而其中就包含正在部署三種新的民用 GPS 訊號：L2、L5 與 L1C。

為什麼 L5 很重要？就如同前面我們提過的，L5 在目前最先進的可用民用 GPS 訊號，因此，智慧型手機、健身追蹤器、車載導航系統和智慧手表等大眾市場消費型電子產品正在試著將它整合到設備中，以提供最佳 GPS 體驗。

L5 訊號擁有的主要優勢之一是它使用 1176.45MHz 的無線電頻率，該頻率保留用於全球航空導航上，因此不必擔心該頻率受到任何其它無線電波流量的干擾，像是電視廣播、雷達和任何地面導航輔助設備。

使用 L5 數據，你的設備可以用更高階的方式確定哪些訊號的誤差較小，並且有效地確定位置點。在可以接收 GPS 但訊號嚴重弱化的區域特別有用，這種環境與情況下，L5 因為擁有加大的頻寬可以提供更多資訊，有利於確定接收訊號中所存在的反射。

此外，更強的 L5 訊號還可以在密集的都市環境中實現更好的覆蓋範圍，並且幫助設備快速定位，而它較低的頻率更能增強室內使用時的接收效果。$wr$, $wr$振慈：商周集團的執行長郭奕伶提到，近期商周也在面臨轉型，當他們面對到訂戶數持續下滑。如何止跌回升？如何重新定位自己、找到新的商業模式？三年的轉型交出了成長的成績單，但他提到不只是看數字上的成長，他覺得在轉型中收穫最大的是經營結構與文化的轉變。他引用了心理學大師薩提爾的話來詮釋這個改變，「我們因彼此的相似而連結，因彼此的差異而成長。」許多轉型失敗案例後發現，八成的踩坑都是敗在溝通這關；而再好的策略、再強的執行力，都敵不過軟弱而分歧的人心。唯有大家一條心，才可以將困難化為機會，但一條心必須來自信任；而信任，則來自不厭其煩的對話。「我們因相似而連結，因相異而成長。」這將是我們一起建立的團隊文化：彼此連結、欣賞差異、共同成長，這樣美麗而動人的文化，或許面對轉型的混亂及不適應，但只要團隊一心朝著同樣的目標前進，所經歷的這些風雨，回頭看來都會是大家成長的養分。

美玲：日前桑崎 HM2 負責窗口更換，無論是在機器生產製造排程交期或是機器問題處理都能隨時反饋及處理，讓我們覺得是在同個頻道上溝通，也反映在近期交貨的 HM2 不良率已有明顯改善，所以，工作上遇到對的夥伴是很棒的一件事，良性的互動跟溝通才能讓事情事半功倍。

→ 原窗口與我們配合超過二十年，認真有餘，因屆齡退休而更換窗口，意外之餘也有些不捨，但這改變也確實帶來新的氣象

→ 良性的互動跟溝通才能讓事情事半功倍。是的，從我們自己開始

可欣：「溝通」是工作非常重要的環節，現代社會有許多快速簡易溝通工具，如通訊軟體（line、skype）、e-mail 也許可以節省不少時間，留個言等回覆，但很多時侯就是沒有進一步的瞭解或面對面的溝通，而造成認知上的差異，小則造成工作進度的落後，大則可能造成公司財務上的損傷。在面對面的溝通過程中，我們才容易找到認知上差異的地方並清楚直接的解決問題，而不是用「揣測」的方式找問題；不要害怕溝通，不要「自己以為對方知道」或是「我有發信通知了」就省略溝通，省思一下自己有沒有常說「我以為你（他）知道了」，學著多打一通電話確認，多走幾步路去面對面溝通，別再因為忙碌，而省略了溝通。

怡琪：對於六路開關控制器的案子，因為太多電子方面及安規的問題需要釐清，加上這些都是新的東西，還有多家廠商的資源整合，常常在處理的過程會很容易卡住，但冷靜下來一個一個解決問題，沒有資源就往上尋求協助，好像也就突然豁然開朗。我覺得適時向上出聲求救也是很重要的，不要怕問問題，重點是要把問題解決，釐清自己的疑問，再往下走。尋求幫助也是解決問題的捷徑，確保自己執行的方向正確，有效率的把專案完成才是重要的。

→ 能豁然開朗，是因為擁抱問題，不斷的思考，並採取行動尋找答案，恭喜你的成長！稻盛和夫先生年輕時嘗試開發產品，做不出來，就睡在現場，就抱著產品睡覺，常常會在睡夢中突然蹦出創意想法，再趕快起來實驗，是這樣的態度成就了京瓷。

于嵐：跟客戶確認事項往往是以信件往來，因我們都是國內客戶居多，所以對我們來說回信之外，最快確認內容的方式，直接打電話跟客戶確認問題內容，才不會在等候問題的答案，等待過久的時間，也可以加快彼此之間事情的進度。

→ 是的，人的溫度、面對面的情誼、語言的親和力，是全人類共同的，不論國內國外客戶，都應該盡可能地創造見面的機會、或視訊、電話溝通，文字是最不得已的方式為之，又或者是作為記錄使用。

湘芸：業務會議時討論了 TAM、SAM、SOM 的概念，我們目前的困境之一是 SAM 的客戶數太少，還有缺乏 A 級客戶。近期著眼在尋找市場的 A 級客戶和做潛在客戶的 ABC 分類，一下子要做的事情很多，讓人很迷惘，但一次一次的會議說明後加上內部討論，現在要做的事的輪廓慢慢清楚了。先篩選出重點目標客戶再去開發，依照大數法則的概念，希望可以開發到一些客戶，增加我們的既有客戶數量。業務的開發工作是一步一腳印的累積，過往我們較忽略開發新客戶，現在發展的方向明確、產品軸線清晰、思維轉變，接下來就是有紀律的執行。

→ 太正確了，所有的困擾都是因為 SAM 不清楚，SOM 太少，但只要清晰方向，有紀律地執行，成果，只是時間的問題。我已看到隧道口的陽光了。

紹軍：最近看完《比專業更重要的隱形競爭力》，正好剛幫女兒買了一個（怡寶）的書包，打開後發現裡面有一個信封，上面寫「給未來 穿越時空的信」，大致內容是要我們寫一封給孩子的信寄回它們公司，1000 天後會幫我們寄回家給孩子（驚喜）。正是書中提到的「別人不願意做，它去做」、「永遠比別人要求或期待更多一小步」，在父母還沒實際檢視書包前，先看到這封信對（怡寶）的好感就多了許多，覺得很有心。原本產品的品質與品牌服務就做得不錯，只再多用了 2 個信封 2 張紙 2 份郵資，額外多了這一小步，不僅能抓住許多父母的心，讓人備感親切，還能大大提高回購率。因為設定在 1000 天後收到未來信，也正好是大多數孩子要換書包的年紀。

→ 很棒的故事，學習了

紹軍：會議上，如何給出「有料的」回饋？劉潤：4 個準則，工作越做越出色

1. 給回饋的時候，要讓對方感受到：你的態度很真誠、建議經過深思熟慮、出發點是利他的、目的是為了讓事情更好。
2. 在 Netflix 的企業文化中，如果員工有意見卻不說出來，會被認為對公司不負責。
3. 為了讓員工好好的回饋，Netflix 建立了 4A 回饋準則。每個人都能及時知道哪裡需要改進，然後馬上調整。

https://www.businessweekly.com.tw/careers/blog/3010702

→ 得到內的劉潤的五分鐘商學院系列音頻是我很喜歡的材料，建議可收聽

紅絨：抱怨是一个坏习惯的原因有很多。抱怨会恶化你的情绪，让你专注于问题和错误，让你怀疑和不值得信任。当你的指责让他们感到软弱无力，无法帮助你时，抱怨也会让你周围的人感到不舒服。一般来说，抱怨只会让你自己以及你周围的人的生活更加沮丧和无聊。你需要意识到的最重要的事情是，抱怨不会解决你的问题，只会分散你的注意力，让你忘记真正需要做的事情。所以，你所做的就是抱怨、责备，扼杀你对未来的所有希望。$wr$, $wr$台北的同事，請於每週週會時增加一個程序，週報分享時間，以抽籤的方式挑選 2 人，1 員做 Woody 週報讀後分享，一員針對自己的週報做分享。$wr$,
