・越南團隊課程安排$wr$, $wr$上週心得，阿杏提到了沙灘車團隊的觀察，講到一個成功的團隊，不可或缺的一定是要有專業、熱情、訓練（紀律）、互補（團隊），怡芳也有以下補充：「團隊中每個成員都可以替補其他成員的角色, 每個成員都把球接的很好, 這是怎樣的默契可以讓一個活動辦的讓客人充滿歡樂和印象深刻, 這蠻值得我們思考一下, 我們一直以來都在強調團隊, 但我們被部門化了, 其實我們做的任何事情都是為了同一個目標, 我們應該更加彈性於各個專案, 公司的目標達標才是我們共同的努力方向。」

我跟怡芳的討論中，還特別提到一個觀察，一個好的服務團隊，是要懂得如何『要求客戶』，客戶的安全是首要，其次是不可以影響或妨礙到其他人，如果客戶不配合服務團隊的要求，也會影響客戶自己的消費體驗。在完成團隊共同目標的前提下，對客戶有所要求，是絕對必要的。

反映到我們自身的狀況，也是如此，我們希望每個專案都能夠超越顧客期待，因此，首先要先設定合理的客戶期待，不做沒有把握的承諾。客戶期待值落定後，就進入專案合作的階段，此時是需要多方合作配合才能順利推展專案，我們有責任必須不斷『要求各方團隊』，透過不斷的「提醒」與「要求」，方能確保專案的品質。$wr$,
       $wr$惠卿：需求銳減貨櫃船沒貨載 全球航運減班潮越演越烈

在歐美等地，隨感恩節揭開序幕的年終購物季帶來消費熱潮，業者提前加緊備貨，因此第三季通常是航運業的傳統旺季。然而，由於俄烏戰爭、中國工廠停工、全球經濟惡化等多重衝擊，航運市場旺季行情失靈，面臨無貨可載、大量航班被取消的現象。

外媒先前報導，Braemar 貨櫃航運分析師 Jonathan Roach 指出，隨著能源價格飆升、通膨居高不下，全球經濟衰退風險升高，引發貨運需求大減，另方面，各國全面解封後，民眾不再瘋狂購物，也導致疫情對貨運市場的提振效應消退。

https://www.moneydj.com/kmdj/news/newsviewer.aspx?a=1f983574-5cce-4f0a-a00b-80d31c424a43$wr$, $wr$淑婷：剛好在公佈欄的新知學習看到這篇文章「企業貫徹初心 利他創造多贏」

想到我們的願景「讓行動生活更美好」，我們也是能夠站在客人角度，創新或推薦客人需要的產品，真正幫助到客人，也可以讓自己有成就感。商業不是零和遊戲。我們不需要在獲利和行善之間做出選擇。大家都應該貪心一點，全部都要，做出對社會、環境、同仁、消費者和股東都有利的政策。貫徹企業初心，有好的宗旨，就能吸引好人才投入，也就會有好的業績，達成多贏局面。

https://udn.com/news/story/7340/6368548

→ 是的，這是我們不斷強調願景重要性的原因，我們的所有努力，是為消費者創造福祉，是要為社會、為工作夥伴帶來正面的回饋與影響。

賺錢是結果，不是目的。

惠卿：擁有好人緣的人，大多都善於傾聽，不但會在別人說話時專心聆聽，更懂得用心理解說話者想講什麼。溝通，也是從傾聽開始，而耐性則是學會傾聽中最重要的課題，按捺住「嘴巴跑得比耳朵快」的壞習慣，別搶著搭話，別急著指正，給對方解釋的機會，了解錯誤的原因，好好聆聽對方的需求跟需要。逐步練習，讓傾聽成為溝通的第一步。

怡萱：人人都可以是業務，但要成為好的業務，除了要為自己創造業績外，更要為顧客創造價值，因為現在這個年代，強迫推銷已經行不通，要以顧客為中心，陪伴潛在顧客面對各種現實的問題，針對不同的顧客扮演不同的角色，了解顧客的痛處，回答他們問題，根據他們特定的需求，提出相對應的解決方法，將自己定位成為能夠為他們增加價值的導遊和顧問，才可以成功的引導顧客順利通過購買過程。

→ 是的，先思考我們能為客戶創造什麼價值，這個價值才是客戶下單給我們的原因，是我們能夠賴以生存的利潤。如果無法為客戶創造價值，那麽這客戶早晚是會離開的，或是我們應自己終結這段關係。

慶鐘：話語的溫度，這個溫度聽起來很抽象，但往往可以帶給顧客有不一樣的感受。前些時候公司樓下的全家便利商店因某些原因造成人員異動，後續新進人員因流程不熟悉造成人潮回堵外，店內人員也因慌亂忘了應有的服務態度，對顧客詢問的問題回應時略顯不耐煩，讓人感受不到服務的熱情，凸顯了該企業對員工的教育訓練不足，以及人員徵選時的考量不周，後來幾次早上也發現以往常出現的常客不再進去購買，而是過馬路到對面的 7-11，而自己現在也因這原因而選擇多走幾步路到對面的 7-11 做購買，如果一間企業因看似微不足道的小細節而流失客人，短時間內也許不會受影響，但長此以往將動搖企業的根本。值得我們深思!

→ 請各位參考上週「誰是公司」

可欣：疫情 2 年多以來，從中看到許多夥伴美好的品格，有的是嚴以律己，有的是為了他人著想，又或者是為了團隊能心安，總是會不惜成本的多篩檢幾次，用高規格的態度要求自己，也用高規格的態度對待他人；我相信這些人不管是在待人處事上，或是在工作的態度上，一定也有著相同高規格的態度。態度，看似只是小小的差異，卻能決定一個人的高度，造就日後的差異，正所謂「決定你人生高度的，不是你的才能，而是你的態度。」這些具有美好品格的夥伴們，真的很值得學習及被尊重。

