沒複製到「陌生人社交」精髓 臉書、IG 抖音化踢鐵板

即使同樣名為「社群網路」，用戶的真正需要卻是南轅北轍。TikTok 的成功，正反映了年輕世代對社交需求的轉變。如今 Meta 要超車對手，就必須釐清用戶對平台真正的期待，才可能複製得精準又到位。

對於要加大行銷力度的我們，必須要清楚每個平台的受眾與運作模式，方能決定如何運用各種媒體。否則，散彈打鳥，耗費資源卻未必能有收益。$wr$, $wr$秋恒：营收和费用需要分开来看，这两个指标有不同的达到的方式

+ 营收最大，要求你满足顾客的要求，不断地发展自己的能力，服务更多，带来更多的收入

+ 费用最小，是要看自己管控成本，找办法节省费用，不断地评估自己，优化生产程序。。。

→ 正確，如思考的是利潤最大化，就不是「利他」而是「利己」了。我們應先思考幫客戶創造價值，其次要要求自己提升效率、精實，控制成本。

惠卿：在學校讀差不多先生的故事時，其實沒有什麼太多感觸，但是出了社會以後，差不多的工作態度看似沒什麼影响，次數多了，職業生涯可能就葬送在差不多的態度裡。認真處理每一個細節，不要讓同事或主管為你收尾，工作上拒絕「差不多」，將每份任務，不論是大是小，都認認真真地做好，是一份責任，也是一種工作態度。

可欣：講到如何面對資深但不資優的員工，到底「資深」，是組織的資產? 還是包袱? 公司年資 8 年以上的同仁剛好佔了一半，想想自己到底是組織的助力? 還是阻力? 若是「資深」代表薪資成本較高，那是不是要思考自己的貢獻度有沒有成正比? 不要讓過往豐富或成功的經驗綁住自己，若你只想站在原地回頭欣賞過往的豐功偉業，那很快就會被世界快速變化的浪潮所吞噬。

