       $wr$湄涵：CASETiFY 是曝光度蠻高的手機保護殼品牌，常與其他知名卡通、經典角色品牌聯名，每當有新聯名產品，常看到相關行銷新聞，在 CASETiFY 官網首頁可以直接看到一類是聯名系列，與本週營運模式主題 Co-Brand 呼應，CASETiFY 儘管與很多國內外大牌聯名，但對 CASETiFY 品牌印象並不會因此糊焦，看到新聞的主體都會強調 CASETiFY 與某某聯名，而不只是某某品牌圖案的手機殼而已，產品本身也提供多樣選擇，還有客製化服務，更貼近消費者需求。

CASETiFY 攜手華納兄弟推出第二波《哈利波特》聯名系列 融入電影經典元素
https://gnn.gamer.com.tw/detail.php?sn=239724$wr$, $wr$振慈：本周周會又再複習了之前的一個概念，叫做時間顆粒度，「時間顆粒度，可以看出一個人的職業化程度。」—劉潤，作者說一個人的職業化程度越高，時間就會顆粒，甚至還會粉末化，以前看到或許覺得有這麼誇張嗎，但隨著工作與內外部團隊配合頻率越多、也就像作者所說的職業化程度越深，越會感受到時間顆粒度的重要性，我們不僅要配合不同人的時間顆粒度，也要尊重大家對於時間單位的認知，其實，每個人一開始的「時間尺度」都是大的，但隨著身份不斷疊加、能力的提升，以及責任不斷加重，時間變得越來越顆粒狀。我們必須要妥善管理好我們每一個時間片刻，讓自己的「每一塊時間」都能好好運用，把握片刻，認真去做。

惠卿：本周週會時有講要培養自己的時間顆粒度，相對於職場上就是掌握時間管理，時間管理好的人，通常工作也是比較不會拖延或延誤的，因為他們會意識到哪些事是現在立刻要做，哪些是被打斷也不會影響進度及時間安排，會很自覺得排出事情的重要順序，安排時間越有彈性，就更能面對各種被打斷的變化，而不是最後一刻才全部擠在一起處理。時間管理也不是一種能力，而是不斷的刻意練習，再內化成習慣，不會做不到，隨時都可以開始管理自己的時間，從過程中慢慢修正及持續累積不同經驗，最終一定能夠掌握什麼時候該做什麼事。

可欣：週會抽問公司必讀書籍時，發現曾經閱讀過的文章回想起的時侯竟一時間無法想出該如何述說概要，這樣的狀況很類似在專業上也許很精通，但卻不懂得如何用淺顯易懂的方式讓對方聽懂或是傳承；自己應該試著在每篇文章或書籍都讀完時，問問自己這本書在說什麼，或是將想法有系統的「說出來」，可以幫助自己整理思緒，或是也可以試著對別人述說文章大綱，藉由別人的發問來調整自己的觀點，幫助自己將思考脈絡逐漸釐清及加深記憶；每天進步 1%，一年就會強大 37 倍！

→ 費曼學習法

于嵐：這禮拜碰到幾個客服案子，我們都是一步一步引導出客戶真正的問題是什麼，後續客戶也有給予我們實際的回饋以及肯定，所以我覺得對於客服的事情，最快速的處理方式就是直接電話聯繫客戶，直接了解客戶實際上使用的問題，用最快速的方式解決客戶的問題，客戶對於我們的印象也會提升並肯定我們，之後也會因為我們良好的服務，而再度跟我們購買產品。

→ 是的，能當面講的就不要打電話，能打電話就不要發郵件或簡訊$wr$, $wr$台北的同事，請於每週週會時增加一個程序，週報分享時間，以抽籤的方式挑選 2 人，1 員做 Woody 週報讀後分享，一員針對自己的週報做分享。$wr$,
       'C00001', '劉恕偉', timestamptz $wr$2022-10-23 09:00:00+08$wr$, now()
where not exists (select 1 from public.woody_reports where report_date = $wr$2022-10-23$wr$);

insert into public.woody_reports
  (id, report_date, work, plan, reflections, intel, feedback, other, author_id, author_name, created_at, updated_at)
select $wr$b0000009arzl37n$wr$, $wr$2022-10-30$wr$, $wr$・拜訪信昌 車用結構件廠商
・拜訪強弦 IC 設計廠商
・萬旭跟進$wr$, $wr$・備課：營運模式選擇
・FR Glass 案後續評估
・面談$wr$, $wr$本週台北倉庫因為疫情緣故，許多夥伴機動的到倉庫去支援，以下是兩位夥伴的心得回饋，我藉此重申：

1. 跨部門支援、擔任多職能工，是最好的組織內部學習管道，主管不需預設立場認為團隊不願接受新的工作而剝奪了大家互相學習的機會

2. Teamwork，要去部門化，需要各部主管刻意打破框架，改變不會自然發生的

3. 所有的問題與知識都在現場，到生產現場工作與學習是必要的

4. 台北一直有一項政策，新人，尤其是業務，報到後的第一個月應該先在倉庫實習。不論現在的資歷，當初沒有拿先修學分的，應找時間補齊

5. 林森說：这世上，凡让你变好的事情，过程往往伴随着不适。

楷軒：這週協助倉庫出貨我認為是個不錯的經驗，除了能了解倉庫狀況外，撿貨時還能發現「原來這產品還有人買，而且需求不少」，又或是「原來這產品出的比我想像中的慢」這樣的狀況，這通常是無人會反映的事情，因為對倉庫與業務來說是被習慣的事情，但這正是市場最直接反映。或許適時讓設計師參與各環節的工作也會有所收穫。

森梅：好不容易渡過了魔鬼周，經過一周的歷練，學習到出貨端因不同的結帳方式，出貨流程皆不盡相同，深刻體會美玲的辛苦，謝謝阿杏及小賀的投入及把關，讓這周的出貨都能如期的完成，感謝 SANDY 及 SHIRLY 協助工單及收貨，順利完成發票的開立。$wr$,
       $wr$歐盟達成協議 2035 年起將禁售內燃機引擎汽車

https://udn.com/news/story/6811/6721710$wr$, $wr$彥菩：無論是說服他人或說服自己採取某個行動，很多時候我們以為只要把提案弄得夠吸引人或是強調產品的優勢有多好即可，但問題可能不是出在提案或產品不夠吸引人，而是心理摩擦力。不是我們的點子不夠好、想要倡導的事不夠重要。而是我們沒有把「人」的心理抗拒因素考量進去。例如客戶現在如果有這類型產品，就會「懶」的在新增這類型的供應商，或者是客戶要新增一間供應商，要走的行政流程瑣碎，會感到「麻煩」。有時候把焦點放在減少「心理摩擦力」而非產品本身，或許是成交的關鍵要素。

→ 是的，業務面的問題，客戶都有答案，產品面的問題大多數是問得出來的，流程面的問題需要透過觀察與感受，業務的歷練可由此看出。

振慈：溝通技巧是軟實力中的關鍵，我們對內，怎麼與主管、同事及下屬順暢合作，對外，如何跟客戶、供應商聯繫好關係，溝通表達技巧都是不可或缺的技能。要怎麼做到快、狠、準地表達，同時又能提升對方的聆聽意願？首先，「開頭就說完結論」，這麼做一來可以吸引聽眾，二來也有利於雙方在溝通上對焦。第二步是「詳細說明」，將前因後果詳加解釋，讓對方利於理解，為何會得到此結論，最後則是「再重申一次結論」，強化論述的可信度。撰寫 email 也是如此，秉持「不遺漏、不贅述」的原則，除了問候語外，只需要寫清楚相關事件的時間、地點及目的，且切記一封信只能傳達一件事，在字數上必須以對方無須滑動頁面、「不超過一個螢幕」為標準。否則資訊過多、或用詞太冗贅，而造成收件人的負擔。從工作上的每一個小細節上注意，不僅可以增進我們在職場上的技能，也能在雙向溝通時達到良好的效果。

淑倩：不懂得感恩的人，只會把別人的給予當作理所當然，只會一味索取而不知回報，也不會體驗到團隊相互給予及創造利他的快樂。相對懂得感恩的人，能夠從為他人創造的快樂中享受給予的樂趣。而且也是一個心胸寬廣，對人的態度是積極的、陽光的、也比較樂觀。碰到壓力或逆境時，原力也會比較快，對每件事情會尊重，看待事情也會少一些抱怨，會多一分發自內心的熱心幫助與快樂。所以要懂得感恩團隊，感恩團隊給予的協助、幫助和支持，珍惜團體共有的成長經歷。

林森：我们总是看别人容易，站在原地抱怨生活的不公，其实不如全面提升自己。很多人顺从贪图安逸的人性，只想待在舒适区，可这世上，凡让你变好的事情，过程往往伴随着不适。多向前迈一步，多往上攀一寸，多比别人承受些不适，你再回头望一下身后，其实已经不知不觉就前进了许多。

可欣：本週績效面談後發現，在檢討某些執行面困難的地方時，在得到的反饋及提醒後，發現其實解決並沒有想像中的困難，首先是問題是可以『隨時』被解決，不一定要等到面談時再反應，資源一直都在我們身邊，只是自己會不會使用，再來就是『不停的溝通』，不管是對上、對下、對專案進度、或是對教育訓練，有問題就是要持續溝通，溝通直到問題被解決。就像 OKR 的精神，就是要學著拆解問題、分析問題，再逐一找到解決對策；把複雜的事簡單化，再逐一克服，學著將思考模式轉換，提升自己解決問題的效率及能力。$wr$, $wr$台北的同事，請於每週週會時增加一個程序，週報分享時間，以抽籤的方式挑選 2 人，1 員做 Woody 週報讀後分享，一員針對自己的週報做分享。$wr$,
       'C00001', '劉恕偉', timestamptz $wr$2022-10-30 09:00:00+08$wr$, now()
where not exists (select 1 from public.woody_reports where report_date = $wr$2022-10-30$wr$);

