select $wr$b0000008expdagv$wr$, $wr$2022-11-06$wr$, $wr$・CONNACT 專案討論
・拜訪 ELECOM
・面談$wr$, $wr$・接待印度客人
・宜蘭大學交流
・中小企業總會交流$wr$, $wr$我是一個「跑業務的」，我很期待與客戶互動，客戶給予的回饋及資訊總是讓我成長，客戶幾乎總是能解答我所有的疑問，包含購買決策及背後原因，我也非常享受解決客戶問題帶來的成就感，透過發覺客戶的痛點與潛在需求，盡可能給予建議與協助，也讓我建立龐大的朋友圈層。若剛好能有交集，我們的產品與服務要先能讓客戶獲利，我們自己的公司才能受益，得以生存，這就是我的業務人生。

「跑」是動詞，本週很開心能夠跟 Julia 去拜訪 Elecom, 我學習非常多，也請各業務盡可能幫我安排拜訪重點客戶。

摘錄 Julia 週報分享：… 從客戶的身上也看到我們自己的影子，看到我們該如何讓客戶更依賴我們的一些重點因素：持續地觀察客戶需求、抱持開放學習的態度不間斷地了解市場的新事物新產品、勇往直前地推廣產品／提案。Woody 在會談中與客戶談了很多公司發展的歷史跟脈絡，並不斷提醒客戶，產品的呈現除了是呈現產品本身以外，更重要的是讓客戶知道我們能做什麼類型的東西，呈現的是我們的核心能力，讓客戶知道我們隨時都有機會、有能力為他服務。就算是我們不能做的，也可能幫客戶介紹適合的供應商或是人脈。…$wr$,
       $wr$涵暭：不堪虧損擴大 蝦皮陸續關店裁員

https://udn.com/news/story/6811/6626652$wr$, $wr$振慈：… 企業文化可以歸結為內化為行，將理念層面進行總結，並形成規範和要求，落實到制度和行為裡，企業文化是透過實作、實踐出來的，內化成當我們遇到問題或是處理事情的態度是第一個產生的想法和念頭，並且透過不斷的檢討、反省、考核，一次次堆疊出來的想法和行為。

→ 是的，越在上位者越要注意所有言行。反之，言行越符合者，越應該升遷。

淑婷：本周由夥伴分享的心得中－自我修練的心法內：走出去，說出來－樂於分享，和人群互動，不斷的累積自己的人脈存摺。

當我們有任何需求，或是工作、生活上遇到瓶頸與困擾，思緒一時被卡住，不得其解時，一定要「走出去」，透過各種機會與拜訪，積極和你的人脈網絡分享、請益；並且要說出來需求，才能帶來回應，進而解決問題。

同時，養成習慣主動關心，對別人的活動熱心參與，盡力解決他們的問題或幫忙介紹資源。樂於助人，有一天別人也可能幫助你。

→ 我的業務人生就是如此，拜訪客戶，不一定要跟我購買產品，我是聚焦於能如何協助他們，但最終，我們的收穫總是多於付出，我總是這樣感受的。

秋妝：饱满的麦穗总低头，枯萎的麦穗高仰脸

《菜根谭》中有这样一句话：「低地成海，人低成王，圣人无名，大者无形」。谦虚是一种修养，即使成功了，也要懂得放低自己，理解和尊重别人，给别人留一点面子，也是给自己一条回头路。

有句谚语：「不知者无畏，知而深深畏」。无知不可怕，最怕的是狂妄自大。自以为无所不知的人，其实知识只是冰山一角。就像一只坐在井底的青蛙，被困在有限的认识中，无法前进，但仍然喜出望外地自以为是。相反，人知道的越多，受的教育越丰富，就越卑微，因为他们知道山外有山人外有人。

栖息在树枝上的麻雀叽叽喳喳叫个不停，天上展翅的老鹰常常沉默不语。

我们的生命是有限的，我们的知识也是有限的，要谦虚才可以学到更多。$wr$, $wr$台北的同事，請於每週週會時增加一個程序，週報分享時間，以抽籤的方式挑選 2 人，1 員做 Woody 週報讀後分享，一員針對自己的週報做分享。$wr$,
