select $wr$b00000060lfgfeg$wr$, $wr$2022-11-13$wr$, $wr$・接待印度客人
・宴請創新研究獎有功人員
・中小企業總會交流$wr$, $wr$・創新研究獎交流
・越南行程
・SS 來訪$wr$, $wr$本週受邀參與政大 DBA 論壇，主題是「永續」，我提到企業可以透過強化永續來建構我們的價值與競爭力，可由對外與對內兩個面向探討。

對外的部分，強化永續有助於我們吸引重視環境議題及管理的客戶，也可以當作我們自我品牌的差異化概念，由設計端開始，逐步提高環境友善的材質與包裝，如可分解材質塑膠、永續森林認證紙張、生質油墨印刷等等。

對內的部分，我認為，年輕世代更注重工作與公司的經營理念及企業對於永續的理念，強化永續的經營模式有助於企業吸引及留任好的人才，打造有競爭力的僱主品牌。

因此，對環境與社會議題的投入是正面的投資。$wr$,
