https://shop.tesla.com/zh_tw/product/desktop-supercharger?sku=8756722-00-A$wr$, $wr$郁庭：其實能培養出第二專業的，都是在工作中認真做好每一件事情的人，無論是否屬於自己份內的工作，都會認真的去做。要知道，做分外的工作才是培養第二專長的最佳機會，這樣才能直接有經驗，因為做過才知道該會什麼，之後再把不懂的去請教同事，或買書來補足基本知識。

多數人對於該培養哪些技能成為自己的第二專業，其實自己很難知道，而常在那裡尋尋覓覓，事實上只要把自己接觸到的每件事情都盡力做到最好，願意做分外之工作，就有機會培養出第二專長，然後平時多讀書、多觀察別人做些什麼、積極爭取參加非自己專長的教育訓練、願意接受挑戰，這樣，不但是樂於助人，還一舉兩得，何樂而不為呢？

艷梅：《周易》劝诫我们说：「君子以厚德载物。」

人的德行是生存于世的根基，财富、地位、权利，乃至世间万物，都需要深厚的德行以承载。如若不然，就是在损耗自己的福报。修德修己，修身养性，德、财兼备，生活才能越过越顺。

美玲：卓越，是一種習慣

順手完成，是良好的工作習慣。雖然這可能讓自己相對緊繃，但基於人的記憶力有限，盡可能在現場完成工作，不但贏得時間，也提升了工作的精準度。「我們重複做的事造就了我們；因此，卓越不是一次行動，而是一種習慣。」亞里斯多德說。一個順手完成的小習慣，透露了每個人對時間資源的看法，也造就了不同人的平庸或卓越。

阿草：… 从本质来看，闭环思维强调的不仅仅是责任心，更强调团队配合和人际敏感性。不仅仅是完成事情本身，更需要心里装着与此相关的人。工作中各部门、各级别的沟通主要包括布置任务、提出要求、发出命令、督促落实、请示事项、汇报工作、反馈结果、提出建议等。布置一项工作，无论大小，不论轻重缓急、是否存在困难、是否完成，都要形成一个完整的「闭合」回路，其中需要反问自己的是：我是否在约定的时间内给到反馈？我是否在项目进行时阶段性的和领导作报告、沟通，并主动给到反馈？我是否每一个环节都为我最终的目标负责？…$wr$, $wr$台北的同事，請於每週週會時增加一個程序，週報分享時間，以抽籤的方式挑選 2 人，1 員做 Woody 週報讀後分享，一員針對自己的週報做分享。$wr$,
