・OKR$wr$, $wr$下文來自 Emily，我非常同意，Emily 也總是能針對目標，想辦法、尋求資源。但職場上總有許多人認為，目標太高、資源有限，天下無難事，只要肯放棄；或是，反正我認為我已努力了，達不到就算了。

因此，資深不代表能力的提升，解決方法並不難，只要提升自己的高度，用更高的眼光去看待目標，細看整個組織與專案，甚至是組織外部的資源，整理出行動計畫，並針對問題點主動出擊，解決方法一定比問題多。若還有問題，請來找我。

Emily: 本週行銷會議提到了做專案要先想好目標，路徑以及資源。這段與之前 OKR 課程一致，決定好目標之後，去思考要如何做到，以及需要甚麼資源，都列下來之後。突然覺得這就是我們每天在做的事，客人提出需求，我們想辦法，尋求資源以達到目標，做客戶專案也是同樣的道理。原本覺得很複雜的事，套用此邏輯，也會知道該如何去執行。$wr$,
