https://udn.com/news/story/7239/6769350$wr$, $wr$淑婷：必讀文章—我以為……

在自己犯錯時勇於承認錯誤並且自我檢討改善，避免重覆犯同樣的錯誤。「人非聖賢，孰能無過」，「道歉」是在萬一犯錯，用來維護好不容易建立起來的信用，千萬不要變成了「習慣道歉了事的做法」，會讓道歉變得廉價也會失去夥伴對我們的信任。

→ 是的，「我以為」有虛妄猜測之意，但聽來更像是卸責之詞，事情發生了就是事實，應先面對問題、承擔問題，儘速思考解決之道，而不是先切分責任。

淑倩：對於協同工作，有些人特別大度，而有些人特別小氣。只為自己著想者不會大度，能替別人著想者不會小氣。只有能力差的人，在小事上計較，不在做事上認真，容易的事也難成；能力強的人，對事情全力以赴，不在情緒上計較，難題也會輕易化解。正所謂成大事者不拘小節，沒必要在任何事情都斤斤計較，做個心胸開闊、樂善協助的人。

惠卿：讓自己持續成長的方法還有一種就是跟周遭的人學習。向傑出同事與朋友學習，隨時記錄他們值得我們仿效的優點與行為。向直屬主管、Mentor 學習，吸收在做人處事與職場的智慧及專業知識。見賢思齊，見不賢內自省，看到別人越多優點與專長，才能發現自己的短處再加以補強，並向學習對象看齊。$wr$, $wr$台北的同事，請於每週週會時增加一個程序，週報分享時間，以抽籤的方式挑選 2 人，1 員做 Woody 週報讀後分享，一員針對自己的週報做分享。$wr$,
