・ESG 課程$wr$, $wr$湘芸：這世界不缺有想法的人，欠缺的是行動的人。

有想法而不行動，一切都是空想。一旦目標明確，檢視自身的資源、評估風險、擬定行動策略後，朝著目標前進才有可能成功。所有的行動即使經過縝密的計畫，也不能保證每次的結果都會成功。即使失敗也不可怕，面對失敗從中分析原因，從而學到的知識、經驗可以應用在未來的行動中。成功沒有既定的方程式，每個成功的配方都不同，自身的努力、運氣、金錢、人脈資源…都是可能影響成功的要素，不管手中握有多少資源，只有付諸行動才有成功的機會。

上週的我對 Scosche 新案子的吸盤開案很徬徨，很擔心開模後還是沒辦法達到客人的期待。但，Woody 說只要有方向，資源與能力沒有限度，有希望，有努力，就能完成。福威也是說邊做邊調整，這款料不行我們就找下一款料。再想想很多台灣的中小企業也是土法煉鋼，最後找到獨特的成功竅門。感謝團隊在我徬徨時給我支持，確實我們最該擔心的不是失敗，而是怕失敗就不行動，做就對了！

Woody → 謝謝肯定，一開始時，我們本來就什麼都沒有，沒什麼好怕的。

我一直認為，從錯誤中（數據中）調整找方法，不斷嘗試各種可能性，從失敗中累積經驗，是找尋出路的最佳途徑。

我也認為，公司的資源，絕對不只存在於公司之內，走出去說出來，只要真心想要做一件事情，天地鬼神都會來相助。

就算是一個小螺絲，只要有心，也能成就大事。盯著問題看的人、都是被自己的思維卡死的；只會盯著問題看的人，不適合存在這間公司。

只要努力，沒有做不到的事，解決辦法一定比問題多的多。$wr$,
       $wr$惠卿：日本首家企業！SONY 從手機、耳機開始淘汰塑膠包材

環保議題興起，全球企業開始使用可持續材料，SONY 宣布明年取消包裝塑膠，成為日本首家淘汰塑膠包裝的電子公司。除了 SONY，蘋果 2021 年將包裝塑膠量減少至 4%，並計畫 2025 年前完全淘汰。惠普已將 PC 和其他設備的聚苯乙烯改成紙質包裝。由於大多數塑膠在自然界不易分解，並產生許多塑膠微粒，傷害海洋生物。歐盟 2020 年宣布 2030 年前禁止使用這些塑膠，並採用可重複使用和可回收的包材；中國也於 2020 年決定一次性餐具和其他用品逐步淘汰塑膠。

https://technews.tw/2022/11/08/sony-plastic-packaging/$wr$, $wr$郁庭：商業思維學院院長暨創辦人游舒帆在他的部落格上分享，要培養同理心與換位思考能力時，可以掌握 3 個步驟。

步驟 1：培養傾聽的軟技能。包括練習在跟他人交流時，適當地提問、認真感受、不馬上批評等，都是在培養換位思考能力時，可以先掌握的技巧。

步驟 2：累積經驗。他認為，當自己跟他人有相同的經驗時，往往會比較容易理解對方的處境，也更具有同理心。好比在一間公司裡，同部門的人通常較少吵架，同樣職能的人，也較少有衝突，就是因為彼此的工作經驗相似，在碰到困難時，通常比較能互相包容。

步驟 3：拓展知識。他指出，當自己具備跟對方溝通的共同知識時，通常在互動上會比較順利。在公司裡，面對不同職能或是部門的同事，如果能夠懂一些對方的工作內容，就比較能理解他之所以提出某些需求背後的原因。

怡芳、振慈、瑩如：… 溝通談判, 其中運用人格特質來分析我們的談判方式, 在遇到不同的對象的時候要使用不同的談判方式, 若遇到不是我們的風格時也不是要我們改成我們不擅長的方式去談判, 而是可以換不同的人去談判, 這就是一個 team, 我們全公司就是一個 team, 每個人有每個人的角色也有擅長的部分, 當公司專案遇到什麼問題時, 熟悉擅長的人就應該跳出來接球, 而非拘泥於這並非我們部門的問題, 請大家還是要打破部門的思維, 其他同事遇到困難時我們就應該跳出來, 大家是朝同一個目標（業績）在努力的, 既然已經多一小步服務了, 就應該打破部門的限制, 多付出必然會有正向的果, 多分享多吸收也是一種成長, 不要想這是小事或者這不重要, 往往魔鬼就在細節裡

文千：稻盛和夫在《心》中写道：「人生一切的不幸，没有别的原因，都是由自己的心灵吸引而来的，是无休止地倾诉不幸、牢骚不断的那颗心，唤来了不幸。」抱怨是一剂毒药，你抱怨越多，越会加剧恶化你的处境。当你止住了负能量的传递，调整好心态，才能于灰色浓雾之中发现一丝光亮，并顺着光亮走出阴霾。

鄧氏紅：世事沧海桑田，知识日新月异，我们不能有吃老本的思想，我们也没有多少老本可吃。要用发展的眼光去审视自我，要用与时俱进的素养去获得有形的翅膀。要自觉加强学习，提高工作本事。工作本事的提高，没有任何捷径可走，惟有靠刻苦学习，长期积累。深刻认识加强学习的极端重要性，增强学习的主动性和自觉性，树立终身学习的思想，把学习当作一种政治职责、一种精神追求，构成浓厚的学习风气，勤于学习，善于学习。不断掌握新知识，积累新经验，增长新本领，创造新业绩。「水惟善下方成海，山不矜高自极天」，虚心求教，学而不厌，是方向、是动力、是生命力！$wr$, $wr$台北的同事，請於每週週會時增加一個程序，週報分享時間，以抽籤的方式挑選 2 人，1 員做 Woody 週報讀後分享，一員針對自己的週報做分享。$wr$,
