       $wr$禹榮、紅卿：https://www.bella.tw/articles/news/37826

Pantone 2023 年度代表色公布！「Viva Magenta」充滿活力、傳遞勇敢無畏訊號的洋紅色彩

Pantone 今日公布了 2023 年度代表色「Viva Magenta」，是一種源自紅色家族系列的自然色調，展現了我們希望邁入新一年時所感受到的韌性、樂觀與創造力。「Viva Magenta」介於紅與紫色之間，是充滿活力熱情、勇敢無畏且激勵人心的洋紅色彩，同樣是被認為最符合當前後疫情時代，予人希望並展現新生力量，並且適用於真實與虛擬世界的新時代色彩。

過去兩年，COVID-19 疫情席捲全球，人類面臨死亡、孤立以及社會動盪。但隨著 2023 年即將到來，疫情逐漸趨緩，或者至少人們已經準備好重新投入新生活當中，去彌補那些失去的時間。呼應這樣的世界脈動，以及對新一年的期待，Pantone 將 2023 年度代表色定為「Viva Magenta」，傳達純粹的喜悅，鼓勵人們無拘無束地進行實驗與自我表達，是一款令人振奮的、無邊界的色調，充滿大膽、智慧以及包容精神。

Pantone 提到，「Viva Magenta」的部分靈感其實是來自於一隻不起眼的「胭脂蟲」。其是一種 0.2 英寸長的甲蟲，原產於美州，外表呈現醒目的紅色，與棲息地中顏色相似的花朵和水果融為一體。經歷千年，許多物種早已滅絕，但胭脂蟲卻存活了下來，頑強地向世界展現如此美麗的色彩，Pantone 色彩研究所副總裁 Laurie Pressman 表示，那堅硬的外殼其實也展示了我們多數人在過去兩年中所獲得的勇敢與無畏。

不僅如此，早在公元前二世紀，人們便在織物和紙張上注入如此豐富耀眼的紅色調，「Viva Magenta」是天然染料中相當珍貴的染料之一，也是世界上已知最濃烈、最明亮的染料之一。有趣的是，「Viva Magenta」色彩如此豐富飽滿，以至於看起來像是人工調出的顏色，但其實是汲取於自然界中的顏色。

「Viva Magenta」飽滿的色彩也經常被應用在線上遊戲等虛擬世界中，因而該色彩也被 Pantone 定義為適用於真實與虛擬世界的新時代色彩，有助於幫助探索這兩個世界間的關係。

Pantone 每年到 12 月便會宣布隔年的代表色，繼 2019 年「活珊瑚橘」、2020 年「經典藍」、2021 年帶來韌性與希望的「極致灰」和「亮麗黃」雙色，和 2022 年展現內在自信和大膽好奇心的「長春花藍」後，2023 年度代表色定為「Viva Magenta」，希望透過充滿活力、韌性的洋紅，讓人們在全新一年無拘無束地進行探索和自我表達，令人充滿振奮也喚起自然的力量，激發人們想跳脫框架的精神，並在這個紛亂時刻重拾內在力量。$wr$, $wr$福威：你多學一項本事，就少說一句求人的話。人總要找點事情做，讓自己忙起來，忙起來才知道生活的不易，才明白平時的憂傷都是矯情。

→ 不能同意更多，有時間抱怨或八卦的，不如去學些新的東西，人生才會充實

湘芸：本週週會分享提到我們必須努力學習才能使自己不被淘汰，不進則退，這是終身學習的概念。終身學習意即隨時保持對新事物的好奇心與求知欲，並且不斷學習新知、習得新技能。單一領域的專業知識與技能會不斷更新，過去所學的知識或技能，很可能無法適用於未來的工作，所以多面向的學習是必要的。在我們公司內，也很強調學習的重要性，過往舉行過的讀書會、各種顧問的分享會、商業模式討論、產品加工分享…等都是在增強我們的知識技能。要成為「通才」很難，但跨領域的橫向學習是必要的，如此才能使自己的知識技能能靈活地跨領域發揮。

佳鈴：「感恩」是一種人生態度，它讓一個人珍惜自己所有，並對此滿足且充滿感激。懂得感恩的人能看見別人對自己的愛，學會珍惜一切，並將感恩的心轉化為能量和動力。真正的感恩，就是不將一切視為理所當然，是付出大於給予。

→ 是的，先懂感恩，自然就懂的利他。

燕婷：古语云：「博观而约取，厚积而薄发。」世界千变万化，只有终身学习，才能不断提升自己，未来的路才能越走越宽。有时，困扰我们的不是事情本身，而是认知的局限。固执己见的人，不愿意接受新的事物，活在自己的世界里，长此以往，他的格局会越来越小。只有不断提升自己，强大认知，才能终身受益。

