・北醫大產學合作拜訪
・寶可齡合作討論$wr$, $wr$本週，可欣分享了「靠譜」跟「閉環」兩個概念，本週週報收到了廣大的迴響，有七八位夥伴對此深表認同，並發表了觀點。我曾說過，我個人認為，對我最高的評價就是：「這是一個靠譜的人」。要成為靠譜的人，這件事情跟能力關聯其實不大，但努力認真是不可少的，也要有對事件掌控的能力，將當責三件事養成習慣，「凡是有交代、件件有著落、事事有回音」，隨時將重點回報團隊，若等到主管跟協同工作者來詢問狀況，就已經不太靠譜了。

湄涵：一同仁分享閉環的概念，是當一個靠譜的人很重要的工作方法，有一篇文章說，見過最高級的聰明，是靠譜，做事有首尾，做人有擔當，誇讚工作者的詞很多，無非是能力強、聰明、自律等等，但是聰明的人很多，靠譜的人卻很難得，因為比起能力更重要的是對工作的態度，靠譜體現在一些細節，每次靠譜的行為，就是累積社交信用，是最好的個人品牌，能持續給人帶來價值感，讓人放心合作，也能帶來更多機會。

惠卿：靠譜其實就是做事有始有終，腳踏實地，而且還要持續不斷的堅持下去。道理其實都很簡單，同仁分享那麼多次大家知道也明白怎麼做，但是差別就是願不願意開始去執行，讓靠譜成為自己的一種習慣。$wr$,
       $wr$怡芳：

在全球減碳的風氣下，各大車廠都在研發電動車（Electric Vehicle，EV），媒體也常討論電動車的未來，其中又分為電動車、純電動車（BEV）、油電混合車（HEV）、插電式混合動力車（PHEV）等，有何不同？哪個是真的比較環保？哪個其實仍是以內燃機為主要動力？

全文請見連結：https://www.managertoday.com.tw/eightylife/article/view/1386$wr$, $wr$瑩如：週會同仁分享靠譜的人是善於閉環管理的，靠譜是一種習慣的養成，而不是一個口號，需要在日常工作或生活中，時刻提醒自己。「凡事有交代，件件有著落，事事有迴音」交代的事一定會放在心上，盡心盡力，並隨時反饋，即便出了問題，也能及時補救。連接越多，能及早意識困難點，主動去找資源，想辦法解決，價值就越大，不給協作者帶來風險，這是靠譜的回報。有始有終的閉環，是職場與生活的一份智慧。

可欣：「壓力好大！」是上班族常說的話，但其實壓力的好壞？取決自己的態度！簡單來說，就是我們看待壓力的「心態」，會決定我們的身心健康和工作表現。若是看待壓力的心態，是用正面且積極的方式面對時，可以降低自己焦慮或憂鬱的程度，相對的就也會提升我們的專注力、生產力和配合度。健康心理學家麥高尼格指出「管理壓力的最佳做法，並不是盡可能擺脫壓力，而是重新思考壓力的作用，甚至積極擁抱壓力，這會讓自己感覺更有力量。」學會把壓力視為一種成長、學習，或變得更堅強的機會時，讓壓力從敵人變成朋友並成為我們人生中每個重要的轉捩點。

于嵐：我們現在社群行銷企劃實施了四個月以來，粉絲團的活躍程度越來越好，歡迎全公司同事多按讚分享，也可以跟我們分享想分享的事情，以及公司最近發生的大小事情，這些我們都可以 PO 在社群上告知我們的粉絲們。

