・新產品開案討論$wr$, $wr$本週，慶鐘分享了這個議題，「汝無面從，退有後言」，這個回饋很好，我補充一下，做為反對一方，消極配合也是不好的，既然是民主的決議，就應當要當作是自己的決策，不妨回頭想想，OKR 的精神是什麼，既然是一個團隊一個目標，就必須放下自我，我知道不容易，但是這是成熟的民主精神表現。

慶鐘：《尚書》云：汝無面從，退有後言。意思是說表面順從答應，卻在背後進行非議。一個組織進行一項指令或政策時，通常都會經過公開、透明、民主的方式開會討論，一旦達成共識。就應該以多數人覺得可行且有利於組織進程的方案全力去執行，如果做為反對一方，縱然是消極配合。但也決不要表面順從，背後非議，進而造成組織的傷害。

補充一下何飛鵬先生的文章：何飛鵬：汝無面從，退有後言（商場自慢塾，出刊日期：2012-06-14）

辦雜誌、做出版，最重視就是時間，準時截稿、準時出書是無限上綱，誰都不可以違背。因此我一向要求時間第一，無論如何要準時。但有些主管還有質疑，如果內容品質不好，也可以為了準時，閉著眼睛出書嗎？

我的回答是：何謂品質不好？是低於六十分的最低及格標準嗎？那當然不行，但只要在六十分以上，都要以準時為第一優先。因為雜誌每期都要出，準時之後，就可以徐圖進取，逐漸進步。這是我辦雜誌的原則。用系統化尋求最低品質，準時出書，再逐步雕琢內容，提升讀者滿意度。

可是永遠有主管會有不同的想法。一位年輕的主管經常以品質為由，拖延出書，我雖愛才，但此事觸犯我的經營原則，我不得不開鍘處罰。沒想到我事後聽到的說法是：此位主管竟甘之如飴，「要我犧牲品質，達成準時出書，我做不到！」一副我不入地獄，誰入地獄的態度。

我忍住脾氣，找來這位年輕主管，告訴他在態度上犯了全天下老闆都不可原諒的錯誤，這種錯誤叫：「汝無面從，退有後言」。

這八個字出於《尚書》，意思是：你表面順從答應，但卻背後進行非議。而這位年輕主管錯誤更重，因為不只是背後非議，更採取完全不同的做法。

我告訴他，我可以容許公開討論，不一定要按照我的意思做，但是如果沒有不同的意見，那就要徹底執行。如果一時無法執行，也要限期改善。絕對不可以在背後有不同的說法、不同的做法，這不但違背職場工作倫理，對公司、對老闆，更是一種形式的「背叛」。說「背叛」太嚴重，但對我而言，這確實是我認定的「背叛」。

公開、透明、民主是我一向信仰的組織精神。不只是公司政策，就算是我的指令，我也都允許討論，讓大家有公開表示意見的機會；達成共識後，才能有效推動。就算有些事無法讓所有人都同意，我也會盡可能尋求反對者的諒解，期望不要用威權迫使大家遵守。可是一旦做成決議，就不能有任何模糊的空間。

而一個工作者對老闆的指令，只要是明確而不可更動的指令，就只能主動配合執行，與被動配合兩種做法。但絕不可表面順從，背後非議。

我把「背後非議」視為背叛，主要是因為表面的面從是不可原諒的誤導，有意見不說卻選擇靜默，不論任何原因都是不忠實的表現。當面表示反對，反對不成，事後消極配合，對這種員工，我都還能理解、諒解，因為他們至少表裡如一。

「汝無面從，退有後言」，是職場中最不可原諒的錯誤，對不認同的指令，不積極執行就算了，絕不可在背後說反話。$wr$,
