湄涵：週一同仁分享內容中提到刺蝟原則，哲學家以賽亞‧柏林（Isaiah Berlin）從中把人分成狐狸與刺蝟。狐狸型的人習慣一心多用，從不把想法整合成整體概念；刺蝟型總把複雜的世界單純化，歸總出單一系統或基本原則。管理學大師吉姆‧柯林斯（Jim Collins）在《從 A 到 A+》指出，刺蝟型的人因為擁有敏銳的洞察力，才能看穿繁複的萬物表象，找到潛藏在世界中的運作本質。於此基礎，柯林斯進一步整理出企業從優秀突破到卓越的刺蝟原則，由 3 個面相交集而成，分別是發掘能熱情投入的事業、藉由研究企業的經營模式，找出使公司獲利的關鍵原因、了解自己在哪些專長能達到世界頂尖，並始終如一的深耕。

秋妝：人生本就有很多的岔路，倘若迷了路并不是什么可怕的事情。但可怕的是，我们不主动的寻找那条出路，我们或许会抱怨没有合适的机会，会怨天尤人会妄自菲薄，甚至我们会变的满身戾气。

所以我们要记住：冠军可能会输，但不会低头抱怨。$wr$, $wr$台北的同事，請於每週週會時增加一個程序，週報分享時間，以抽籤的方式挑選 2 人，1 員做 Woody 週報讀後分享，一員針對自己的週報做分享。$wr$,
