這星期同仁提到公司流程要跑很久、流程麻煩等等，我不認同，建議同仁先送件，再追每一個簽核主管，系統流程是死的，可以想辦法，找主管協助、跨部門溝通、可以很多方式變通、達到想要的時間，任何問題都可以一起溝通協調，不能一直抱怨，這不行這不合理，我們存在的價值，共同創造價值。

=> Woody: 謝謝，正確，抱怨無法解決問題，我們需要的是能解決問題的人。此題剛好與可欣的本週分享有關連。

可欣的情報分享：沒人喜歡滿嘴不行的員工，試著解決問題

如果你抱持「我很努力準備報告了，主管應該會寬容大量，好好聽到最後」的想法，那不叫正當期待，而是「盲目的錯覺」。倘若你考量到他們的處境，就要注意一些部分。

提出問題並且叮囑組織必須盡快解決問題相當重要，但那是聽報告的人該做的事。你只要展現積極、正面努力解決自己業務上的問題的模樣，不，只要把解決方法好好寫進報告裡就可以了。如果有想要補充的部分，就以「建議事項」處理，這是上班族的寫作 sense。以前我的一位高階主管也經常告訴我，絕對不要放棄樂觀思考。

舉出 100 個不可能的理由很簡單，但上級想要聽的是「一個可行的理由」。就算有眾多不可能，總會有人做出成果，而公司就是想要找那個人。

我們要把「我會這樣試著解決看看」的意志展現在報告裡，如果報告充滿「這個因為這樣不行，那個因為那樣不行」，沒人會喜歡這種員工。

你是一個「讓人想培養的人才」還是「爛梨子」，取決於你的內容有多少樂觀成分。記得別迷失在尋找不可能的理由中，要問問自己真的沒有辦法可行了嗎？倘若有一點可能性，就把它寫進報告中，這樣的人才是組織想要的，有寫作 sense 的人才。$wr$,
       $wr$政男：可持續發展 & 循環經濟的新世代塑膠材料（生質塑膠）
https://www.smartmolding.com/20-10b08/

生質塑膠

生質塑膠作為最為環保的解決方案，為世界降低能耗和碳排，且可以在現存的再循環系統中回收。首先，我們先來瞭解一下什麽是生質塑膠，生質塑膠可分為生物基塑膠（Biobased Plastics），可分解塑膠（Degradable Plastics）和生物可降解塑膠（Biodegradable Plastics）三大類，雖説目標一致為了保護環境，三種材料的概念可所謂是大相徑庭。

…$wr$, $wr$振慈：本周心得我自己分享了影響力習慣書裡的其中一篇文章，但其實我最有感的是，彎路才是價值所在之處，當我們遇到困難或是不容易解的難題時，才是顯現我們的價值的地方。一般人會把「計畫之外」的專案和「超出範圍」的工作，當成是對生產力的威脅，所以選擇避開。就像很多時候我們面對工作上新的職務或是任務，我們在面對的第一心態上就已經覺得排斥或是逃避，但是具有影響力的成員是會坦然面對接受，並且想著該如何完成，努力尋找資源、精進自己的能力、排除困難也要完成目標，這才是我們有價值的地方，也是我們該學習調整之處。

紹軍：曾國藩說：「天下事，在局外吶喊議論，總是無益，必須躬身入局，挺膺負責，方有成事之可冀。」躬身入局是一種做事的態度。就如本週分享的五種影響力心態，除了份內工作，也必須在碰到沒人負責的「灰色地帶」，會挺身而出解決問題，達成團隊目標。

瑩如：本週週會提到公司資產維護問題，運用在日常工作事務上也是相同的道理，當發現問題的人，都能主動站出來提出問題、解決問題，不拘泥於某人或某部門才能處理，打破既有的工作框架，主動做需要做的事，會讓點與點的連結更加順暢，這是每個工作者都具應備的能力。

淑婷：周會提出的公共設備維護，我想到的是之前當責也有說到當我們帶著共同責任的態度去看待公司的所有事情時，邊界的隙縫就會消失，每個人都會覺得是自己的責任。所以不管是否與工作有關的事，我們都應有良好正面積極的當責態度及行為，以自己為出發點主動積極向外擴散，影響他人，產生良好的感染力。$wr$, $wr$大家聖誕快樂！

